const VARIANT_GENERATORS=[
  {match:q=>q.concept==='サブネット',gen:genSubnet},
  {match:q=>q.concept==='SQL',gen:genSqlWhere},
  {match:q=>q.concept==='SQL集約',gen:genSqlAggregate},
  {match:q=>q.concept==='論理演算',gen:genLogic},
  {match:q=>q.concept==='公開鍵暗号',gen:genPublicKeyCrypto},
  {match:q=>q.concept==='共通鍵暗号',gen:genSymmetricCrypto},
  {match:q=>q.concept==='デジタル署名',gen:genDigitalSignature},
  {match:q=>q.concept==='損益分岐点',gen:genBreakEven},
  {match:q=>q.concept==='基数変換',gen:genBaseConversion},
  {match:q=>q.concept==='16進数',gen:genHexConversion},
  {match:q=>q.concept==='信頼性',gen:genReliability},
  {match:q=>q.concept==='画像データ量',gen:genImageSize},
  {match:q=>q.concept==='財務',gen:genGrossProfit},
  {match:q=>q.concept==='キュー',gen:genQueue},
  {match:q=>q.concept==='スタック',gen:genStack},
  {match:q=>q.concept==='条件分岐',gen:genConditional},
  {match:q=>q.concept==='集合',gen:genSetIntersection},
  {match:q=>q.concept==='スループット',gen:genThroughput}
];
function generatorFor(q){return VARIANT_GENERATORS.find(x=>x.match(q))?.gen||null;}
function hasVariant(q){return !!generatorFor(q);}
function generateVariant(q){
  const g=generatorFor(q);
  if(!g)return null;
  try{
    const v=g(q);
    if(!v||!Array.isArray(v.options)||v.options.length!==4||v.a<0||v.a>3||v.options[v.a]==null)return null;
    return v;
  }catch(e){console.warn('variant generation failed',q.id,e);return null;}
}
function siblingVariant(q){
  const lessonId=lessonForQuestion(q);
  const sameLesson=lessonId?QUESTION_BANK.filter(x=>x.id!==q.id && lessonForQuestion(x)===lessonId):[];
  const sameConcept=QUESTION_BANK.filter(x=>x.id!==q.id && x.concept===q.concept);
  const pool=sameLesson.length?sameLesson:sameConcept;
  if(!pool.length) return null;
  const picked=shuffledCopy(pool)[0];
  return {...picked,id:variantId(q.id),sourceId:q.sourceId||q.id,variant:true,variantSibling:true};
}
function buildReviewItem(q){
  if(profile.settings.variantReview===false)return q;
  return generateVariant(q)||siblingVariant(q)||q;
}
function variantCoverage(){
  const direct=QUESTION_BANK.filter(hasVariant).length,total=QUESTION_BANK.length;
  const concepts=[...new Set(QUESTION_BANK.filter(hasVariant).map(q=>q.concept))].length;
  return {direct,total,concepts};
}
function validateGeneratedVariants(){
  let count=0;
  for(const base of QUESTION_BANK.filter(hasVariant)){
    for(let i=0;i<8;i++){
      const q=generateVariant(base);
      if(!q||q.options.length!==4||q.a<0||q.a>3||q.options[q.a]==null)throw new Error('invalid variant '+base.id);
      if(q.sourceId!==base.id)throw new Error('source mismatch '+base.id);
      count++;
    }
  }
  return count;
}



const CORE_A_DIFFICULTY_LEVELS=['基礎','標準','実戦'];
const CORE_A_DIFFICULTY_RANK={'基礎':0,'標準':1,'実戦':2};

function coreChapterDifficultyTarget(pool){
  const available=CORE_A_DIFFICULTY_LEVELS.reduce((a,k)=>(a[k]=pool.filter(q=>q.difficulty===k).length,a),{});
  const target={'基礎':0,'標準':0,'実戦':0};
  let left=12;

  // 章末は「思い出す」より「使う・見分ける」を重視する。
  target['実戦']=Math.min(5,available['実戦']||0,left);left-=target['実戦'];
  target['基礎']=Math.min(1,available['基礎']||0,left);left-=target['基礎'];
  target['標準']=Math.min(left,available['標準']||0);left-=target['標準'];

  // 小章などで一つの難易度が不足する場合だけ、残りを他の層から補う。
  for(const level of ['実戦','標準','基礎']){
    if(left<=0)break;
    const spare=Math.max(0,(available[level]||0)-target[level]);
    const add=Math.min(left,spare);
    target[level]+=add;left-=add;
  }
  return target;
}
function coreChapterQuestionRichness(q){
  if(String(q.id||'').startsWith('challenge_cmp_'))return 100;
  const score={comparison:95,calculation:90,scenario:82,interpretation:76,trace:76,discrimination:72,application:64,knowledge:30};
  return score[q.angle]||45;
}
function coreChapterQuestionNovelty(q){
  const attempts=(typeof profile!=='undefined'&&profile.qStats?.[q.id]?.attempts)||0;
  return attempts===0?24:0;
}
function buildCoreChapterQuiz(ch){
  const topics=CORE_A_CURRICULUM.filter(t=>t.chapter===ch);
  const ids=topics.map(t=>t.id);
  const chapterExtras=CORE_A_CHAPTER_EXTRA_QUESTIONS[ch]||[];
  const pool=[...QUESTION_BANK.filter(q=>q.coreTopicId&&ids.includes(q.coreTopicId)),...chapterExtras];
  const target=coreChapterDifficultyTarget(pool);
  const out=[],used=new Set(),topicCounts={},levelCounts={'基礎':0,'標準':0,'実戦':0};

  const canUse=q=>q&&!used.has(q.id)&&(levelCounts[q.difficulty]||0)<(target[q.difficulty]||0);
  const add=q=>{
    if(!q||used.has(q.id))return false;
    out.push(q);used.add(q.id);
    if(q.coreTopicId)topicCounts[q.coreTopicId]=(topicCounts[q.coreTopicId]||0)+1;
    levelCounts[q.difficulty]=(levelCounts[q.difficulty]||0)+1;
    return true;
  };
  const best=(candidates,preferUncovered=false)=>{
    const list=shuffled(candidates.filter(canUse));
    list.sort((a,b)=>{
      const ac=topicCounts[a.coreTopicId]||0,bc=topicCounts[b.coreTopicId]||0;
      if(preferUncovered&&((ac===0)!==(bc===0)))return ac===0?-1:1;
      if(ac!==bc)return ac-bc;
      return (coreChapterQuestionRichness(b)+coreChapterQuestionNovelty(b))-(coreChapterQuestionRichness(a)+coreChapterQuestionNovelty(a));
    });
    return list[0]||null;
  };

  // 1) 章末らしい「近い概念の見分け」を最大3問、存在する範囲で優先確保。
  const comparisons=pool.filter(q=>String(q.id||'').startsWith('challenge_cmp_')||q.angle==='comparison');
  const comparisonGoal=Math.min(3,comparisons.length,Math.max(1,(target['実戦']||0)));
  for(let i=0;i<comparisonGoal;i++){
    const q=best(comparisons,true);
    if(!q)break;
    add(q);
  }

  // 2) 計算テーマがある章では、公式を思い出すだけでなく実際に使う問題を最低1問入れる。
  const calculations=pool.filter(q=>q.angle==='calculation');
  if(calculations.length&&!out.some(q=>q.angle==='calculation')){
    const q=best(calculations,true);
    if(q)add(q);
  }

  // 3) その章の全テーマを最低1回は扱う。
  //    実戦→標準を優先し、基礎1問は最後の確認用に残す。
  const remainingTopics=shuffled(topics.filter(t=>(topicCounts[t.id]||0)===0));
  for(const t of remainingTopics){
    const same=pool.filter(q=>q.coreTopicId===t.id&&!used.has(q.id));
    let q=null;
    for(const level of ['実戦','標準','基礎']){
      if((levelCounts[level]||0)>=(target[level]||0))continue;
      q=best(same.filter(x=>x.difficulty===level));
      if(q)break;
    }
    if(!q){
      q=shuffled(same).sort((a,b)=>coreChapterQuestionRichness(b)-coreChapterQuestionRichness(a))[0]||null;
    }
    add(q);
  }

  // 4) 残りは難易度目標を満たしつつ、同じテーマへの偏りを最小化。
  for(const level of ['実戦','標準','基礎']){
    while((levelCounts[level]||0)<(target[level]||0)&&out.length<12){
      const q=best(pool.filter(x=>x.difficulty===level));
      if(!q)break;
      add(q);
    }
  }

  // 5) 想定外の不足時だけ、未使用問題から補う。
  while(out.length<12){
    const rest=shuffled(pool.filter(q=>!used.has(q.id))).sort((a,b)=>{
      const ac=topicCounts[a.coreTopicId]||0,bc=topicCounts[b.coreTopicId]||0;
      if(ac!==bc)return ac-bc;
      return (coreChapterQuestionRichness(b)+coreChapterQuestionNovelty(b))-(coreChapterQuestionRichness(a)+coreChapterQuestionNovelty(a));
    });
    if(!rest.length)break;
    add(rest[0]);
  }
  return shuffled(out.slice(0,12));
}
function coreChapterQuizAudit(ch,items){
  const topics=CORE_A_CURRICULUM.filter(t=>t.chapter===ch);
  const poolIds=new Set(topics.map(t=>t.id));
  const topicCounts={};
  (items||[]).forEach(q=>{
    if(q.coreTopicId&&poolIds.has(q.coreTopicId))topicCounts[q.coreTopicId]=(topicCounts[q.coreTopicId]||0)+1;
  });
  const comparisons=(items||[]).filter(q=>String(q.id||'').startsWith('challenge_cmp_')||q.angle==='comparison').length;
  const calculations=(items||[]).filter(q=>q.angle==='calculation').length;
  const difficulty=CORE_A_DIFFICULTY_LEVELS.reduce((a,k)=>(a[k]=(items||[]).filter(q=>q.difficulty===k).length,a),{});
  return {
    total:(items||[]).length,
    covered:topics.filter(t=>(topicCounts[t.id]||0)>0).length,
    topicTotal:topics.length,
    maxPerTopic:Math.max(0,...Object.values(topicCounts)),
    comparisons,calculations,difficulty
  };
}


function subjectATrackedMetadataV376(){
  const extras=Object.values(CORE_A_CHAPTER_EXTRA_QUESTIONS||{}).flat();
  return [...QUESTION_BANK,...extras];
}
function subjectAUniqueMetadataV376(items,n=20){
  const out=[],seen=new Set();
  const limit=Math.max(1,Math.min(20,Number(n)||1));
  for(const item of items||[]){
    if(!item||typeof item.id!=='string'||seen.has(item.id))continue;
    seen.add(item.id);out.push(item);
    if(out.length>=limit)break;
  }
  return out;
}
function subjectAStatV376(item){return profile.qStats?.[item?.id]||{};}
function subjectAIsDueMetadataV376(item){
  const stat=subjectAStatV376(item),due=typeof stat.due==='string'?stat.due:'';
  const today=typeof localDateISO==='function'?localDateISO(0):new Date().toISOString().slice(0,10);
  if(!due||due>today)return false;
  return typeof questionHasActiveJourney==='function'?!questionHasActiveJourney(item.id):true;
}
function subjectAMetadataWeakScoreV376(item){
  const stat=subjectAStatV376(item),attempts=Number(stat.attempts)||0,correct=Number(stat.correct)||0;
  const accuracy=attempts?Math.max(0,Math.min(1,correct/attempts)):.5;
  const skill=Number(profile.skills?.[item?.cat]??60);
  const dueBonus=subjectAIsDueMetadataV376(item)?35:0;
  const cognitiveBonus=item?.cognitiveLevel==='判断'?6:item?.cognitiveLevel==='適用'?3:0;
  return (100-skill)+(1-accuracy)*40+dueBonus+cognitiveBonus;
}
function subjectAPickWeakMetadataV376(pool,n){
  return subjectAUniqueMetadataV376([...(pool||[])].sort((a,b)=>subjectAMetadataWeakScoreV376(b)-subjectAMetadataWeakScoreV376(a)||Math.random()-.5),n);
}
function subjectAPickDueMetadataV376(pool,n){
  const due=(pool||[]).filter(subjectAIsDueMetadataV376).sort((a,b)=>{
    const ad=String(subjectAStatV376(a).due||''),bd=String(subjectAStatV376(b).due||'');
    return ad.localeCompare(bd)||subjectAMetadataWeakScoreV376(b)-subjectAMetadataWeakScoreV376(a);
  });
  return subjectAUniqueMetadataV376(due,n);
}
function subjectAPickBalancedMetadataV376(pool,n){
  const groups=new Map();
  for(const item of pool||[]){
    const key=String(item?.cat||'その他');
    if(!groups.has(key))groups.set(key,[]);
    groups.get(key).push(item);
  }
  for(const items of groups.values())items.sort(()=>Math.random()-.5);
  const keys=[...groups.keys()].sort(()=>Math.random()-.5),out=[];
  let round=0;
  while(out.length<n&&keys.length){
    let added=false;
    for(const key of keys){
      const item=groups.get(key)?.[round];
      if(item){out.push(item);added=true;if(out.length>=n)break;}
    }
    if(!added)break;
    round++;
  }
  return subjectAUniqueMetadataV376(out,n);
}
function subjectAPickWarmupMetadataV376(pool,n){
  const attempted=(pool||[]).filter(item=>(Number(subjectAStatV376(item).attempts)||0)>0);
  const source=attempted.length?attempted:pool||[];
  const cognitive={'想起':0,'適用':1,'判断':2},difficulty={'基礎':0,'標準':1,'実戦':2};
  return subjectAUniqueMetadataV376([...source].sort((a,b)=>
    (cognitive[a?.cognitiveLevel]??2)-(cognitive[b?.cognitiveLevel]??2)||
    (difficulty[a?.difficulty]??1)-(difficulty[b?.difficulty]??1)||Math.random()-.5
  ),n);
}
function subjectAPickHardMetadataV376(pool,n){
  const cognitive={'想起':0,'適用':1,'判断':2},difficulty={'基礎':0,'標準':1,'実戦':2};
  return subjectAUniqueMetadataV376([...(pool||[])].sort((a,b)=>
    (cognitive[b?.cognitiveLevel]??1)-(cognitive[a?.cognitiveLevel]??1)||
    (difficulty[b?.difficulty]??1)-(difficulty[a?.difficulty]??1)||
    subjectAMetadataWeakScoreV376(b)-subjectAMetadataWeakScoreV376(a)
  ),n);
}
function subjectAPickRxMetadataV376(mode,pool){
  const parts=String(mode).split(':'),kind=parts[1]||'knowledge',cat=parts.slice(2).join(':');
  const same=cat?(pool||[]).filter(item=>item.cat===cat):[...(pool||[])];
  let preferred=[];
  if(kind==='calc')preferred=same.filter(item=>item.angle==='calculation');
  else if(kind==='read')preferred=same.filter(item=>['interpretation','scenario','discrimination'].includes(item.angle));
  else if(kind==='contrast')preferred=same.filter(item=>['comparison','discrimination'].includes(item.angle));
  else if(kind==='repeat')preferred=same.filter(item=>{
    const stat=subjectAStatV376(item);return (Number(stat.attempts)||0)>(Number(stat.correct)||0);
  });
  else if(kind==='knowledge')preferred=same.filter(item=>item.angle==='knowledge'||item.cognitiveLevel==='想起');
  else preferred=same;
  const count=kind==='speed'?10:8;
  return subjectAUniqueMetadataV376([...preferred.sort(()=>Math.random()-.5),...same.sort(()=>Math.random()-.5)],count);
}
function selectSubjectAMetadataV376(mode){
  const key=String(mode||'random'),bank=[...QUESTION_BANK],tracked=subjectATrackedMetadataV376();
  if(key.startsWith('budget:')){
    const task=globalThis.studyActiveV373?.task,n=Math.max(1,Math.min(20,Number(task?.questionLimit)||1));
    const active=globalThis.studyActiveV373;
    const saved=profile.dailyPlans?.[active?.date]?.blockProgressV373?.[task?.slot]?.remainingIds;
    if(Array.isArray(saved)){
      if(saved.length>20||new Set(saved).size!==saved.length)throw new Error('study_resume_ids_invalid');
      const byId=new Map(tracked.map(item=>[item.id,item]));
      if(saved.some(id=>typeof id!=='string'||!byId.has(id)))throw new Error('study_resume_question_missing');
      return saved.map(id=>byId.get(id));
    }
    if(task?.lane==='review'){
      const due=subjectAPickDueMetadataV376(tracked,n);return due.length?due:subjectAPickWeakMetadataV376(bank,n);
    }
    return subjectAPickWeakMetadataV376(bank,n);
  }
  if(key.startsWith('journey:')){
    const id=key.slice(8),item=tracked.find(question=>question.id===id);return item?[item]:[];
  }
  if(key.startsWith('coretopic:')){
    const topicId=key.slice(10),pool=bank.filter(item=>item.coreTopicId===topicId);
    const applied=pool.filter(item=>['application','scenario','calculation','trace','interpretation'].includes(item.angle));
    return subjectAUniqueMetadataV376([...applied.sort(()=>Math.random()-.5),...pool.sort(()=>Math.random()-.5)],10);
  }
  if(key.startsWith('corechapter:')){
    const chapter=Number(key.slice(12));
    const topicIds=new Set((Array.isArray(CORE_A_CURRICULUM)?CORE_A_CURRICULUM:[]).filter(topic=>Number(topic.chapter)===chapter).map(topic=>topic.id));
    const chapterBase=bank.filter(item=>topicIds.has(item.coreTopicId));
    const extras=CORE_A_CHAPTER_EXTRA_QUESTIONS?.[String(chapter)]||[];
    return subjectAUniqueMetadataV376([...chapterBase.sort(()=>Math.random()-.5),...extras.sort(()=>Math.random()-.5)],10);
  }
  if(key==='warmup')return subjectAPickWarmupMetadataV376(bank,3);
  if(key==='taperreview'){
    const due=subjectAPickDueMetadataV376(tracked,5);return due.length>=5?due:subjectAUniqueMetadataV376([...due,...subjectAPickWarmupMetadataV376(bank,5)],5);
  }
  if(key==='review'){
    const due=subjectAPickDueMetadataV376(tracked,10);return due.length?due:subjectAPickWeakMetadataV376(bank,5);
  }
  if(key==='weak')return subjectAPickWeakMetadataV376(bank,10);
  if(key==='boss')return subjectAPickHardMetadataV376(bank,5);
  if(key.startsWith('cogcat:')){
    const [,cat,level]=key.split(':');return subjectAUniqueMetadataV376(bank.filter(item=>item.cat===cat&&item.cognitiveLevel===level).sort(()=>Math.random()-.5),10);
  }
  if(key.startsWith('cat:'))return subjectAUniqueMetadataV376(bank.filter(item=>item.cat===key.slice(4)).sort(()=>Math.random()-.5),10);
  if(key.startsWith('rx:'))return subjectAPickRxMetadataV376(key,bank);
  return subjectAPickBalancedMetadataV376(bank,10);
}

async function startQuiz(mode){
  ensureQuestionProfile();
  quizMode=mode;
  quizItems=selectSubjectAMetadataV376(mode);
  quizIndex=0;
  quizSelected=null;
  quizAnswered=false;
  quizCorrectCount=0;
  quizWrongCount=0;
  quizEarnedXp=0;
  quizPickedReason=null;
  quizRecoveredCount=0;
  stopQuestionPacer();
  sessionLog=[];

  document.getElementById('problems')?.classList.add('exercise-session-active');
  problemHub.style.display='none';
  quizResultScreen.style.display='none';
  quizSession.style.display='block';

  const titles={review:'今日の復習',taperreview:'直前復習 5問',warmup:'受験前ウォームアップ 3問',weak:'弱点10問',random:'ランダム10問',boss:'今日の総合チェック'};
  const modeTitle=String(mode).startsWith('journey:')
    ?'復習ルート・類題確認'
    :String(mode).startsWith('coretopic:')
      ?`${CORE_A_TOPIC_MAP[String(mode).slice(10)]?.title||'テーマ'}・テーマ演習`
      :String(mode).startsWith('corechapter:')
        ?`第${String(mode).slice(12)}章・章末チェック`
        :String(mode).startsWith('cogcat:')
        ?`${String(mode).split(':')[1]}・${String(mode).split(':')[2]} 集中特訓`
        :String(mode).startsWith('cat:')
          ?`${String(mode).slice(4)} 集中特訓`
        :String(mode).startsWith('rx:')
          ?prescriptionMeta(mode).title
          :titles[mode];
  document.getElementById('quizSessionTitle').textContent=modeTitle||'問題演習';
  document.getElementById('quizSessionSub').textContent=String(mode).startsWith('corechapter:')
    ?`科目A 章末統合演習・全${CORE_A_CURRICULUM.filter(t=>t.chapter===Number(String(mode).slice(12))).length}テーマ`
    :'科目A 問題演習';
  configurePrescriptionUI(mode);
  const bridge=globalThis.FEQUEST_V376_PROTECTED_FLOW;
  if(!bridge||typeof bridge.prepareSubjectA!=='function')throw new Error('v376_subject_a_bridge_missing');
  const loadingQuestion=document.getElementById('quizQuestion');
  const loadingOptions=document.getElementById('quizOptions');
  const loadingSubmit=document.getElementById('quizSubmit');
  if(loadingQuestion)loadingQuestion.textContent='問題を読み込み中…';
  if(loadingOptions)loadingOptions.innerHTML='';
  if(loadingSubmit)loadingSubmit.disabled=true;
  try{
    quizItems=await bridge.prepareSubjectA(quizItems);
  }catch(error){
    bridge.reportSubjectAError?.(error);
    problemHub.style.display='block';
    quizSession.style.display='none';
    if(loadingSubmit)loadingSubmit.disabled=false;
    return false;
  }
  renderQuizQuestion();
  return true;
  requestAnimationFrame(()=>document.getElementById('quizSession')?.scrollIntoView({block:'start',behavior:'auto'}));
}

document.querySelectorAll('.problem-mode button[data-mode]').forEach(b=>{
  b.addEventListener('click',()=>startQuiz(b.dataset.mode));
});

function renderQuizQuestion(){
  const q=quizItems[quizIndex];
  quizSelected=null;
  quizAnswered=false;
  quizPickedReason=null;
  quizRetryCount=0;
  quizFirstAttemptWrong=false;
  rxTechniqueReady=true;
  rxTechniqueData={};
  stopQuestionPacer();
  quizQuestionStartedAt=Date.now();
  quizFirstAttemptSeconds=0;

  document.getElementById('quizCategory').textContent=`${q.cat}・${q.concept}`;
  const angleNames={knowledge:'知識',application:'適用例',discrimination:'見分け',calculation:'計算',scenario:'状況判断',interpretation:'読解',trace:'操作追跡',comparison:'比較'};
  document.getElementById('quizDifficulty').textContent=q.angle?`${q.difficulty}・${angleNames[q.angle]||q.angle}`:q.difficulty;
  document.getElementById('quizQuestion').textContent=q.q;
  const vb=document.getElementById('variantBadge');
  if(vb){
    vb.style.display=q.variant?'inline-block':'none';
    vb.textContent=q.variantSibling?'関連問題復習':'バリエーション復習';
  }
  document.getElementById('quizCounter').textContent=`${quizIndex+1} / ${quizItems.length}`;
  document.getElementById('quizProgress').style.width=`${(quizIndex/quizItems.length)*100}%`;
  const quizExplain=document.getElementById('quizExplain');
  quizExplain.classList.remove('show');
  quizExplain.style.height='auto';
  quizExplain.style.minHeight='0';
  quizExplain.querySelectorAll('.memory-next-note,.variant-source-note,.retry-note,.review-route-inline').forEach(x=>x.remove());
  document.getElementById('quizResultTitle').textContent='';
  document.getElementById('quizExplanation').textContent='';
  document.getElementById('quizHint').textContent='';
  document.getElementById('reasonBox').classList.remove('show');
  document.getElementById('quizSubmit').textContent='回答する';
  document.getElementById('quizSubmit').disabled=false;
  document.getElementById('quizHintBtn').style.display='block';
  document.querySelector('.quiz-actions')?.classList.remove('single-primary');

  document.querySelectorAll('.reason-chip').forEach(c=>c.classList.remove('picked'));
  renderRxTechnique(q);

  const opts=document.getElementById('quizOptions');
  opts.innerHTML='';
  q.options.forEach((op,i)=>{
    const b=document.createElement('button');
    b.className='quiz-option';
    b.textContent=`${String.fromCharCode(65+i)}. ${op}`;
    b.addEventListener('click',()=>{
      if(quizAnswered) return;
      quizSelected=i;
      document.querySelectorAll('.quiz-option').forEach(x=>x.classList.remove('selected'));
      b.classList.add('selected');
    });
    opts.appendChild(b);
  });
}

document.getElementById('quizHintBtn')?.addEventListener('click',()=>{
  const q=quizItems[quizIndex];
  popToast(q.hint);
});

document.getElementById('quizSubmit')?.addEventListener('click',()=>{
  if(!quizAnswered){
    if(quizSelected===null){
      popToast('選択肢を1つ選んでください');
      return;
    }
    if(!validateRxTechniqueBeforeAnswer()) return;
    gradeCurrentQuestion();
  }else{
    if(quizIndex < quizItems.length-1){
      quizIndex++;
      renderQuizQuestion();
    }else{
      finishQuizSession();
    }
  }
});


function renderChoiceExplanations(q){
  const letters=['A','B','C','D'];
  const rows=(q.options||[]).map((op,i)=>({op,i})).filter(x=>x.i!==q.a).map(({op,i})=>{
    const reason=(q.choiceExps||[])[i]||'';
    return `<div class="choice-explanation is-wrong">
      <div class="choice-explanation-head">
        <span class="choice-mark">×</span>
        <b>${letters[i]}. ${escapeHtml(op)}</b>
      </div>
      <div class="choice-explanation-body">${learningHtml(reason)}</div>
    </div>`;
  }).join('');
  return `<div class="choice-explanations">
    <div class="choice-explanations-title">他の選択肢</div>
    ${rows}
  </div>`;
}
function renderFinalQuizExplanation(q){
  const root=document.getElementById('quizExplanation');
  if(!root)return;
  root.innerHTML=`
    <div class="answer-rationale">
      <div class="answer-rationale-title">正解の根拠</div>
      <div>${learningHtml(q.exp)}</div>
    </div>
    ${renderChoiceExplanations(q)}
  `;
}

function gradeCurrentQuestionLegacyV376(){
  const q=quizItems[quizIndex];
  const ok=quizSelected===q.a;
  const statId=q.sourceId||q.id;
  const st=profile.qStats[statId];
  const selectedNow=quizSelected;
  const attemptSeconds=Math.max(1,Math.round((Date.now()-quizQuestionStartedAt)/1000));

  // 通常演習ではすべて「初回誤答→ヒント→1回だけ再挑戦」に統一する。
  // v121: 誤答時はヒント本文だけを表示し、採点ルールやメタ説明は出さない。
  // 模試は別の試験UIなので、この関数を通らない。
  if(!ok && quizRetryCount===0){
    quizRetryCount=1;
    quizFirstAttemptWrong=true;
    quizWrongCount++;
    quizFirstAttemptSeconds=attemptSeconds;

    // 成績・正答率・忘却モデルへ入れるのは最初の回答だけ。
    st.attempts++;
    st.last=localDateISO(0);
    st.streak=0;
    adaptiveMemoryUpdate(st,'wrong',attemptSeconds,quizPickedReason,false);
    applyQuestionSkillDelta(q,-1);
    profile.xp+=2;
    registerReviewJourney(q,String(quizMode).startsWith('journey:')?'journey':'practice');
    saveProfile();

    const selectedBtn=document.querySelectorAll('.quiz-option')[selectedNow];
    if(selectedBtn){
      selectedBtn.classList.remove('selected');
      selectedBtn.classList.add('first-wrong');
      selectedBtn.disabled=true;
    }
    quizSelected=null;
    quizQuestionStartedAt=Date.now();

    document.getElementById('quizResultTitle').textContent='💡 ヒント';
    document.getElementById('quizExplanation').textContent=q.hint;
    document.getElementById('quizHint').textContent='';
    document.getElementById('quizExplain').classList.add('show');
    document.getElementById('quizHintBtn').style.display='none';
    document.querySelector('.quiz-actions')?.classList.add('single-primary');
    document.getElementById('quizSubmit').textContent='もう一度回答する';
    return;
  }

  quizAnswered=true;
  stopQuestionPacer();

  document.querySelectorAll('.quiz-option').forEach((btn,i)=>{
    btn.disabled=true;
    btn.classList.remove('selected','first-wrong');
    if(i===q.a) btn.classList.add('correct');
    else if(i===selectedNow && !ok) btn.classList.add('wrong');
  });

  const recovered=ok && quizFirstAttemptWrong;
  document.getElementById('quizResultTitle').textContent=recovered?'🔄 再挑戦で正解！':ok?'⭕ 正解！':'❌ 不正解';
  renderFinalQuizExplanation(q);
  const finalHint=(q.hint && !String(q.exp||'').includes(q.hint))?`確認ポイント：${q.hint}`:'';
  document.getElementById('quizHint').textContent=finalHint;
  document.getElementById('quizExplain').classList.add('show');
  document.getElementById('quizHintBtn').style.display='none';
  document.querySelector('.quiz-actions')?.classList.add('single-primary');

  const answerExplain=document.getElementById('quizExplain');
  answerExplain.querySelector('.variant-source-note')?.remove();
  answerExplain.querySelector('.review-route-inline')?.remove();
  answerExplain.querySelector('.memory-next-note')?.remove();
  const retryNote=answerExplain.querySelector('.retry-note');
  if(retryNote) retryNote.remove();

  if(!quizFirstAttemptWrong){
    // 初回正解だけが「正解」として正答率へ入る。
    quizCorrectCount++;
    quizEarnedXp+=10;
    st.attempts++;
    st.correct++;
    st.last=localDateISO(0);
    st.streak=(st.streak||0)+1;
    adaptiveMemoryUpdate(st,'correct',attemptSeconds,quizPickedReason,false);
    applyQuestionSkillDelta(q,1);
    profile.xp+=10;
  }else if(recovered){
    // 再挑戦成功は別指標。attempts/correctは増やさない。
    quizRecoveredCount++;
    st.recovered=(st.recovered||0)+1;
    st.streak=0;
    adaptiveMemoryUpdate(st,'recovered',quizFirstAttemptSeconds||attemptSeconds,quizPickedReason,true);
    applyQuestionSkillDelta(q,0.25);
    profile.xp+=5;
  }else{
    // 2回目も不正解でも、同じ問題を2回誤答として数えない。
    st.retryFailures=(st.retryFailures||0)+1;
  }

  // 最初に間違えた問題は、再挑戦で正解しても原因を記録できる。
  if(quizFirstAttemptWrong) document.getElementById('reasonBox').classList.add('show');

  if(String(quizMode).startsWith('journey:')){
    const jid=String(quizMode).slice(8);
    markJourneyAnswer(jid,!quizFirstAttemptWrong&&ok);
  }

  sessionLog.push({
    id:statId,variantId:q.variant?q.id:null,cat:q.cat,concept:q.concept,
    ok:!quizFirstAttemptWrong&&ok,
    recovered,
    retryFailed:quizFirstAttemptWrong&&!ok,
    seconds:quizFirstAttemptWrong?(quizFirstAttemptSeconds||attemptSeconds):attemptSeconds,
    nextDue:st.due,
    stability:st.stability,
    technique:String(quizMode).startsWith('rx:')?String(quizMode).split(':')[1]:null,
    techniqueData:safeTechniqueSnapshot()
  });

  // 誤答時は、答えを確認した直後に次の学習段階を見えるようにする。
  // v120: review journey is registered silently; surface it later, not inside the current question.

  saveProfile();
  document.getElementById('quizSubmit').textContent=
    quizIndex===quizItems.length-1 ? '結果を見る' : '次の問題 →';
  document.getElementById('quizProgress').style.width=`${((quizIndex+1)/quizItems.length)*100}%`;
}
async function gradeCurrentQuestion(){
  const q=quizItems[quizIndex];
  if(!q||quizSelected===null)return false;
  const bridge=globalThis.FEQUEST_V376_PROTECTED_FLOW;
  if(!bridge||typeof bridge.gradeSubjectA!=='function')throw new Error('v376_subject_a_bridge_missing');
  const selectedNow=quizSelected;
  const submit=document.getElementById('quizSubmit');
  const optionButtons=[...document.querySelectorAll('.quiz-option')];
  if(submit)submit.disabled=true;
  optionButtons.forEach(button=>button.disabled=true);
  try{
    const result=await bridge.gradeSubjectA(q,selectedNow);
    if(!result||!Number.isInteger(result.answerIndex)||typeof result.correct!=='boolean')throw new Error('subject_a_grade_result_invalid');
    q.a=result.answerIndex;
    q.exp=typeof result.explanation==='string'?result.explanation:'';
    q.choiceExps=Array.isArray(result.choiceExplanations)?[...result.choiceExplanations]:[];
    q.__v376PostSubmit=result.postSubmit&&typeof result.postSubmit==='object'?result.postSubmit:{};
    return gradeCurrentQuestionLegacyV376();
  }catch(error){
    bridge.reportSubjectAError?.(error);
    return false;
  }finally{
    delete q.a;
    delete q.exp;
    delete q.choiceExps;
    delete q.__v376PostSubmit;
    if(!quizAnswered){
      [...document.querySelectorAll('.quiz-option')].forEach(button=>{
        if(!button.classList.contains('first-wrong'))button.disabled=false;
      });
    }
    if(submit)submit.disabled=false;
  }
}


document.querySelectorAll('.reason-chip').forEach(chip=>{
  chip.addEventListener('click',()=>{
    document.querySelectorAll('.reason-chip').forEach(c=>c.classList.remove('picked'));
    chip.classList.add('picked');
    quizPickedReason=chip.dataset.reason;
    const q=quizItems[quizIndex];
    const statId=q.sourceId||q.id;
    if(profile.qStats[statId]){
      profile.qStats[statId].lastReason=quizPickedReason;
      saveProfile();
    }
  });
});

function finishQuizSession(){
  stopRxTimer();
  const total=quizItems.length;
  const rate=total?Math.round(quizCorrectCount/total*100):0;
  profile.sessions.unshift({
    date:localDateISO(0),
    mode:quizMode,
    total,
    correct:quizCorrectCount,
    rate,
    log:sessionLog.slice(0,10)
  });
  profile.sessions=profile.sessions.slice(0,20);
  profile.lastStudyDate=localDateISO(0);
  saveProfile();

  document.getElementById('problems')?.classList.add('exercise-session-active');
  quizSession.style.display='none';
  quizResultScreen.style.display='block';
  requestAnimationFrame(()=>quizResultScreen?.scrollIntoView({block:'start',behavior:'auto'}));

  document.getElementById('sessionScore').textContent=`${rate}%`;
  document.getElementById('sessionCorrect').textContent=quizCorrectCount;
  document.getElementById('sessionWrong').textContent=quizWrongCount;
  document.getElementById('sessionRecovered').textContent=quizRecoveredCount;
  document.getElementById('sessionRecoveredCard').style.display=quizRecoveredCount?'':'none';
  document.getElementById('sessionXp').textContent=`+${quizCorrectCount*10 + quizWrongCount*2 + quizRecoveredCount*5}`;
  recordTechniqueSessionStats();

  let comment='いい復習になりました。';
  if(rate>=90) comment='かなり安定しています！次は少し難しい問題へ進めます。';
  else if(rate>=70) comment='合格圏を意識できる良い出来です。間違えた問題を復習しましょう。';
  else if(rate>=50) comment='理解は進んでいます。苦手分野をもう一周すると伸びます。';
  else comment='今は弱点を発見できたことが収穫です。明日の復習に自動で回します。';
  document.getElementById('sessionComment').textContent=comment;

  const wrongCats={};
  sessionLog.filter(x=>!x.ok).forEach(x=>wrongCats[x.cat]=(wrongCats[x.cat]||0)+1);
  const topWrong=Object.entries(wrongCats).sort((a,b)=>b[1]-a[1]).slice(0,2).map(x=>x[0]);
  const routes=activeReviewJourneys();
  document.getElementById('sessionAdvice').textContent=
    topWrong.length
      ? `今回の要復習は「${topWrong.join('・')}」。誤答は復習ルートへ登録し、教材→類題→後日復習の順で追います。`
      : '全問正解です。正解した問題も忘却を防ぐため、数日後に再出題されます。';
  const continueBtn=document.getElementById('sessionContinueReview');
  const dailyBtn=document.getElementById('sessionContinueDaily');
  const homeBtn=document.getElementById('sessionHome');
  const actionable=actionableReviewJourneys();
  const nextDaily=nextUnfinishedDailyTask();
  if(continueBtn){
    continueBtn.style.display=actionable.length?'':'none';
    continueBtn.textContent=actionable.length?`復習を続ける（残り${actionable.length}件） →`:'復習を続ける →';
  }
  if(dailyBtn){
    const showDaily=!actionable.length&&!!nextDaily;
    dailyBtn.style.display=showDaily?'':'none';
    dailyBtn.textContent=showDaily?`今日の学習を続ける →`:'今日の学習を続ける →';
    dailyBtn.onclick=showDaily?()=>launchDailyTask(nextDaily):null;
  }
  if(homeBtn){
    homeBtn.className=(actionable.length||nextDaily)?'secondary':'primary';
    homeBtn.textContent=(actionable.length||nextDaily)?'演習一覧へ':'演習一覧へ戻る';
  }

  renderRecentHistory();
  renderReviewJourneyHub();
  updateDueCount();
  renderExerciseEntry();

  globalThis.FEQUEST_V376_PROTECTED_FLOW?.clearSubjectASession?.();
  quizItems=[];
}

document.getElementById('sessionHome')?.addEventListener('click',openProblemsHub);
document.getElementById('sessionContinueReview')?.addEventListener('click',()=>{openProblemsHub();const j=actionableReviewJourneys()[0];if(j)startJourneyAction(j.id);});
document.getElementById('quitQuiz')?.addEventListener('click',()=>{
  if(confirm('この演習を終了して問題一覧へ戻りますか？')){
    stopRxTimer();
    openProblemsHub();
  }
});

function renderRecentHistory(){
  const root=document.getElementById('recentHistory');
  if(!root) return;
  ensureQuestionProfile();

  const sessions=(profile.sessions||[]).slice(0,4);
  if(!sessions.length){
    root.innerHTML='<div class="sub">まだ演習履歴がありません。</div>';
    return;
  }
  root.innerHTML='';
  const names={review:'今日の復習',weak:'弱点10問',random:'ランダム10問',boss:'今日の総合チェック'};
  sessions.forEach(s=>{
    const row=document.createElement('div');
    row.className='history-row';
    const good=s.rate>=70;
    row.innerHTML=`
      <div class="history-mark ${good?'ok':'ng'}">${good?'✓':'!'}</div>
      <div class="history-text">
        <div class="history-title">${String(s.mode).startsWith('rx:')?prescriptionMeta(s.mode).title:(names[s.mode]||'問題演習')}・${s.rate}%</div>
        <div class="history-sub">${s.date}　${s.correct}/${s.total}問正解</div>
      </div>
    `;
    root.appendChild(row);
  });
}

