if(!profile.lessonProgress) profile.lessonProgress={};
// ===== v32: lesson density audit =====
function applyLessonDensityAudit(){
  const staticCompact={
    memorychips:{
      headline:'RAM・ROM・フラッシュを1画面で比較',
      copy:'RAMは揮発性で通常は読み書き可能、ROMは不揮発性で基本は読出し中心、フラッシュは不揮発性かつ電気的に書換え可能です。性質と代表用途を一度に整理します。',
      render:()=>memoryView('all')
    },
    devmodel:{
      headline:'ウォーターフォールとアジャイルを1画面で比較',
      copy:'ウォーターフォールは工程を順に固めて進め、アジャイルは短い反復で実装・確認・改善を繰り返します。要件の安定性やプロジェクト特性に応じて使い分けます。',
      render:()=>devModelView('both')
    },
    procurement:{
      headline:'RFPの役割と中身を1画面で整理',
      copy:'RFPはベンダへ提案を依頼する文書です。目的・背景、要求機能、納期や条件、評価方法などを明確にして、提案を比較できるようにします。',
      render:()=>rfpView('all')
    },
    reliability:{
      headline:'直列・並列システムの稼働率を一度に比較',
      copy:'稼働率0.9の装置2台なら、直列は両方が動く必要があるので0.9×0.9=0.81。並列は両方故障する確率0.1×0.1を1から引いて0.99です。',
      render:()=>reliabilityView('both')
    },
    backup:{
      headline:'フル・増分・差分バックアップを1画面で整理',
      copy:'フルは対象全体、増分は前回バックアップ以降の変更、差分は直近のフルバックアップ以降の変更を保存します。保存量と復元手順の違いを図で比較します。',
      render:()=>backupView('compare')
    },
    tcpudp:{
      headline:'TCPとUDPを1画面で比較',
      copy:'TCPは再送・順序制御などで信頼性を高めます。UDPはUDP自体に再送制御を持たず、処理が軽いのが特徴です。パケット欠落時の違いを並べて確認します。',
      render:()=>protocolView('both')
    }
  };

  Object.entries(staticCompact).forEach(([id,content])=>{
    const lesson=LESSONS[id];
    if(!lesson) return;
    const quiz=lesson.pages.find(p=>p.quiz);
    lesson.pages=[content,quiz];
  });

  Object.entries(LESSONS).forEach(([id,lesson])=>{
    if(staticCompact[id]) return;
    if(lesson.pages.length!==4) return;
    const [overview,interactive,recap,check]=lesson.pages;
    if(interactive?.interactive && check?.quiz){
      interactive.takeaway={headline:recap.headline,copy:recap.copy};
      lesson.pages=[overview,interactive,check];
    }
  });
}
