function startLessonLegacyV376(id){
  if(!LESSONS[id]) return;
  if(activeReviewJourneyId && journeyFor(activeReviewJourneyId)?.lessonId!==id) activeReviewJourneyId=null;
  activeLesson=id;
  lessonStep=0;
  lessonCompleteMode=false;
  const prev=document.getElementById('lessonPrev');
  if(prev) prev.style.display='none';
  resetLessonState();
  showScreen('lesson');
  renderLesson();
}
async function startLesson(id){
  if(!fequestProtectedLessonIsCoreV376(id)){fequestProtectedLessonLoadGenerationV376++;fequestProtectedLessonProviderV376().clearCurrent();return startLessonLegacyV376(id);}
  const generation=++fequestProtectedLessonLoadGenerationV376;
  try{
    if(!(await fequestProtectedLessonEnsureAccessV376()))return false;
    await fequestProtectedLessonProviderV376().hydrate(id);
    if(generation!==fequestProtectedLessonLoadGenerationV376)return false;
    if(!fequestProtectedLessonArticleV376(id))throw new Error('lesson_article_invalid');
    startLessonLegacyV376(id);showScreen('lesson');return true;
  }catch(error){fequestProtectedLessonHandleErrorV376(error);return false;}
}

