// ===== v28: first-page presentation rule =====
// Page 1 is an overview. It must not look as if a step-by-step exercise has already started.
function neutralizeFirstPageMarkup(markup){
  let s=String(markup??'');
  s=s.replace(/\bflow-current\b/g,'')
     .replace(/\bflow-done\b/g,'')
     .replace(/\bflow-arrow-current\b/g,'')
     .replace(/class="file-node\s+active"/g,'class="file-node"')
     .replace(/<div class="step-position-note">[\s\S]*?<\/div>/g,'');
  return s;
}

function renderLessonLegacyV376(){
  const lesson=LESSONS[activeLesson];
  const page=lesson.pages[lessonStep];
  const isCore=!!lesson.core;
  document.getElementById('lessonTitle').textContent=lesson.title;
  document.getElementById('lessonCategory').textContent=`${lesson.cat}・レッスン`;
  const headline=document.getElementById('lessonHeadline');
  const copy=document.getElementById('lessonCopy');
  headline.textContent=expandLearningAbbreviations(activeLesson==='stackqueue'?stackQueueOperationTextV360(page.headline):page.headline||'');
  copy.textContent=expandLearningAbbreviations(activeLesson==='stackqueue'?stackQueueOperationTextV360(page.copy):page.copy||'');
  headline.style.display=isCore?'none':'';
  copy.style.display=isCore?'none':'';
  updateInteractionGuide(page);
  const stepLabel=document.getElementById('lessonStepLabel');
  stepLabel.textContent=`${lessonStep+1} / ${lesson.pages.length}`;
  stepLabel.style.display=isCore?'none':'';
  const dots=document.getElementById('lessonDots');
  dots.style.display=isCore?'none':'';
  if(dots.children.length!==lesson.pages.length){
    dots.innerHTML=Array.from({length:lesson.pages.length},()=>'<span></span>').join('');
  }
  dots.querySelectorAll('span').forEach((s,i)=>s.classList.toggle('on',i<=lessonStep));
  const check=document.getElementById('lessonCheck');
  check.className='lesson-check';
  check.innerHTML='';

  const stage=document.getElementById('lessonStage');
  stage.classList.toggle('lesson-intro',lessonStep===0);
  stage.innerHTML='';
  lessonInteractiveDone=!page.interactive && !page.quiz;
  lessonQuizDone=!page.quiz;

  const introGuide=(lessonStep===0 && !page.noGuide) ? lessonStudyGuide(activeLesson) : '';
  if(page.render){
    const markup=page.render();
    const visual=lessonStep===0 ? neutralizeFirstPageMarkup(markup) : markup;
    stage.innerHTML=introGuide + visual;
  }else if(introGuide){ stage.innerHTML=introGuide; }
  if(page.interactive) renderInteractive(page.interactive,stage);
  if(page.quiz) renderLessonQuiz(page.quiz,stage);

  const prev=document.getElementById('lessonPrev');
  prev.style.display=(isCore||lessonStep===0)?'none':'';
  prev.disabled=isCore||lessonStep===0;
  const next=document.getElementById('lessonNext');
  if(isCore){
    next.textContent='学習完了 → 問題演習';
  }else if(lessonStep===lesson.pages.length-1){
    next.textContent='レッスン完了 ✨';
  }else{
    next.textContent='次へ →';
  }
  document.querySelector('.lesson-nav')?.classList.toggle('single-next', prev.style.display==='none');
  rememberLessonPosition();
}
function renderLesson(){
  if(!fequestProtectedLessonIsCoreV376(activeLesson))return renderLessonLegacyV376();
  const article=fequestProtectedLessonArticleV376(activeLesson);
  if(!article){fequestProtectedLessonRenderPendingV376(activeLesson,{retry:false,message:'教材を読み込んでいます…'});void fequestProtectedLessonAutoResumeCurrentV376(activeLesson);return;}
  const lesson=LESSONS[activeLesson],page=lesson?.pages?.[lessonStep];
  if(!page)throw new Error('protected_lesson_page_missing');
  const originalRender=page.render;
  page.render=()=>article;
  try{return renderLessonLegacyV376();}finally{page.render=originalRender;}
}
function showLessonFeedback(msg,bad=false){
  const c=document.getElementById('lessonCheck');
  c.className='lesson-check show'+(bad?' bad':'');
  const page=LESSONS[activeLesson]?.pages?.[lessonStep];
  if(!bad && lessonInteractiveDone && page?.takeaway){
    c.innerHTML=`<div class="lesson-takeaway"><b>${escapeHtml(page.takeaway.headline)}</b><span>${escapeHtml(page.takeaway.copy)}</span></div>`;
  }else{
    c.innerHTML=msg;
  }
  if(!bad && (lessonInteractiveDone||lessonQuizDone)) markInteractionGuideDone();
}

function renderInteractive(type,stage){
  if(type==='binary13'){
    stage.innerHTML=`<div style="text-align:center;font-weight:900">目標：13</div>
      <div class="bit-board" id="bitBoard">${[8,4,2,1].map(w=>`<div class="bit-col"><div class="bit-weight">${w}</div><button class="bit-toggle" data-weight="${w}">0</button></div>`).join('')}</div>
      <div class="binary-total">合計 <span id="bitTotal">0</span></div>`;
    let total=0;
    stage.querySelectorAll('.bit-toggle').forEach(b=>{
      b.addEventListener('click',()=>{
        b.classList.toggle('on');
        b.textContent=b.classList.contains('on')?'1':'0';
        total=[...stage.querySelectorAll('.bit-toggle.on')].reduce((s,x)=>s+Number(x.dataset.weight),0);
        document.getElementById('bitTotal').textContent=total;
        if(total===13){
          lessonInteractiveDone=true;
          showLessonFeedback('🎉 できました！ 8 + 4 + 1 = 13、つまり <b>1101₂</b> です。');
        }
      });
    });
  }

  if(type==='cpuCycle'){
    const draw=()=>{
      stage.innerHTML=`<div id="cpuDynamic">${cpuFlow(cpuStep)}</div>${reversibleStepControls(cpuStep,3,{prevId:'cpuPrevStep',nextId:'cpuNextStep',nextLabel:'次の処理 →',doneLabel:'✓ 命令サイクル確認済み'})}`;
      const prev=document.getElementById('cpuPrevStep'),next=document.getElementById('cpuNextStep');
      if(prev&&!prev.disabled)prev.onclick=()=>{cpuStep=Math.max(0,cpuStep-1);draw();};
      if(next&&!next.disabled)next.onclick=()=>{cpuStep=Math.min(3,cpuStep+1);if(cpuStep===3)lessonInteractiveDone=true;draw();};
    };
    draw();
  }


function flowStepButton(step,label,sub,opts={}){
  const current=!!opts.current,done=!!opts.done,disabled=!!opts.disabled;
  const icon=done?'✓':step;
  return `<button class="flow-step-btn ${current?'current':''} ${done?'done':''}" ${disabled?'disabled':''} id="${opts.id||''}">
    <span class="step-badge">${icon}</span>
    <span class="step-main">
      <span class="step-title">${label}</span>
      <span class="step-sub">${sub}</span>
    </span>
  </button>`;
}

function stepStatusCard(title, body, tone='info'){
  const map={info:['📝','info'],warn:['⚠','warn'],success:['✓','success']};
  const [icon,klass]=map[tone]||map.info;
  return `<div class="step-status ${klass}">
    <div class="step-status-head"><div class="step-status-icon">${icon}</div><div class="step-status-title">${title}</div></div>
    <div class="step-status-body">${body}</div>
  </div>`;
}

function transactionStatusView(step){
  if(step===0) return stepStatusCard('開始前','まずステップ1を押して、A口座だけ減額した途中状態を作ります。','info');
  if(step===1) return stepStatusCard('障害発生','A口座だけが減り、B口座はまだ増えていません。このままだと 1,000円 が消えてしまいます。次はステップ2の ROLLBACK で開始前の状態へ戻します。','warn');
  return stepStatusCard('復元完了','ROLLBACKで開始前の状態へ戻せました。途中までの更新を残さないことが、トランザクションの原子性です。','success');
}
function transactionActionView(step){
  return `<div class="flow-actions">
    ${flowStepButton('1','A口座を1,000円減額','途中状態を作る',{id:'txnWithdraw',current:step===0,done:step>=1,disabled:step>=1})}
    ${flowStepButton('2','ROLLBACK','開始前の状態へ戻す',{id:'txnRollback',current:step===1,done:step>=2,disabled:step!==1})}
  </div>`;
}
function renderTransactionLesson(step, message){
  const balances = step===1 ? [9000,5000] : [10000,5000];
  stage.innerHTML = `<div id="bankDynamic">${bankView(balances[0],balances[1],message)}</div>${transactionStatusView(step)}${transactionActionView(step)}`;
}

  if(type==='transaction'){
    renderTransactionLesson(0,'開始前：A=10,000 / B=5,000');
    document.getElementById('txnWithdraw').addEventListener('click',()=>{
      txnState=1;
      renderTransactionLesson(1,'Aだけ減額。ここで障害が発生');
      document.getElementById('txnRollback').addEventListener('click',()=>{
        txnState=2;
        lessonInteractiveDone=true;
        renderTransactionLesson(2,'ROLLBACK → 処理前の状態へ復元');
      },{once:true});
    },{once:true});
  }

  if(type==='subnet'){
    stage.innerHTML=`<div id="subnetDynamic">${ipView([192,168,10,25],3)}</div>
      <div style="text-align:center;margin-top:18px"><button class="purple-btn" id="zeroHost">ホスト部を0にする</button></div>`;
    document.getElementById('zeroHost').addEventListener('click',()=>{
      document.getElementById('subnetDynamic').innerHTML=ipView([192,168,10,0],3);
      document.getElementById('zeroHost').disabled=true;
      lessonInteractiveDone=true;
      showLessonFeedback('✅ ネットワークアドレスは <b>192.168.10.0</b> です。');
    });
  }

  if(type==='crypto'){
    const draw=()=>{
      const viewStep=cryptoStep===0?0:cryptoStep===1?2:3;
      const nextLabel=cryptoStep===0?'🔒 公開鍵で暗号化 →':'🔑 秘密鍵で復号 →';
      stage.innerHTML=`<div id="cryptoDynamic">${cryptoView(viewStep)}</div>${reversibleStepControls(cryptoStep,2,{prevId:'cryptoPrevStep',nextId:'cryptoNextStep',nextLabel,doneLabel:'✓ 復号完了'})}`;
      const prev=document.getElementById('cryptoPrevStep'),next=document.getElementById('cryptoNextStep');
      if(prev&&!prev.disabled)prev.onclick=()=>{cryptoStep=Math.max(0,cryptoStep-1);draw();};
      if(next&&!next.disabled)next.onclick=()=>{cryptoStep=Math.min(2,cryptoStep+1);if(cryptoStep===2)lessonInteractiveDone=true;draw();};
    };
    draw();
  }


  if(type==='logic'){
    let A=0,B=0;
    const draw=()=>{
      const andv=A&&B?1:0, orv=A||B?1:0;
      stage.innerHTML=`<div class="logic-switches">
        <button class="logic-switch ${A?'on':''}" id="logicA">A = ${A}</button>
        <button class="logic-switch ${B?'on':''}" id="logicB">B = ${B}</button>
        <div style="text-align:center"><div class="sub">AND</div><div class="logic-out ${andv?'on':''}">${andv}</div></div>
        <div style="text-align:center"><div class="sub">OR</div><div class="logic-out ${orv?'on':''}">${orv}</div></div>
      </div><div class="lesson-copy">4通りすべて試してみましょう。</div>`;
      document.getElementById('logicA').onclick=()=>{A=A?0:1;logicSeen.add(`${A}${B}`);draw();check();};
      document.getElementById('logicB').onclick=()=>{B=B?0:1;logicSeen.add(`${A}${B}`);draw();check();};
    };
    const check=()=>{
      logicSeen.add(`${A}${B}`);
      if(logicSeen.size>=4){
        lessonInteractiveDone=true;
        showLessonFeedback('✅ 4通り確認できました。ANDは11だけ1、ORは00だけ0です。');
      }
    };
    logicSeen.add('00');draw();
  }

  if(type==='cache'){
    const drawActions=()=>{
      document.getElementById('cacheActions').innerHTML=`<button class="explore-btn ${cacheSeen.has('hit')?'seen':''}" id="cacheHit">⚡ ヒット</button><button class="explore-btn ${cacheSeen.has('miss')?'seen':''}" id="cacheMiss">🐢 ミス</button>`;
      document.getElementById('cacheHit').onclick=()=>{cacheSeen.add('hit');document.getElementById('cacheDynamic').innerHTML=cacheView('hit');lessonInteractiveDone=cacheSeen.size>=2;drawActions();showLessonFeedback('HIT：キャッシュにデータがあり、主記憶まで行かずに取得できます。');};
      document.getElementById('cacheMiss').onclick=()=>{cacheSeen.add('miss');document.getElementById('cacheDynamic').innerHTML=cacheView('miss');lessonInteractiveDone=cacheSeen.size>=2;drawActions();showLessonFeedback('MISS：キャッシュになかったため、主記憶へ取りに行きます。');};
    };
    stage.innerHTML=`<div id="cacheDynamic">${cacheView('idle')}</div><div class="explore-actions" id="cacheActions"></div>`;
    drawActions();
  }

  if(type==='stackqueue'){
    renderStackQueueExperienceV360(stage);
  }

  if(type==='sql'){
    stage.innerHTML=`<div id="sqlDynamic">${sqlView(false)}</div>
      <div style="text-align:center;margin-top:15px"><button class="purple-btn" id="runSql">▶ WHEREを実行</button></div>`;
    document.getElementById('runSql').onclick=()=>{
      document.getElementById('sqlDynamic').innerHTML=sqlView(true);
      document.getElementById('runSql').disabled=true;
      lessonInteractiveDone=true;
      showLessonFeedback('✅ salaryが300000未満の佐藤さん・高橋さんが除外されました。');
    };
  }

  if(type==='tcpudp'){
    stage.innerHTML=`<div id="protocolDynamic">${protocolView('idle')}</div>
      <div class="txn-buttons"><button class="secondary" id="showTcp">TCPの挙動</button><button class="purple-btn" id="showUdp">UDPの挙動</button></div>`;
    document.getElementById('showTcp').onclick=()=>{
      protocolSeen.add('tcp');
      document.getElementById('protocolDynamic').innerHTML=protocolView('tcp');
      showLessonFeedback('TCP：欠けた2番を再送し、データをそろえます。');
      if(protocolSeen.size>=2) lessonInteractiveDone=true;
    };
    document.getElementById('showUdp').onclick=()=>{
      protocolSeen.add('udp');
      document.getElementById('protocolDynamic').innerHTML=protocolView('udp');
      showLessonFeedback('UDP：UDP自体は再送制御を行わないため、欠落した状態でも先へ進めます。');
      if(protocolSeen.size>=2) lessonInteractiveDone=true;
    };
  }

  if(type==='signature'){
    const labels=['ハッシュを作る →','秘密鍵で署名 →','公開鍵で検証 →'];
    const draw=()=>{
      stage.innerHTML=`<div id="sigDynamic">${signatureView(signatureStep)}</div>${reversibleStepControls(signatureStep,3,{prevId:'sigPrevStep',nextId:'sigNextStep',nextLabel:labels[Math.min(signatureStep,2)],doneLabel:'✓ 検証完了'})}`;
      const prev=document.getElementById('sigPrevStep'),next=document.getElementById('sigNextStep');
      if(prev&&!prev.disabled)prev.onclick=()=>{signatureStep=Math.max(0,signatureStep-1);draw();};
      if(next&&!next.disabled)next.onclick=()=>{signatureStep=Math.min(3,signatureStep+1);if(signatureStep===3)lessonInteractiveDone=true;draw();};
    };
    draw();
  }

  if(type==='mutex'){
    const mutexStatusView=(step)=>{
      if(step===0) return stepStatusCard('開始前','まずステップ1を押して、利用者Aが在庫データをLOCKする様子を確認します。','info');
      if(step===1) return stepStatusCard('LOCK中','Aが在庫を処理している間、Bは待機します。次はステップ2で更新完了後にUNLOCKします。','warn');
      return stepStatusCard('UNLOCK完了','Aの処理後に資源を解放しました。Bは更新後の在庫を確認でき、同時更新による矛盾を防げます。','success');
    };
    const mutexActionView=(step)=>`<div class="flow-actions">
      ${flowStepButton('1','AがLOCK','在庫データを占有する',{id:'lockA',current:step===0,done:step>=1,disabled:step>=1})}
      ${flowStepButton('2','更新完了・UNLOCK','資源を解放して次へ渡す',{id:'unlockA',current:step===1,done:step>=2,disabled:step!==1})}
    </div>`;
    const renderMutexLesson=(step)=>{
      const scene = step===2
        ? `<div class="lock-demo">
            <div class="worker"><div style="font-size:28px">👤</div><b>利用者A</b><div class="sub">購入完了</div></div>
            <div class="resource"><div class="lock-icon">📦</div><b>在庫：0</b><div class="sub">ロック解除</div></div>
            <div class="worker"><div style="font-size:28px">👤</div><b>利用者B</b><div class="sub">在庫0を確認</div></div>
          </div>`
        : lockView(step===1?'locked':'idle');
      stage.innerHTML = `<div id="lockDynamic">${scene}</div>${mutexStatusView(step)}${mutexActionView(step)}`;
    };
    renderMutexLesson(0);
    document.getElementById('lockA').onclick=()=>{
      mutexStep=1;
      renderMutexLesson(1);
      document.getElementById('unlockA').onclick=()=>{
        mutexStep=2;
        lessonInteractiveDone=true;
        renderMutexLesson(2);
      };
    };
  }



  if(type==='automata'){
    const seq=[1,0,1];
    const stateAt=(n)=>{
      let state='A';
      for(let i=0;i<n;i++)if(seq[i]===1)state=state==='A'?'B':'A';
      return state;
    };
    const draw=()=>{
      const state=stateAt(automataIdx);
      const tokens=seq.map((x,i)=>`<div class="fsm-token ${i<automataIdx?'done':i===automataIdx?'current':''}">${x}</div>`).join('<span>→</span>');
      stage.innerHTML=`<div id="fsmDynamic">${automataView(state)}</div><div class="fsm-sequence">${tokens}</div>${reversibleStepControls(automataIdx,seq.length,{prevId:'fsmPrevStep',nextId:'fsmNextStep',nextLabel:automataIdx<seq.length?`入力 ${seq[automataIdx]} を適用 →`:'',doneLabel:'✓ 入力列を確認済み'})}`;
      const prev=document.getElementById('fsmPrevStep'),next=document.getElementById('fsmNextStep');
      if(prev&&!prev.disabled)prev.onclick=()=>{automataIdx=Math.max(0,automataIdx-1);draw();};
      if(next&&!next.disabled)next.onclick=()=>{automataIdx=Math.min(seq.length,automataIdx+1);if(automataIdx===seq.length)lessonInteractiveDone=true;draw();};
    };
    draw();
  }

  if(type==='memorychips'){
    stage.innerHTML=`<div id="memDynamic">${memoryView('none')}</div><div class="txn-buttons">
      <button class="secondary" data-mem="0">RAM</button><button class="secondary" data-mem="1">ROM</button><button class="purple-btn" data-mem="2">フラッシュ</button></div>`;
    stage.querySelectorAll('[data-mem]').forEach(b=>b.onclick=()=>{
      memorySeen.add(b.dataset.mem);
      document.getElementById('memDynamic').innerHTML=memoryView(b.dataset.mem);
      if(memorySeen.size>=3){lessonInteractiveDone=true;showLessonFeedback('✅ 3種類を比較できました。揮発性と書換え可否を軸に整理しましょう。');}
    });
  }

  if(type==='filesystem'){
    const steps=[
      {path:'/',correct:'home',opts:['home','etc','var']},
      {path:'/home',correct:'user',opts:['guest','user','shared']},
      {path:'/home/user',correct:'docs',opts:['bin','cache','docs']},
      {path:'/home/user/docs',correct:'report.pdf',opts:['photo.png','report.pdf','app.exe']}
    ];
    const draw=()=>{
      if(fileStep>=steps.length){
        lessonInteractiveDone=true;
        stage.innerHTML=`${fileTreeView(5)}<div class="file-path-task">${stepStatusCard('到達','絶対パス /home/user/docs/report.pdf を階層順にたどれました。','success')}</div>${reversibleStepControls(fileStep,steps.length,{prevId:'filePrevStep',nextId:'fileNextStep',doneLabel:'✓ 到達済み'})}`;
        const prev=document.getElementById('filePrevStep');
        if(prev&&!prev.disabled)prev.onclick=()=>{fileStep=Math.max(0,fileStep-1);draw();};
        return;
      }
      const s=steps[fileStep];
      stage.innerHTML=`${fileTreeView(fileStep)}<div class="file-path-task">
        <div class="file-path-current">現在位置：<b>${s.path}</b></div>
        <div class="file-path-label">次に進む名前を選んでください</div>
        <div class="file-path-options">${s.opts.map(x=>`<button class="file-path-option" data-filepart="${x}">${x}</button>`).join('')}</div>
        ${fileStep>0?'<div class="step-nav-controls"><button class="step-prev-btn" id="filePrevStep">← 1階層戻る</button></div>':''}
      </div>`;
      const prev=document.getElementById('filePrevStep');
      if(prev)prev.onclick=()=>{fileStep=Math.max(0,fileStep-1);draw();};
      stage.querySelectorAll('[data-filepart]').forEach(b=>b.onclick=()=>{
        if(b.dataset.filepart===s.correct){b.classList.add('good');fileStep++;setTimeout(draw,220);}
        else{b.classList.add('bad');showLessonFeedback(`「${s.path}」から目的ファイルへ進む次の階層を考えてみましょう。`,true);setTimeout(()=>b.classList.remove('bad'),650);}
      });
    };
    draw();
  }

  if(type==='uiux'){
    stage.innerHTML=`${uiView(false)}<div class="micro-options"><button class="micro-option" data-ui="bad">左：小さい「?」</button><button class="micro-option" data-ui="good">右：「保存する」</button></div>`;
    stage.querySelectorAll('[data-ui]').forEach(b=>b.onclick=()=>{
      if(b.dataset.ui==='good'){b.classList.add('good');lessonInteractiveDone=true;showLessonFeedback('⭕ 目的が分かるラベルと十分な操作領域があり、操作しやすい設計です。');}
      else{b.classList.add('bad');showLessonFeedback('何をするボタンか分かるか、押しやすい大きさかを見てみましょう。',true);setTimeout(()=>b.classList.remove('bad'),650);}
    });
  }

  if(type==='multimedia'){
    stage.innerHTML=`${mediaView(false)}<div class="micro-options"><button class="micro-option" data-v="32">32 byte</button><button class="micro-option" data-v="64">64 byte</button><button class="micro-option" data-v="512">512 byte</button><button class="micro-option" data-v="4096">4096 byte</button></div>`;
    stage.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>{
      if(b.dataset.v==='64'){b.classList.add('good');lessonInteractiveDone=true;stage.querySelector('.media-calc').outerHTML=mediaView(true).match(/<div class="media-calc">[\s\S]*<\/div>$/)?.[0]||stage.querySelector('.media-calc').outerHTML;showLessonFeedback('⭕ 512ビット ÷ 8 = 64バイトです。');}
      else{b.classList.add('bad');showLessonFeedback('まず 8×8×8 = 512ビット。その後8で割ってバイトへ変換します。',true);setTimeout(()=>b.classList.remove('bad'),650);}
    });
  }

  if(type==='devmodel'){
    const renderModelChoices=()=>{
      stage.innerHTML=`<div id="modelDynamic">${devModelView('none',true)}</div>`;
      stage.querySelectorAll('[data-model]').forEach(btn=>{
        btn.onclick=()=>{
          const kind=btn.dataset.model;
          devModelSeen.add(kind==='waterfall'?'w':'a');
          lessonInteractiveDone=devModelSeen.size>=2;
          renderModelChoices();
          showLessonFeedback(kind==='waterfall'
            ? '① ウォーターフォール：工程を順に区切って進めます。次は②アジャイルも確認してください。'
            : '② アジャイル：短い反復で計画・実装・確認・改善を回します。'+(lessonInteractiveDone?' 2つの比較が完了しました。':' 次は①ウォーターフォールも確認してください。'));
          if(lessonInteractiveDone)markInteractionGuideDone();
        };
      });
    };
    renderModelChoices();
  }

  if(type==='audit'){
    stage.innerHTML=`${auditView(false)}<div class="micro-options"><button class="micro-option" data-audit="dev">開発責任者による自己監査</button><button class="micro-option" data-audit="ind">独立した監査担当</button></div>`;
    stage.querySelectorAll('[data-audit]').forEach(b=>b.onclick=()=>{
      if(b.dataset.audit==='ind'){b.classList.add('good');lessonInteractiveDone=true;showLessonFeedback('⭕ 客観的な評価のため、監査対象からの独立性が重要です。');}
      else{b.classList.add('bad');showLessonFeedback('自分の仕事を自分だけで評価すると客観性が弱くなります。',true);setTimeout(()=>b.classList.remove('bad'),650);}
    });
  }

  if(type==='businessprocess'){
    stage.innerHTML=`${processView(false)}<div class="micro-options"><button class="micro-option" data-proc="keep">再入力を残す</button><button class="micro-option" data-proc="remove">再入力をなくす</button></div>`;
    stage.querySelectorAll('[data-proc]').forEach(b=>b.onclick=()=>{
      if(b.dataset.proc==='remove'){b.classList.add('good');lessonInteractiveDone=true;stage.querySelector('.process-lane').outerHTML=processView(true);showLessonFeedback('⭕ 重複入力をなくし、データを一度入力すれば後工程でも利用する形に改善しました。');}
      else{b.classList.add('bad');showLessonFeedback('どの工程が同じ情報を二度入力しているか探しましょう。',true);setTimeout(()=>b.classList.remove('bad'),650);}
    });
  }

  if(type==='procurement'){
    stage.innerHTML=`<div id="rfpDynamic">${rfpView('none')}</div><div class="txn-buttons">
      <button class="secondary" data-rfp="0">目的</button><button class="secondary" data-rfp="1">要求機能</button><button class="secondary" data-rfp="2">納期条件</button><button class="purple-btn" data-rfp="3">評価方法</button></div>`;
    stage.querySelectorAll('[data-rfp]').forEach(b=>b.onclick=()=>{
      rfpSeen.add(b.dataset.rfp);document.getElementById('rfpDynamic').innerHTML=rfpView(b.dataset.rfp);
      if(rfpSeen.size>=4){lessonInteractiveDone=true;showLessonFeedback('✅ 提案を比較できるよう、要求と条件を明確にしておくことが重要です。');}
    });
  }

  if(type==='swot'){
    const cases=[
      ['高い技術力','S'],['知名度が低い','W'],['市場が拡大中','O'],['競合が新規参入','T']
    ];
    const learned={};
    const draw=()=>{
      if(swotStep>=cases.length){
        lessonInteractiveDone=true;
        stage.innerHTML=`${swotMatrixView(learned,false)}${stepStatusCard('4象限を確認できました','内部/外部とプラス/マイナスの2軸で分類すると、S・W・O・Tの位置が決まります。','success')}`;
        return;
      }
      const c=cases[swotStep];
      stage.innerHTML=`<div class="swot-practice-head"><span>この例はどの象限？</span><b>${c[0]}</b></div>${swotMatrixView(learned,true)}`;
      stage.querySelectorAll('.swot-quad[data-swot]').forEach(b=>b.onclick=()=>{
        if(b.dataset.swot===c[1]){
          b.classList.add('good');
          learned[c[1]]=c[0];
          swotStep++;
          setTimeout(draw,260);
        }else{
          b.classList.add('bad');
          showLessonFeedback('内部か外部か、そのうえでプラス要因かマイナス要因かの順で考えてみましょう。',true);
          setTimeout(()=>b.classList.remove('bad'),600);
        }
      });
    };
    draw();
  }

  if(type==='iot'){
    const draw=()=>{
      stage.innerHTML=`<div id="iotDynamic">${iotView(iotStep)}</div>${reversibleStepControls(iotStep,4,{prevId:'iotPrevStep',nextId:'iotNextStep',nextLabel:'データを次へ送る →',doneLabel:'✓ 流れを確認済み'})}`;
      const prev=document.getElementById('iotPrevStep'),next=document.getElementById('iotNextStep');
      if(prev&&!prev.disabled)prev.onclick=()=>{iotStep=Math.max(0,iotStep-1);draw();};
      if(next&&!next.disabled)next.onclick=()=>{iotStep=Math.min(4,iotStep+1);if(iotStep===4)lessonInteractiveDone=true;draw();};
    };
    draw();
  }

  if(type==='finance'){
    stage.innerHTML=`<div id="finDynamic">${financeView(0)}</div><div class="micro-options" id="finOptions"><button class="micro-option" data-fin="400">売上総利益 400</button><button class="micro-option" data-fin="600">売上総利益 600</button></div>`;
    stage.querySelectorAll('[data-fin]').forEach(b=>b.onclick=()=>{
      if(b.dataset.fin==='400'){
        financeStep=1;document.getElementById('finDynamic').innerHTML=financeView(1);
        document.getElementById('finOptions').innerHTML='<button class="micro-option" data-op="150">営業利益 150</button><button class="micro-option" data-op="250">営業利益 250</button>';
        document.querySelectorAll('[data-op]').forEach(x=>x.onclick=()=>{
          if(x.dataset.op==='150'){x.classList.add('good');financeStep=2;document.getElementById('finDynamic').innerHTML=financeView(2);lessonInteractiveDone=true;showLessonFeedback('✅ 1,000−600=400、400−250=150です。');}
          else{x.classList.add('bad');showLessonFeedback('売上総利益400から販管費250を引きます。',true);setTimeout(()=>x.classList.remove('bad'),600);}
        });
      }else{b.classList.add('bad');showLessonFeedback('売上総利益 = 売上高1,000 − 売上原価600です。',true);setTimeout(()=>b.classList.remove('bad'),600);}
    });
  }

  if(type==='os'){
    const draw=()=>{
      stage.innerHTML=`<div id="osDynamic">${scheduleView(osSteps)}</div>${reversibleStepControls(osSteps,3,{prevId:'osPrevStep',nextId:'osNextStep',nextLabel:'CPUを次へ割り当てる →',doneLabel:'✓ 3プロセス確認済み'})}`;
      const prev=document.getElementById('osPrevStep'),next=document.getElementById('osNextStep');
      if(prev&&!prev.disabled)prev.onclick=()=>{osSteps=Math.max(0,osSteps-1);draw();};
      if(next&&!next.disabled)next.onclick=()=>{osSteps=Math.min(3,osSteps+1);if(osSteps===3)lessonInteractiveDone=true;draw();};
    };
    draw();
  }

  if(type==='reliability'){
    stage.innerHTML=`<div id="relDynamic">${reliabilityView('none')}</div>
      <div class="txn-buttons"><button class="secondary" id="relSeries">直列を計算</button><button class="purple-btn" id="relParallel">並列を計算</button></div>`;
    document.getElementById('relSeries').onclick=()=>{
      reliabilitySeen.add('series');document.getElementById('relDynamic').innerHTML=reliabilityView('series');
      showLessonFeedback('直列：0.9 × 0.9 = 0.81');
      if(reliabilitySeen.size>=2) lessonInteractiveDone=true;
    };
    document.getElementById('relParallel').onclick=()=>{
      reliabilitySeen.add('parallel');document.getElementById('relDynamic').innerHTML=reliabilityView('parallel');
      showLessonFeedback('並列：1 − (0.1 × 0.1) = 0.99');
      if(reliabilitySeen.size>=2) lessonInteractiveDone=true;
    };
  }

  if(type==='backup'){
    stage.innerHTML=`<div id="backupDynamic">${backupView('full')}</div>
      <div class="backup-controls"><button class="secondary" id="showInc">増分を見る</button><button class="purple-btn" id="showDiff">差分を見る</button></div>`;
    document.getElementById('showInc').onclick=()=>{
      backupSeen.add('inc');document.getElementById('backupDynamic').innerHTML=backupView('incremental');
      showLessonFeedback('増分は「前回バックアップ後に変わった分」だけを保存します。');
      if(backupSeen.size>=2) lessonInteractiveDone=true;
    };
    document.getElementById('showDiff').onclick=()=>{
      backupSeen.add('diff');document.getElementById('backupDynamic').innerHTML=backupView('differential');
      showLessonFeedback('差分は「直近フルバックアップ後の変更を全部」毎回保存します。');
      if(backupSeen.size>=2) lessonInteractiveDone=true;
    };
  }

  if(type==='development'){
    const draw=()=>{
      stage.innerHTML=`<div id="devDynamic">${devPipeline(devSteps)}</div>${reversibleStepControls(devSteps,5,{prevId:'devPrevStep',nextId:'devNextStep',nextLabel:'次の工程 →',doneLabel:'✓ 全工程確認済み'})}`;
      const prev=document.getElementById('devPrevStep'),next=document.getElementById('devNextStep');
      if(prev&&!prev.disabled)prev.onclick=()=>{devSteps=Math.max(0,devSteps-1);draw();};
      if(next&&!next.disabled)next.onclick=()=>{devSteps=Math.min(5,devSteps+1);if(devSteps===5)lessonInteractiveDone=true;draw();};
    };
    draw();
  }

  if(type==='testingClassify'){
    const cases=[{q:'1つの関数やモジュールの分岐・処理経路に誤りがないか確認する。',a:'単体テスト',exp:'個々のプログラムを対象とするため単体テストです。内部構造を見るホワイトボックステストとも結び付きます。'},{q:'複数のモジュールを接続し、データの受渡しやインタフェースを確認する。',a:'結合テスト',exp:'モジュール同士を組み合わせた連携確認なので結合テストです。'},{q:'システム全体について、機能だけでなく応答時間なども含めて要件を満たすか確認する。',a:'システムテスト',exp:'システム要件全体を対象に確認するためシステムテストです。'},{q:'本番に近い環境で、実際の利用者が業務手順どおり運用できるか確認する。',a:'運用テスト',exp:'利用者が業務要件を満たすか確認する段階なので運用テストです。'}];
    const opts=['単体テスト','結合テスト','システムテスト','運用テスト'];
    const draw=()=>{if(testSteps>=cases.length){lessonInteractiveDone=true;stage.innerHTML=`<div class="testing-practice">${stepStatusCard('4種類を目的から判別できました','テスト名ではなく、対象範囲・確認内容・担当者を手掛かりに判断しましょう。','success')}</div>`;return;}const c=cases[testSteps];stage.innerHTML=`<div class="testing-practice"><div class="testing-practice-case"><span>ケース ${testSteps+1} / ${cases.length}</span><b>${c.q}</b></div><div class="testing-choice-grid">${opts.map(x=>`<button class="testing-choice" data-testkind="${x}">${x}</button>`).join('')}</div><div class="testing-progress">${testSteps} / ${cases.length} 完了</div></div>`;stage.querySelectorAll('[data-testkind]').forEach(btn=>btn.onclick=()=>{if(btn.dataset.testkind===c.a){btn.classList.add('good');showLessonFeedback(c.exp);testSteps++;setTimeout(draw,500);}else{btn.classList.add('bad');showLessonFeedback('何を対象に、何を確認している説明なのかを見直してみましょう。',true);setTimeout(()=>btn.classList.remove('bad'),650);}});};draw();
  }

  if(type==='criticalpath'){
    stage.innerHTML=`${criticalPathView(false)}<div class="cp-paths"><button class="cp-choice" data-path="ac">A→C（7日）</button><button class="cp-choice" data-path="bd">B→D（5日）</button></div>`;
    stage.querySelectorAll('.cp-choice').forEach(b=>b.onclick=()=>{
      if(b.dataset.path==='ac'){
        b.classList.add('good');lessonInteractiveDone=true;
        stage.querySelector('.cp-network').outerHTML=criticalPathView(true).split('<div class="lesson-copy">')[0];
        showLessonFeedback('⭕ 正解。7日のA→Cが最長なのでクリティカルパスです。');
      }else{
        b.classList.add('bad');showLessonFeedback('5日より7日の経路の方が全体完了を制約します。',true);
        setTimeout(()=>b.classList.remove('bad'),700);
      }
    });
  }

  if(type==='sla'){
    stage.innerHTML=`${slaView('idle')}<div class="micro-options"><button class="micro-option" data-ticket="major">全社停止を先に対応</button><button class="micro-option" data-ticket="minor">表示崩れを先に対応</button></div>`;
    stage.querySelectorAll('.micro-option').forEach(b=>b.onclick=()=>{
      if(b.dataset.ticket==='major'){
        b.classList.add('good');lessonInteractiveDone=true;
        showLessonFeedback('⭕ 影響範囲と緊急度が大きく、目標復旧時間も厳しい全社停止を優先します。');
      }else{
        b.classList.add('bad');showLessonFeedback('影響範囲・緊急度・SLAを見比べましょう。',true);
        setTimeout(()=>b.classList.remove('bad'),700);
      }
    });
  }

  if(type==='iprights'){
    const cases=[
      {q:'新しい省エネ機構の発明',a:'特許権'},
      {q:'自作したゲームプログラム',a:'著作権'},
      {q:'新商品のブランドロゴ',a:'商標権'},
      {q:'新しい電気ケトルの外観デザイン',a:'意匠権'}
    ];
    const rights=['特許権','著作権','商標権','意匠権'];
    const draw=()=>{
      const c=cases[rightsSteps];
      if(!c){lessonInteractiveDone=true;stage.innerHTML=rightsView(4);showLessonFeedback('✅ 4つすべて仕分けできました。');return;}
      stage.innerHTML=`<div style="text-align:center;font-size:20px;font-weight:900;margin-bottom:14px">${c.q}</div><div class="micro-options">${rights.map(r=>`<button class="micro-option" data-r="${r}">${r}</button>`).join('')}</div>`;
      stage.querySelectorAll('.micro-option').forEach(b=>b.onclick=()=>{
        if(b.dataset.r===c.a){b.classList.add('good');rightsSteps++;showLessonFeedback(`⭕ ${c.a} が最も近い分類です。`);setTimeout(draw,450);}
        else{b.classList.add('bad');showLessonFeedback('保護したい対象が「発明・著作物・ブランドの目印・物品のデザイン」のどれか考えてみましょう。',true);setTimeout(()=>b.classList.remove('bad'),650);}
      });
    };
    draw();
  }

  if(type==='breakeven'){
    stage.innerHTML=`<div id="beDynamic">${breakEvenView(false)}</div><div class="be-controls"><button class="purple-btn" id="showBE">損益分岐点を表示</button></div>`;
    document.getElementById('showBE').onclick=()=>{
      document.getElementById('beDynamic').innerHTML=breakEvenView(true);
      const btn=document.getElementById('showBE');
      btn.textContent='✓ 損益分岐点を確認済み';
      btn.disabled=true;
      lessonInteractiveDone=true;
      showLessonFeedback('売上高と総費用が等しい交点では利益は0です。交点より左は赤字、右は黒字になります。');
    };
  }

  if(type==='binarysearch'){
    stage.innerHTML=`${searchView(false)}
      <div class="micro-options"><button class="micro-option" data-side="left">← 左側を残す</button><button class="micro-option" data-side="right">右側を残す →</button></div>`;
    stage.querySelectorAll('.micro-option').forEach(b=>{
      b.addEventListener('click',()=>{
        if(b.dataset.side==='right'){
          b.classList.add('good');
          lessonInteractiveDone=true;
          stage.querySelector('.search-array').innerHTML=[3,8,15,23,37,42,61].map((v,i)=>`<div class="search-cell ${i===3?'mid':''} ${i===4?'target':''} ${i<=3?'gone':''}">${v}</div>`).join('');
          showLessonFeedback('🎉 正解！ 37 > 23 なので、左半分を捨てて右側を残します。');
        }else{
          b.classList.add('bad');
          showLessonFeedback('💡 37は23より大きいですね。大きい値が並んでいる側を残します。',true);
          setTimeout(()=>b.classList.remove('bad'),900);
        }
      });
    });
  }
}

function renderLessonQuiz(quiz,stage){
  stage.innerHTML=`<div class="micro-options" id="lessonQuizOptions">${quiz.options.map((o,i)=>`<button class="micro-option" data-i="${i}">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}</div>`;
  stage.querySelectorAll('.micro-option').forEach(b=>{
    b.addEventListener('click',()=>{
      if(lessonQuizDone) return;
      const i=Number(b.dataset.i);
      if(i===quiz.answer){
        b.classList.add('good');
        lessonQuizDone=true;
        lessonInteractiveDone=true;
        stage.querySelectorAll('.micro-option').forEach(x=>x.disabled=true);
        showLessonFeedback('⭕ 正解！ '+quiz.explain);
      }else{
        b.classList.add('bad');
        showLessonFeedback('もう一度考えてみましょう。',true);
        setTimeout(()=>b.classList.remove('bad'),800);
      }
    });
  });
}

document.getElementById('lessonPrev')?.addEventListener('click',()=>{
  if(lessonStep>0){lessonStep--;resetLessonState();renderLesson();}
});
document.getElementById('lessonNext')?.addEventListener('click',()=>{
  if(lessonCompleteMode){
    lessonCompleteMode=false;
    document.getElementById('lessonPrev').style.display='';
    showScreen('map');
    updateCourseUI();
    return;
  }
  const lesson=LESSONS[activeLesson];
  const page=lesson.pages[lessonStep];
  if((page.interactive||page.quiz) && !lessonInteractiveDone){
    popToast('このステップをクリアしてから進みましょう');
    return;
  }
  if(lessonStep<lesson.pages.length-1){
    lessonStep++;
    resetLessonState();
    renderLesson();
  }else{
    completeLesson();
  }
});
function completeLessonLegacyV376(){
  const lesson=LESSONS[activeLesson];
  const old=profile.lessonProgress[activeLesson]||0;
  profile.lessonProgress[activeLesson]=100;
  // 教材を読んだ事実と、問題で確認した習熟度は分けて扱う。
  // 習熟度は診断・問題演習の回答結果から更新する。
  profile.xp += old<100?50:15;
  saveProfile();
  updateCourseUI();

  const reviewLessonCompleted=activeReviewJourneyId?markJourneyLessonDone(activeReviewJourneyId,activeLesson):false;
  const reviewJourneyId=reviewLessonCompleted?activeReviewJourneyId:null;

  if(lesson.core){
    const completedId=activeLesson;
    const earned=old<100?50:15;
    lessonCompleteMode=false;
    popToast(`${lesson.title} 学習完了　+${earned} XP`);
    if(reviewLessonCompleted){
      activeReviewJourneyId=null;
      showScreen('problems');
      startQuiz('journey:'+reviewJourneyId);
    }else{
      showScreen('problems');
      startQuiz('coretopic:'+completedId);
    }
    return;
  }

  document.getElementById('lessonHeadline').textContent='レッスン完了！';
  document.getElementById('lessonCopy').textContent=reviewLessonCompleted?'次は類題へ進みます。':'';
  document.getElementById('lessonStage').innerHTML=`
    <div class="lesson-complete">
      <div class="lesson-complete-icon">🏆</div>
      <h2>${lesson.title} クリア</h2>
      <div class="lesson-complete-xp">+${old<100?50:15} XP</div>
      <span class="mastery-change">教材の学習を記録しました</span>
      ${reviewLessonCompleted?'<button class="lesson-review-next" id="lessonReviewNext">類題で確認 →</button>':''}
      ${(!reviewLessonCompleted && CORE_A_IDS.includes(activeLesson))?`<button class="lesson-topic-practice" id="lessonTopicPractice">このテーマを問題で仕上げる →</button><div class="topic-practice-note">${CORE_A_TOPIC_PRACTICE_COUNTS[activeLesson]||3}問で、この解説だけで判断できる内容を確認します。複数テーマをまたぐ比較問題は章末チェックで扱います。</div>`:''}
    </div>`;
  if(reviewLessonCompleted){
    document.getElementById('lessonReviewNext')?.addEventListener('click',()=>{const id=reviewJourneyId;activeReviewJourneyId=null;showScreen('problems');startQuiz('journey:'+id);});
  }
  document.getElementById('lessonTopicPractice')?.addEventListener('click',()=>{
    const id=activeLesson;
    showScreen('problems');
    startQuiz('coretopic:'+id);
  });
  document.getElementById('lessonCheck').className='lesson-check';
  document.getElementById('lessonPrev').style.display='none';
  document.getElementById('lessonStepLabel').textContent='完了';
  const next=document.getElementById('lessonNext');
  next.textContent='学習マップへ';
  lessonCompleteMode=true;
}
function completeLesson(){
  const protectedCore=fequestProtectedLessonIsCoreV376(activeLesson);
  const result=completeLessonLegacyV376();
  if(protectedCore)fequestProtectedLessonProviderV376().clearCurrent();
  return result;
}

// Home main quest starts the weakest matching implemented lesson.
function pickLessonForSkill(skill){
  const ids=(typeof CORE_A_IDS!=='undefined'?CORE_A_IDS:Object.keys(LESSONS)).filter(id=>LESSONS[id].skill===skill);
  const incomplete=ids.find(id=>(profile.lessonProgress?.[id]||0)<100);
  return incomplete || ids[0] || 'binarysearch';
}
document.getElementById('startQuest')?.addEventListener('click',()=>{
  const weak=sortedSkills()[0]?.[0]||'アルゴリズム';
  startLesson(pickLessonForSkill(weak));
});



