  root.innerHTML=bMockItems.map((_,i)=>`<button class="bmock-nav-q ${bMockAnswers[i]!==null?'answered':''} ${bMockFlags.has(i)?'flagged':''} ${i===bMockIndex?'current':''}" data-bmq="${i}">${i+1}</button>`).join('');
