let currentBFilter='all';
let bTracePacketV376=null;
let bTraceGradeBusyV376=false;
let bTraceFinalResultV376=null;
function bTraceBridgeV376(){
  const bridge=globalThis.FEQUEST_V376_B_TRACE;
  if(!bridge||typeof bridge.start!=='function'||typeof bridge.grade!=='function'||typeof bridge.next!=='function')throw new Error('v376_b_trace_bridge_missing');
  return bridge;
}
function bTraceGenericTitleV376(ex){return ex?.concept?`${ex.concept}・トレース演習`:'アルゴリズム・トレース演習';}
function bTraceApplyPacketV376(packet,{resetMessage=true}={}){
  if(!packet||typeof packet!=='object'||!packet.traceSegment||!Array.isArray(packet.traceSegment.steps)||!packet.traceSegment.steps.length)throw new Error('v376_b_trace_packet_invalid');
  const segment=packet.traceSegment;
  bTracePacketV376=packet;
  currentB={
    id:packet.parentId,
    title:segment.title||bTraceGenericTitleV376(packet),
    icon:segment.icon||'💻',
    concept:packet.concept||segment.concept||'アルゴリズム',
    level:packet.level||segment.level||'',
    code:Array.isArray(segment.code)?[...segment.code]:[],
    array:Array.isArray(segment.array)?[...segment.array]:segment.array,
    target:segment.target,
    list:Array.isArray(segment.list)?[...segment.list]:segment.list,
    matrix:Array.isArray(segment.matrix)?segment.matrix.map(row=>Array.isArray(row)?[...row]:row):segment.matrix,
    objectName:segment.objectName,
    tree:segment.tree,
    steps:segment.steps.map(step=>({...step})),
  };
  bStepIndex=-1;
  bPredictionSatisfied=true;
  lastBState={};
  document.getElementById('bLabTitle').textContent=currentB.title;
  document.getElementById('bLabMeta').textContent=`科目B・${currentB.concept}・${currentB.level}`;
  document.getElementById('bCode').innerHTML=currentB.code.map((line,i)=>`<div class="b-code-line" data-bline="${i}">${escapeHtml(line)}</div>`).join('');
  resetBView();
  const progress=packet.phase==='tail'?80:Math.max(0,Math.min(80,(Number(packet.ordinal)-1)*40));
  document.getElementById('bTraceProgress').style.width=`${progress}%`;
  if(!resetMessage)document.getElementById('bTraceMessage').textContent='予測正解。続きの区間を1行ずつ追跡してください。';
}
function bTraceRecordStudyPositionV376(ordinal,stepIndex,complete=false,tail=null){
  const active=globalThis.studyActiveV373;
  if(!active||active.screen!=='trace'||active.bmode!=='trace')return;
  const rec=profile.dailyPlans[active.date];
  rec.blockProgressV373=rec.blockProgressV373||{};
  rec.blockProgressV373[active.task.slot]={seconds:active.seconds,screen:'trace',bid:currentB.id,traceV376:{ordinal,stepIndex,complete,...(tail?{phase:'tail',choiceIndex:tail.choiceIndex}:{})}};
  if(complete)rec.done[active.task.slot]=true;
}
async function bTraceShowPredictionV376(){
  const packet=bTracePacketV376;
  if(!packet||bTraceGradeBusyV376)return;
  bPredictionSatisfied=false;
  const box=document.getElementById('predictionBox');
  box.classList.add('show');
  document.getElementById('predictionTitle').textContent='⚡ 次を予測：'+packet.stem;
  const root=document.getElementById('predictionOptions');
  root.innerHTML='';
  packet.options.forEach((option,index)=>{
    const button=document.createElement('button');
    button.className='prediction-option';
    button.textContent=option;
    button.onclick=async()=>{
      if(bTraceGradeBusyV376)return;
      bTraceGradeBusyV376=true;
      root.querySelectorAll('button').forEach(node=>node.disabled=true);
      try{
        const alreadyScored=bTraceBridgeV376().state().resolvedOrdinals.includes(packet.ordinal);
        const result=alreadyScored?(bTraceFinalResultV376||{correct:true}):await bTraceBridgeV376().grade(packet.questionId,index);
        if(result.tail)bTraceFinalResultV376=result;
        if(!result.correct){
          button.classList.add('bad');
          popToast(packet.hint?`ヒント：${packet.hint}`:'現在の状態と次に実行する行を確認しましょう');
          setTimeout(()=>button.classList.remove('bad'),700);
          root.querySelectorAll('button').forEach(node=>node.disabled=false);
          return;
        }
        button.classList.add('good');
        bPredictionSatisfied=true;
        document.getElementById('bTraceMessage').textContent=result.explanation||'予測した状態と実際の処理を対応させて確認しましょう。';
        if(!alreadyScored){
          popToast('予測正解！ +5 XP');
          profile.xp+=5;
        }
        if(packet.ordinal===2){
          box.classList.remove('show');
          bTraceRecordStudyPositionV376(2,-1,false,result.tail);
          if(!saveProfile())throw new Error('b_trace_checkpoint_save_failed');
          bTraceApplyPacketV376(result.tail);
          return;
        }
        bTraceRecordStudyPositionV376(2,-1);
        if(!saveProfile())throw new Error('b_trace_checkpoint_save_failed');
        const nextPacket=await bTraceBridgeV376().next();
        if(nextPacket){
          bTraceApplyPacketV376(nextPacket,{resetMessage:false});
        }else{
          box.classList.remove('show');
          finishBExercise();
        }
      }catch(error){
        bTraceBridgeV376().reportError?.(error);
        root.querySelectorAll('button').forEach(node=>node.disabled=false);
      }finally{
        bTraceGradeBusyV376=false;
        if(globalThis.studyActiveV373)globalThis.studyActiveV373.last=performance.now();
      }
    };
    root.appendChild(button);
  });
}
function traceNextRecommendation(){
  const ex=B_EXERCISES.find(item=>(profile.bProgress?.[item.id]||0)<100);
  return ex?{id:ex.id,title:bTraceGenericTitleV376(ex),level:ex.level||'',concept:ex.concept||'アルゴリズム'}:null;
}
function renderTraceNextCard(){
  const title=document.getElementById('bTraceNextTitle'),desc=document.getElementById('bTraceNextDesc'),action=document.getElementById('bTraceNextAction');
  if(!title||!desc||!action)return;
  const next=traceNextRecommendation();
  if(next){title.textContent=next.title;desc.textContent=[next.level,next.concept].filter(Boolean).join('・');action.textContent='この演習を始める →';action.onclick=()=>startBExercise(next.id);return;}
  title.textContent='アルゴリズム20演習は完了しました';desc.textContent='次の科目B演習へ進めます。';action.textContent='次の科目Bへ →';action.onclick=()=>{try{const rec=subjectBHubRecommendation();launchSubjectBRecommendation(rec)}catch(_e){showBList()}};
}
