function renderBGrid(){
  const root=document.getElementById('bExerciseGrid');if(!root)return;
  root.innerHTML='';
  const done=B_EXERCISES.filter(ex=>(profile.bProgress?.[ex.id]||0)>=100).length;
  const visible=B_EXERCISES.filter(ex=>currentBFilter==='all'||ex.level===currentBFilter);
  const nextId=traceNextRecommendation()?.id;
  visible.forEach(ex=>{
    const pct=profile.bProgress?.[ex.id]||0,card=document.createElement('div');
    card.className='b-card'+(pct>=100?' done':'')+(ex.id===nextId?' b-next-highlight':'');
    const diffClass=ex.level==='標準'?'medium':ex.level==='応用'?'hard':'';
    card.innerHTML=`<div class="b-card-top"><div class="b-card-icon">💻</div><div><div class="b-card-title">${escapeHtml(bTraceGenericTitleV376(ex))}</div><div class="b-card-meta">${escapeHtml(ex.concept||'アルゴリズム')}</div></div></div><div class="b-card-desc">途中状態を1行ずつ追跡し、2回の予測問題で確認します。</div><div class="b-card-bottom"><span class="difficulty ${diffClass}">${escapeHtml(ex.level||'')}</span>${pct>=100?'<span class="b-check">✓ 完了</span>':''}<button class="b-start" data-bex="${ex.id}">${pct>=100?'もう一度':'開始'}</button></div>`;
    root.appendChild(card);
  });
  const progress=document.getElementById('bProgressText');
  if(progress){const levels=['基礎','標準','応用'].map(level=>{const all=B_EXERCISES.filter(item=>item.level===level).length,clear=B_EXERCISES.filter(item=>item.level===level&&(profile.bProgress?.[item.id]||0)>=100).length;return `${level}${clear}/${all}`}).join(' ・ ');progress.innerHTML=`<div>${done} / ${B_EXERCISES.length}</div><div style="font-size:14px;color:#8965ab;margin-top:2px">${levels}</div>`;}
  root.querySelectorAll('[data-bex]').forEach(button=>button.onclick=()=>startBExercise(button.dataset.bex));
  renderTraceNextCard();
}

document.getElementById('mapTrace')?.addEventListener('click',()=>{
  showScreen('trace');
  showBList();
});

function showBListLegacyV376(){
  stopBMockTimer();
  document.getElementById('bSelect').classList.remove('hidden');
  document.getElementById('secSelect')?.classList.add('hidden');
  document.getElementById('bMockSelect')?.classList.add('hidden');
  document.getElementById('bMockExam')?.classList.remove('show');
  document.getElementById('bMockResult')?.classList.remove('show');
  document.getElementById('bLab').classList.remove('show');
  renderBGrid();
}
function showBList(){bTraceBridgeV376().clear();bTracePacketV376=null;currentB=null;return showBListLegacyV376();}
document.getElementById('bBackToList')?.addEventListener('click',showBList);
document.getElementById('bNextExercise')?.addEventListener('click',continueSubjectBFlow);

async function startBExercise(id,resume=null){
  const meta=B_EXERCISES.find(item=>item.id===id);if(!meta)return false;
  bTraceFinalResultV376=null;
  document.getElementById('bSelect').classList.add('hidden');
  document.getElementById('bLab').classList.add('show');
  document.getElementById('bComplete').classList.remove('show');
  document.getElementById('bLabTitle').textContent=bTraceGenericTitleV376(meta);
  document.getElementById('bLabMeta').textContent='科目B・問題を読み込み中…';
  document.getElementById('bCode').innerHTML='<div class="sub">保護されたトレースを読み込み中…</div>';
  document.getElementById('bStep').disabled=true;
  try{
    if(resume&&(!Number.isInteger(resume.ordinal)||resume.ordinal<1||resume.ordinal>2||!Number.isInteger(resume.stepIndex)||resume.stepIndex<-1||resume.complete))throw new Error('b_trace_resume_invalid');
    const packet=resume?.phase==='tail'?await bTraceBridgeV376().resumeTail(id,resume.choiceIndex):resume?await bTraceBridgeV376().resume(id,resume.ordinal):await bTraceBridgeV376().start(id);
    if(resume&&(resume.stepIndex>=packet.traceSegment.steps.length||(resume.phase==='tail'&&resume.stepIndex===packet.traceSegment.steps.length-1)))throw new Error('b_trace_resume_step_invalid');
    bTraceApplyPacketV376(packet);
    if(resume&&resume.stepIndex>=0){bStepIndex=resume.stepIndex;renderBStep(currentB.steps[bStepIndex]);}
    return true;
  }catch(error){
    bTraceBridgeV376().reportError?.(error);
    document.getElementById('bLab').classList.remove('show');
    document.getElementById('bSelect').classList.remove('hidden');
    return false;
  }
}

function escapeHtml(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function resetBView(){
  bStepIndex=-1;bPredictionSatisfied=true;lastBState={};
  document.querySelectorAll('.b-code-line').forEach(line=>line.classList.remove('active'));
  document.getElementById('bStateGrid').innerHTML='<div class="sub">まだ実行していません。</div>';
  document.getElementById('bVisual').innerHTML='<div class="sub" style="text-align:center">1行ずつ実行し、区間の最後で次の状態を予測します。</div>';
  document.getElementById('bTraceMessage').textContent=bTracePacketV376?.ordinal===2?'続きの区間を1行ずつ実行してください。':'最初の行から1行ずつ実行してください。';
  const base=bTracePacketV376?.phase==='tail'?80:bTracePacketV376?Math.max(0,(Number(bTracePacketV376.ordinal)-1)*40):0;
  document.getElementById('bTraceProgress').style.width=String(base)+'%';
  document.getElementById('predictionBox').classList.remove('show');
  document.getElementById('bStep').disabled=!currentB;
  document.getElementById('bStep').textContent='▶ 次の行を実行';
  document.getElementById('bComplete').classList.remove('show');
}
document.getElementById('bReset')?.addEventListener('click',resetBView);

document.getElementById('bStep')?.addEventListener('click',()=>{
  if(!currentB) return;
  if(!bPredictionSatisfied){
    popToast('予測問題に答えてから進みましょう');
    return;
  }
  if(bStepIndex < currentB.steps.length-1){
    bStepIndex++;
    renderBStep(currentB.steps[bStepIndex]);
  }
});

function renderBStep(step){
  if(!currentB||!bTracePacketV376)return;
  document.querySelectorAll('.b-code-line').forEach(line=>line.classList.remove('active'));
  const active=document.querySelector(`.b-code-line[data-bline="${step.line}"]`);if(active)active.classList.add('active');
  renderBState(step.state||{});renderBVisual(step);
  document.getElementById('bTraceMessage').textContent=step.msg||'';
  const segmentFraction=(bStepIndex+1)/Math.max(1,currentB.steps.length);
  const overall=bTracePacketV376.phase==='tail'?80+segmentFraction*20:((Number(bTracePacketV376.ordinal)-1)+segmentFraction)/2*80;
  document.getElementById('bTraceProgress').style.width=String(Math.max(0,Math.min(100,overall)))+'%';
  if(bStepIndex===currentB.steps.length-1){document.getElementById('bStep').disabled=true;if(bTracePacketV376.phase==='tail')finishBExercise();else void bTraceShowPredictionV376();}
  else{bPredictionSatisfied=true;document.getElementById('predictionBox').classList.remove('show');}
}

function renderBState(state){
  const grid=document.getElementById('bStateGrid');
  grid.innerHTML='';
  Object.entries(state).forEach(([k,v])=>{
    const changed=lastBState[k]!==undefined && String(lastBState[k])!==String(v);
    const d=document.createElement('div');
    d.className='state-card';
    d.innerHTML=`<div class="state-key">${escapeHtml(k)}</div><div class="state-value ${changed?'changed':''}">${escapeHtml(v)}</div>`;
    grid.appendChild(d);
  });
  lastBState={...state};
}

function renderBVisual(step){
  const v=document.getElementById('bVisual');

  if(currentB.matrix){
    const focus=step.matrixFocus||[];
    v.innerHTML=`<div class="trace-matrix">${currentB.matrix.map((row,r)=>`
      <div class="trace-matrix-row">${row.map((x,c)=>`<div class="trace-matrix-cell ${focus[0]===r&&focus[1]===c?'focus':''}">${x}<span class="trace-matrix-index">${r},${c}</span></div>`).join('')}</div>`).join('')}</div>`;
    return;
  }

  if(step.queue){
    v.innerHTML=`<div class="trace-queue-label">先頭 → 末尾</div><div class="trace-queue">${step.queue.length?step.queue.map(x=>`<div class="trace-queue-item">${escapeHtml(x)}</div>`).join(''):'<div class="sub">空</div>'}</div>`;
    return;
  }

  if(currentB.list){
    v.innerHTML=linkedListTraceViewV365(currentB.list,step.currentNode,step.visited||[]);
    return;
  }

  if(step.bits){
    const labels={x:'x',mask:'mask',result:'AND'};
    v.innerHTML=`<div class="trace-bits">${Object.entries(step.bits).map(([k,val])=>`
      <div class="trace-bit-row"><div class="trace-bit-label">${labels[k]||escapeHtml(k)}</div><div class="trace-bit-value">${escapeHtml(val)}</div></div>`).join('')}</div>`;
    return;
  }

  if(step.object){
    const title=currentB.objectName||'object';
    v.innerHTML=`<div class="trace-object"><div class="trace-object-title">${escapeHtml(title)}</div>${Object.entries(step.object).map(([k,val])=>`
      <div class="trace-object-prop"><span>${escapeHtml(k)}</span><b>${escapeHtml(val)}</b></div>`).join('')}</div>`;
    return;
  }

  if(currentB.array){
    const arr=step.arrayState||currentB.array;
    if(currentB.id==='linear_search'||currentB.id==='binary_search_b'){
      v.innerHTML=searchTraceViewV366(currentB.id,arr,currentB.target,step);
      return;
    }
    if(currentB.id==='bubble_sort_b'||currentB.id==='selection_sort_b'){
      v.innerHTML=sortTraceViewV367(currentB.id,arr,step);
      return;
    }
    v.innerHTML=`<div class="trace-array">${
      arr.map((x,i)=>`<div class="trace-array-cell ${step.focus===i?'focus':''} ${step.found===i?'found':''}">${x}<span class="trace-array-index">${i}</span></div>`).join('')
    }</div>${currentB.target!==undefined?`<div class="visit-path">target = ${currentB.target}</div>`:''}`;
    return;
  }

  if(step.stack){
    v.innerHTML=`<div class="sub" style="text-align:center;margin-bottom:6px">トップ</div><div class="trace-stack">${step.stack.map(x=>`<div class="trace-stack-item">${escapeHtml(x)}</div>`).join('')}</div>`;
    return;
  }

  if(currentB.tree){
    const visited=step.visited||[];
    const mark=n=>visited.includes(n)?`[${n}]`:n;
    v.innerHTML=`<div class="tree-view">       ${mark('A')}
      /   \\
    ${mark('B')}     ${mark('C')}
   / \\
 ${mark('D')}   ${mark('E')}</div>
 <div class="visit-path">出力：${escapeHtml(step.state?.output||'—')}</div>`;
    return;
  }

  v.innerHTML='<div class="sub" style="text-align:center">変数の変化を右上のSTATEで追いましょう。</div>';
}

function showBPrediction(){throw new Error('v376_b_prediction_must_use_server_bridge');}

function finishBExerciseLegacyV376(){
  const old=profile.bProgress[currentB.id]||0;
  profile.bProgress[currentB.id]=100;
  profile.skills['アルゴリズム']=clamp((profile.skills['アルゴリズム']||50)+(old<100?3:1),0,100);
  profile.xp += old<100?80:20;
  saveProfile();

  document.getElementById('bCompleteXp').textContent=`+${old<100?80:20} XP`;
  document.getElementById('bCompleteText').textContent=`「${currentB.concept}」のトレースを完了しました。`;
  document.getElementById('bComplete').classList.add('show');
  document.getElementById('bStep').disabled=true;
  document.getElementById('bStep').textContent='✓ 完了';
  renderBGrid();
  updateSubjectBCompletionButton('bNextExercise');
}
function finishBExercise(){
  bTraceRecordStudyPositionV376(2,-1,true);
  bTraceBridgeV376().clear();bTracePacketV376=null;
  const result=finishBExerciseLegacyV376();
  const active=globalThis.studyActiveV373;
  if(active?.screen==='trace'&&active.bmode==='trace'){
    globalThis.studyActiveV373=null;
    document.getElementById('studyBlockBarV373')?.remove();document.body.classList.remove('study-block-active-v373');
  }
  return result;
}



