function bFinalFormatOf(item){
  if(item.kind==='security') return item.log?'ログ読解':'ケース判断';
  return item.format||'トレース';
}

function makeFinalAlgoFromTrace(){return undefined;}/* FEQUEST_V376_REDACTED_RESIDUAL_QUESTION_FUNCTION */

function makeFinalAlgoFromCompound(){return undefined;}/* FEQUEST_V376_REDACTED_RESIDUAL_QUESTION_FUNCTION */

function makeFinalSecurity(){return undefined;}/* FEQUEST_V376_REDACTED_RESIDUAL_QUESTION_FUNCTION */

function makeFinalAlgoExam(item){
  const src=structuredClone(item),correct=src.options[src.a],options=shuffled([...src.options]);
  return {
    ...src,id:`exam:${src.id}`,sourceId:src.id,kind:'algo',
    options,a:options.indexOf(correct),correctText:correct,
    studyMode:'exam'
  };
}
function finalAlgoPool(){
  return B_EXAM_ALGO_ITEMS.map(makeFinalAlgoExam);
}

const B_FINAL_APPLIED_DOMAINS=new Set(['再帰・関数','木構造','リスト','スタック・キュー','ビット列','探索・整列']);

function bFinalAlgoSeen(item){
  return profile.bFinalStats?.[`algo:${item.id}`]?.seen||0;
}
function pickFinalAlgoCandidate(pool,selected){
  const formatCounts={};
  selected.forEach(x=>formatCounts[x.format||'トレース']=(formatCounts[x.format||'トレース']||0)+1);
  return [...pool].sort((a,b)=>{
    const sa=bFinalAlgoSeen(a),sb=bFinalAlgoSeen(b);
    if(sa!==sb)return sa-sb;
    const fa=formatCounts[a.format||'トレース']||0,fb=formatCounts[b.format||'トレース']||0;
    if(fa!==fb)return fa-fb;
    return Math.random()-.5;
  })[0]||null;
}
function pickSecurityForFinal(pool,n,used){
  const sorted=[...pool].filter(s=>!used.has(s.id)).sort((a,b)=>{
    const sa=profile.bFinalStats?.[`sec:${a.id}`]?.seen||0,sb=profile.bFinalStats?.[`sec:${b.id}`]?.seen||0;
    if(sa!==sb)return sa-sb;
    return Math.random()-.5;
  });
  const out=sorted.slice(0,n);
  out.forEach(s=>used.add(s.id));
  return out;
}

function buildBFinal(){
  // 40問の本番型アルゴリズムプールから、
  // 10分野を最低1問ずつ・標準8問/応用8問になるよう16問を構成する。
  const selected=[];
  const used=new Set();

  B_FINAL_ALGO_DOMAINS.forEach(domain=>{
    const desired=B_FINAL_APPLIED_DOMAINS.has(domain)?'応用':'標準';
    let pool=B_EXAM_ALGO_ITEMS.filter(x=>x.domain===domain&&x.level===desired&&!used.has(x.id));
    if(!pool.length)pool=B_EXAM_ALGO_ITEMS.filter(x=>x.domain===domain&&!used.has(x.id));
    const pick=pickFinalAlgoCandidate(pool,selected);
    if(pick){selected.push(pick);used.add(pick.id);}
  });

  const fillLevel=(level,target)=>{
    while(selected.filter(x=>x.level===level).length<target){
      const pool=B_EXAM_ALGO_ITEMS.filter(x=>x.level===level&&!used.has(x.id));
      const pick=pickFinalAlgoCandidate(pool,selected);
      if(!pick)break;
      selected.push(pick);used.add(pick.id);
    }
  };
  fillLevel('応用',8);
  fillLevel('標準',8);

  // 念のため不足時だけ未使用問題で補完する。
  while(selected.length<16){
    const pick=pickFinalAlgoCandidate(B_EXAM_ALGO_ITEMS.filter(x=>!used.has(x.id)),selected);
    if(!pick)break;
    selected.push(pick);used.add(pick.id);
  }
  const algo=selected.slice(0,16).map(makeFinalAlgoExam);

  // 情報セキュリティ4問は、ログ読解2問＋ケース判断2問を固定。
  const secUsed=new Set();
  const secLogs=pickSecurityForFinal(SECURITY_SCENARIOS.filter(s=>s.log),2,secUsed);
  const secCases=pickSecurityForFinal(SECURITY_SCENARIOS.filter(s=>!s.log),2,secUsed);
  const secPool=[...secLogs,...secCases].map(makeFinalSecurity);

  return shuffled([...algo,...secPool]);
}

function renderBFinalReadiness(){
  const box=document.getElementById('bFinalReadiness');
  const icon=document.getElementById('bFinalReadinessIcon'),kicker=document.getElementById('bFinalReadinessKicker'),title=document.getElementById('bFinalReadinessTitle'),desc=document.getElementById('bFinalReadinessDesc'),prep=document.getElementById('bFinalPrepAction'),start=document.getElementById('bFinalStart');
  if(!box||!icon||!kicker||!title||!desc||!prep||!start)return;
  const m=subjectBProgressMetrics();
  const days=examDaysRemaining();
  const taper=days!=null&&days>=0&&days<=3;
  const ready=m.algoDone===B_EXERCISES.length&&m.secDone===SECURITY_SCENARIOS.length&&m.practiceEvidence>=5;
  box.classList.toggle('ready',ready&&!taper);box.classList.toggle('warn',!ready||taper);
  if(taper){
    icon.textContent='⏱️';kicker.textContent='試験直前';title.textContent='100分の総合実戦は行いません';desc.textContent='残り3日以内は、新しい長時間実戦より今日の短い復習・確認を優先します。';prep.style.display='';prep.textContent='今日の学習へ →';prep.onclick=()=>showScreen('home');start.disabled=true;start.textContent='試験直前は総合実戦を停止中';return;
  }
  start.disabled=false;start.textContent='20問の総合実戦を開始 →';
  if(ready){
    icon.textContent='✅';kicker.textContent='開始前の確認';title.textContent='総合実戦を始められる状態です';desc.textContent='基礎演習と短い実戦を一通り経験しています。100分を確保できる日に実施してください。';prep.style.display='none';return;
  }
  const rec=subjectBHubRecommendation();
  icon.textContent=rec.icon||'📚';kicker.textContent='先に進めると効果的';title.textContent=rec.title;desc.textContent='総合実戦はいつでも利用できますが、未完了の基礎・短い実戦を先に進めると復習ポイントが明確になります。';prep.style.display='';prep.textContent='科目Bの続きへ →';prep.onclick=()=>launchSubjectBRecommendation(rec);
}

function renderBFinalMenu(){
  const hist=profile.bFinalHistory||[],best=hist.length?Math.max(...hist.map(h=>Number.isFinite(h.rate)?h.rate:Math.round((h.correct||0)/(h.total||20)*100))):null;
  document.getElementById('bFinalBest').textContent=best===null?'ベスト —':`ベスト ${best}%`;
  const root=document.getElementById('bFinalHistory'),rows=hist.slice(0,5);
  root.innerHTML=rows.length?rows.map(h=>`
    <div class="bmock-history-row">
      <div class="bmock-history-main"><b>${h.correct}/${h.total}問 正解</b><span>${escapeHtml(h.date||'')}</span></div>
      <div class="bmock-history-time">${bMockFormatTime(h.seconds||0)}</div>
      <div class="bmock-history-score">${Number.isFinite(h.rate)?h.rate:Math.round((h.correct||0)/(h.total||20)*100)}%</div>
    </div>`).join(''):'<div class="sub">まだ総合実戦の受験履歴はありません。</div>';
  renderBFinalReadiness();
  if(typeof renderSubjectBHub==='function')renderSubjectBHub();
}

function showBFinalMenu(){
  stopBFinalTimer();
  ['bSelect','secSelect','bMockSelect'].forEach(id=>document.getElementById(id)?.classList.add('hidden'));
  ['bLab','secLab','bMockExam','bMockResult','bCompoundExam','bCompoundResult','secMockExam','secMockResult','bFinalExam','bFinalResult'].forEach(id=>document.getElementById(id)?.classList.remove('show'));
  document.getElementById('bFinalSelect')?.classList.remove('hidden');
  renderBFinalMenu();
}


const BFINAL_RESUME_KEY='fequest_bfinal_resume_v1';
function clearBFinalResume(){
  try{localStorage.removeItem(BFINAL_RESUME_KEY)}catch(e){}
}
function saveBFinalResume(){
  if(!bFinalItems?.length||!document.getElementById('bFinalExam')?.classList.contains('show'))return false;
  try{
    const payload={
      version:1,appVersion:APP_VERSION,
      items:bFinalItems,answers:bFinalAnswers,flags:[...bFinalFlags],index:bFinalIndex,
      expiresAt:Date.now()+Math.max(0,bFinalSeconds)*1000,
      startedAt:bFinalStartedAt||Date.now(),savedAt:Date.now()
    };
    localStorage.setItem(BFINAL_RESUME_KEY,JSON.stringify(payload));
    return true;
  }catch(e){console.warn('B final resume save failed',e);return false}
}
function readBFinalResume(){
  try{return JSON.parse(localStorage.getItem(BFINAL_RESUME_KEY)||'null')}catch(e){return null}
}
function restoreBFinalResume(){
  const s=readBFinalResume();
  if(!s||!Array.isArray(s.items)||s.items.length!==20||!Array.isArray(s.answers)||s.answers.length!==20)return false;
  const remain=Math.ceil((Number(s.expiresAt||0)-Date.now())/1000);
  if(remain<=0){clearBFinalResume();return false}
  bFinalItems=s.items;
  bFinalAnswers=s.answers;
  bFinalFlags=new Set(s.flags||[]);
  bFinalIndex=Math.max(0,Math.min(19,Number(s.index)||0));
  bFinalSeconds=Math.min(B_FINAL_SECONDS,remain);
  bFinalStartedAt=Number(s.startedAt)||Date.now();
  lastBFinalAttempt=null;
  setBMode('final');
  document.getElementById('bFinalSelect')?.classList.add('hidden');
  document.getElementById('bFinalResult')?.classList.remove('show');
  document.getElementById('bFinalExam')?.classList.add('show');
  showScreen('trace',{replaceHistory:true,instant:true});
  renderBFinalQuestion();
  startBFinalTimer();
  return true;
}

const B_FINAL_ALGO_DOMAINS_V376=Object.freeze(["制御","一次元配列","二次元配列","再帰・関数","木構造","オブジェクト指向","リスト","スタック・キュー","ビット列","探索・整列"]);
const B_FINAL_APPLIED_DOMAINS_V376=new Set(["再帰・関数","木構造","リスト","スタック・キュー","ビット列","探索・整列"]);
const B_FINAL_HIGH_TRACE_IDS_V376=new Set(["bexam_ctrl_01","bexam_ctrl_04","bexam_arr_02","bexam_mat_01","bexam_mat_04","bexam_rec_05","bexam_tree_02","bexam_tree_04","bexam_list_04","bexam_sq_04","bexam_algo_01","bexam_algo_03","bexam_obj_04","bexam_bit_05","bexam_tree_05"]);
const B_FINAL_SECURITY_LOG_IDS_V376=new Set(["ransomware","logs","password_spray","exfiltration"]);
function bFinalBridgeV376(){
  const bridge=globalThis.FEQUEST_V376_B_FINAL;
  if(!bridge||typeof bridge.startSession!=='function'||typeof bridge.gradeSession!=='function')throw new Error('v376_b_final_bridge_missing');
  return bridge;
}
function bFinalAlgoSeenV376(item){return profile.bFinalStats?.[`algo:${item.id}`]?.seen||0}
function bFinalPickAlgoV376(pool,selected){
  const formatCounts={};
  selected.forEach(item=>{const format=item.format||'トレース';formatCounts[format]=(formatCounts[format]||0)+1});
  return [...pool].sort((a,b)=>{
    const sa=bFinalAlgoSeenV376(a),sb=bFinalAlgoSeenV376(b);if(sa!==sb)return sa-sb;
    const fa=formatCounts[a.format||'トレース']||0,fb=formatCounts[b.format||'トレース']||0;if(fa!==fb)return fa-fb;
    return Math.random()-.5;
  })[0]||null;
}
function bFinalRepairTraceFloorV376(input){
  const selected=[...input];
  let highCount=selected.filter(item=>B_FINAL_HIGH_TRACE_IDS_V376.has(item.id)).length;
  while(highCount<4){
    const used=new Set(selected.map(item=>item.id));
    const formatCounts={};selected.forEach(item=>{const format=item.format||'トレース';formatCounts[format]=(formatCounts[format]||0)+1});
    const swaps=[];
    selected.forEach((victim,index)=>{
      if(B_FINAL_HIGH_TRACE_IDS_V376.has(victim.id))return;
      B_EXAM_ALGO_ITEMS.filter(candidate=>B_FINAL_HIGH_TRACE_IDS_V376.has(candidate.id)&&!used.has(candidate.id)&&candidate.domain===victim.domain&&candidate.level===victim.level).forEach(candidate=>{
        const candidateFormat=candidate.format||'トレース',victimFormat=victim.format||'トレース';
        swaps.push({index,candidate,candidateSeen:bFinalAlgoSeenV376(candidate),formatLoad:(formatCounts[candidateFormat]||0)-(candidateFormat===victimFormat?1:0),victimSeen:bFinalAlgoSeenV376(victim)});
      });
    });
    swaps.sort((a,b)=>a.candidateSeen-b.candidateSeen||a.formatLoad-b.formatLoad||b.victimSeen-a.victimSeen||Math.random()-.5);
    if(!swaps.length)break;
    selected[swaps[0].index]=swaps[0].candidate;highCount++;
  }
  if(highCount<4)throw new Error('v376_b_final_trace_floor_unavailable');
  return selected;
}
function bFinalSelectAlgoV376(){
  const selected=[],used=new Set();
  B_FINAL_ALGO_DOMAINS_V376.forEach(domain=>{
    const desired=B_FINAL_APPLIED_DOMAINS_V376.has(domain)?'応用':'標準';
    let pool=B_EXAM_ALGO_ITEMS.filter(item=>item.domain===domain&&item.level===desired&&!used.has(item.id));
    if(!pool.length)pool=B_EXAM_ALGO_ITEMS.filter(item=>item.domain===domain&&!used.has(item.id));
    const pick=bFinalPickAlgoV376(pool,selected);if(pick){selected.push(pick);used.add(pick.id)}
  });
  const fillLevel=(level,target)=>{
    while(selected.filter(item=>item.level===level).length<target){
      const pick=bFinalPickAlgoV376(B_EXAM_ALGO_ITEMS.filter(item=>item.level===level&&!used.has(item.id)),selected);
      if(!pick)break;selected.push(pick);used.add(pick.id);
    }
  };
  fillLevel('応用',8);fillLevel('標準',8);
  while(selected.length<16){
    const pick=bFinalPickAlgoV376(B_EXAM_ALGO_ITEMS.filter(item=>!used.has(item.id)),selected);if(!pick)break;
    selected.push(pick);used.add(pick.id);
  }
  const repaired=bFinalRepairTraceFloorV376(selected.slice(0,16));
  const domainSet=new Set(repaired.map(item=>item.domain));
  if(repaired.length!==16||repaired.filter(item=>item.level==='応用').length!==8||repaired.filter(item=>item.level==='標準').length!==8||B_FINAL_ALGO_DOMAINS_V376.some(domain=>!domainSet.has(domain)))throw new Error('v376_b_final_algo_mix_invalid');
  return repaired.map(item=>{
    if(!item.protectedQuestionId)throw new Error('v376_b_final_algo_question_id_missing');
    return {kind:'algo',questionId:item.protectedQuestionId,sourceId:item.id};
  });
}
function bFinalPickSecurityV376(pool,n,used){
  const sorted=[...pool].filter(item=>!used.has(item.id)).sort((a,b)=>{
    const sa=profile.bFinalStats?.[`sec:${a.id}`]?.seen||0,sb=profile.bFinalStats?.[`sec:${b.id}`]?.seen||0;
    if(sa!==sb)return sa-sb;return Math.random()-.5;
  });
  const out=sorted.slice(0,n);out.forEach(item=>used.add(item.id));return out;
}
function bFinalSelectSecurityV376(){
  const used=new Set();
  const logs=bFinalPickSecurityV376(SECURITY_SCENARIOS.filter(item=>B_FINAL_SECURITY_LOG_IDS_V376.has(item.id)),2,used);
  const cases=bFinalPickSecurityV376(SECURITY_SCENARIOS.filter(item=>!B_FINAL_SECURITY_LOG_IDS_V376.has(item.id)),2,used);
  const selected=[...logs,...cases];
  if(selected.length!==4||logs.length!==2||cases.length!==2)throw new Error('v376_b_final_security_mix_invalid');
  return selected.map(item=>{
    const candidates=(item.steps||[]).filter(step=>Number(step.ordinal)>=2&&step.id);
    const step=candidates[Math.floor(Math.random()*candidates.length)]||null;
    if(!step)throw new Error('v376_b_final_security_step_missing');
    return {kind:'security',questionId:step.id,sourceId:item.id};
  });
}
function bFinalSelectDescriptorsV376(){
  const descriptors=shuffled([...bFinalSelectAlgoV376(),...bFinalSelectSecurityV376()]);
  if(descriptors.length!==20||new Set(descriptors.map(item=>item.questionId)).size!==20)throw new Error('v376_b_final_selection_invalid');
  return descriptors;
}
function bFinalProtectedItemV376(packet){
  if(!packet||!['algo','security'].includes(packet.kind)||!Array.isArray(packet.options)||packet.options.length!==4)throw new Error('v376_b_final_packet_invalid');
  const pairs=packet.options.map((text,serverIndex)=>({text,serverIndex})),mixed=shuffled(pairs);
  const common={
    _protectedQuestionId:packet.questionId,_serverMap:mixed.map(item=>item.serverIndex),
    sourceId:packet.parentId,kind:packet.kind,level:packet.level||'',title:packet.title||'',
    q:packet.stem,options:mixed.map(item=>item.text),
  };
  if(packet.kind==='algo')return {...common,id:`exam:${packet.parentId}`,domain:packet.domain||'擬似言語',format:packet.format||'トレース',context:packet.context||'',code:structuredClone(packet.code||[]),data:structuredClone(packet.data||[]),studyMode:'exam'};
  return {...common,id:`sec:${packet.parentId}:${Math.max(0,(Number(packet.ordinal)||1)-1)}`,concept:packet.concept||'情報セキュリティ',format:packet.format||'ケース判断',incident:structuredClone(packet.incident||{}),evidence:structuredClone(packet.evidence||[]),log:packet.log||null,risk:!!packet.risk,studyMode:'security'};
}
function bFinalClearProtectedV376(){try{return bFinalBridgeV376().clear()}catch(_e){return 0}}
function installBFinalCleanupV376(){
  const exam=document.getElementById('bFinalExam');
  document.getElementById('bFinalExit')?.addEventListener('click',()=>queueMicrotask(()=>{if(!exam?.classList.contains('show'))bFinalClearProtectedV376()}));
  document.getElementById('bFinalBackMenu')?.addEventListener('click',()=>queueMicrotask(bFinalClearProtectedV376));
}
let bFinalStartBusyV376=false;
let bFinalGradeBusyV376=false;
async function startBFinal(){
  const days=examDaysRemaining();
  if(days!=null&&days>=0&&days<=3){popToast('試験直前は100分の総合実戦ではなく、今日の短い確認を優先します');showScreen('home');return false;}
  if(bFinalStartBusyV376)return false;
  bFinalStartBusyV376=true;
  const startBtn=document.getElementById('bFinalStart'),retryBtn=document.getElementById('bFinalRetry');
  if(startBtn)startBtn.disabled=true;if(retryBtn)retryBtn.disabled=true;
  clearBFinalResume();bFinalClearProtectedV376();
  try{
    const descriptors=bFinalSelectDescriptorsV376();
    const packets=await bFinalBridgeV376().startSession(descriptors.map(item=>item.questionId));
    if(!Array.isArray(packets)||packets.length!==20)throw new Error('v376_b_final_packet_count_invalid');
    bFinalItems=packets.map(bFinalProtectedItemV376);
    if(bFinalItems.filter(item=>item.kind==='algo').length!==16||bFinalItems.filter(item=>item.kind==='security').length!==4)throw new Error('v376_b_final_runtime_mix_invalid');
    bFinalAnswers=Array(bFinalItems.length).fill(null);bFinalFlags=new Set();bFinalIndex=0;
    bFinalSeconds=B_FINAL_SECONDS;bFinalStartedAt=Date.now();lastBFinalAttempt=null;
    document.getElementById('bFinalSelect')?.classList.add('hidden');
    document.getElementById('bFinalResult')?.classList.remove('show');
    document.getElementById('bFinalExam')?.classList.add('show');
    renderBFinalQuestion();startBFinalTimer();saveBFinalResume();
    return true;
  }catch(error){
    bFinalBridgeV376().reportError?.(error);bFinalClearProtectedV376();
    document.getElementById('bFinalExam')?.classList.remove('show');document.getElementById('bFinalSelect')?.classList.remove('hidden');
    return false;
  }finally{
    if(startBtn)startBtn.disabled=false;if(retryBtn)retryBtn.disabled=false;bFinalStartBusyV376=false;
  }
}
function stopBFinalTimer(){if(bFinalTimerId){clearInterval(bFinalTimerId);bFinalTimerId=null}}
function startBFinalTimer(){
  stopBFinalTimer();updateBFinalTimer();
  bFinalTimerId=setInterval(()=>{bFinalSeconds--;updateBFinalTimer();if(bFinalSeconds>0&&bFinalSeconds%15===0)saveBFinalResume();if(bFinalSeconds<=0){stopBFinalTimer();finishBFinal(true)}},1000);
}
function updateBFinalTimer(){
  const t=document.getElementById('bFinalTimer');if(!t)return;
  t.textContent=bMockFormatTime(bFinalSeconds);
  t.classList.toggle('warn',bFinalSeconds<=15*60&&bFinalSeconds>5*60);
  t.classList.toggle('danger',bFinalSeconds<=5*60);
}

function finalAlgoDataHtml(item){
  return (item.data||[]).map(d=>`<div class="bfinal-data-card"><b>${escapeHtml(d.label||'補足')}</b>${escapeHtml(d.text||'')}</div>`).join('');
}

function renderBFinalQuestion(){
  const item=bFinalItems[bFinalIndex];if(!item)return;
  document.getElementById('bFinalTopMeta').textContent=`問題 ${bFinalIndex+1} / ${bFinalItems.length}`;
  document.getElementById('bFinalQNum').textContent=`Q${bFinalIndex+1}`;
  const type=document.getElementById('bFinalQType');
  type.textContent=item.kind==='security'?'情報セキュリティ':'擬似言語';
  type.classList.toggle('security',item.kind==='security');
  document.getElementById('bFinalQFormat').textContent=item.kind==='security'?bFinalFormatOf(item):`${item.domain||'擬似言語'}・${bFinalFormatOf(item)}`;

  const algo=document.getElementById('bFinalAlgoBlock'),sec=document.getElementById('bFinalSecurityBlock');
  if(item.kind==='algo'){
    algo.classList.remove('hidden');algo.hidden=false;
    sec.classList.add('hidden');sec.hidden=true;
    document.getElementById('bFinalAlgoContext').textContent=item.context||'';
    document.getElementById('bFinalCode').innerHTML=item.code.map((line,i)=>`<div class="bmock-code-line"><span class="ln">${i+1}</span><span>${escapeHtml(line)}</span></div>`).join('');
    document.getElementById('bFinalAlgoData').innerHTML=finalAlgoDataHtml(item);
  }else{
    algo.classList.add('hidden');algo.hidden=true;
    sec.classList.remove('hidden');sec.hidden=false;
    document.getElementById('bFinalSecIcon').textContent=item.incident.icon;
    document.getElementById('bFinalSecTitle').textContent=item.incident.title;
    document.getElementById('bFinalSecText').textContent=item.incident.text;
    document.getElementById('bFinalSecEvidence').innerHTML=securityMockEvidenceHtml(item);
  }

  document.getElementById('bFinalQuestion').textContent=item.q;
  const ans=bFinalAnswers[bFinalIndex];
  document.getElementById('bFinalOptions').innerHTML=item.options.map((op,i)=>`<button class="bfinal-option ${item.kind==='security'?'security':''} ${ans===i?'selected':''}" data-bfopt="${i}">${String.fromCharCode(65+i)}. ${escapeHtml(op)}</button>`).join('');
  document.querySelectorAll('[data-bfopt]').forEach(btn=>btn.onclick=()=>{bFinalAnswers[bFinalIndex]=Number(btn.dataset.bfopt);renderBFinalQuestion()});

  document.getElementById('bFinalPrev').disabled=bFinalIndex===0;
  document.getElementById('bFinalNext').textContent=bFinalIndex===bFinalItems.length-1?'提出へ':'次へ →';
  document.getElementById('bFinalFlag').classList.toggle('active',bFinalFlags.has(bFinalIndex));
  document.getElementById('bFinalFlag').textContent=bFinalFlags.has(bFinalIndex)?'★ 後で見る':'☆ 後で見る';
  document.getElementById('bFinalProgressMini').style.width=`${((bFinalIndex+1)/bFinalItems.length)*100}%`;
  renderBFinalNav();
}

function renderBFinalNav(){
  const root=document.getElementById('bFinalNavGrid');
  root.innerHTML=bFinalItems.map((item,i)=>`<button class="bfinal-nav-q ${item.kind==='security'?'security':'algo'} ${bFinalAnswers[i]!==null?'answered':''} ${bFinalFlags.has(i)?'flagged':''} ${i===bFinalIndex?'current':''}" data-bfq="${i}">${i+1}</button>`).join('');
  root.querySelectorAll('[data-bfq]').forEach(btn=>btn.onclick=()=>{bFinalIndex=Number(btn.dataset.bfq);renderBFinalQuestion()});
  const answered=bFinalAnswers.filter(x=>x!==null).length;
  const algo=bFinalItems.reduce((n,x,i)=>n+(x.kind==='algo'&&bFinalAnswers[i]!==null?1:0),0);
  const sec=bFinalItems.reduce((n,x,i)=>n+(x.kind==='security'&&bFinalAnswers[i]!==null?1:0),0);
  document.getElementById('bFinalAnswerCount').textContent=`${answered} / ${bFinalItems.length} 回答`;
  document.getElementById('bFinalAlgoAnswered').textContent=algo;document.getElementById('bFinalSecAnswered').textContent=sec;
  saveBFinalResume();
}

function askSubmitBFinal(){
  const blank=bFinalAnswers.filter(x=>x===null).length;
  if(confirm(blank?`未回答が${blank}問あります。総合実戦を提出しますか？`:'20問の回答を提出しますか？'))finishBFinal(false);
}


if(!profile.bFinalMistakeStats)profile.bFinalMistakeStats={};
function bFinalMistakeKey(d){return `${d.kind}:${d.sourceId}:${d.format}`;}
function bFinalReviewReasonMeta(reason,d){
  const m={
    'トレースミス':['TRACEで1行ずつ確認','途中状態を紙に書き、変数・配列の更新を1行ずつ追います。'],
    'コード理解':['複合問題で確認','空欄や処理目的を、コード全体の役割から判断する練習へ進みます。'],
    '読み違い':['条件を読み直す','設問が聞いている時点・対象・条件を先に囲ってからコードを読みます。'],
    '知識不足':[d.kind==='security'?'セキュリティ演習で確認':'学習モードで確認','用語や仕組みを短く整理してから、もう一度判断します。'],
    '時間不足':['時間を区切って再挑戦','一つの設問に粘りすぎず、後で戻る判断を練習します。']
  };return m[reason]||[d.kind==='security'?'セキュリティ演習へ':'学習モードへ','まず該当する学習モードで処理を確認します。'];
}
function bFinalAutoDiagnosis(a){
  const wrong=a.details.filter(d=>!d.ok),byFormat={},byDomain={};
  wrong.forEach(d=>{
    byFormat[d.format]=(byFormat[d.format]||0)+1;
    const domain=d.domain||(d.kind==='security'?'情報セキュリティ':'擬似言語');
    byDomain[domain]=(byDomain[domain]||0)+1;
  });
  const top=Object.entries(byFormat).sort((a,b)=>b[1]-a[1])[0];
  const topDomain=Object.entries(byDomain).sort((a,b)=>b[1]-a[1])[0];
  const secWrong=a.details.filter(d=>d.kind==='security'&&!d.ok).length,algoWrong=a.details.filter(d=>d.kind==='algo'&&!d.ok).length;
  const repeat=wrong.filter(d=>(profile.bFinalMistakeStats?.[bFinalMistakeKey(d)]?.misses||0)>=2).length;
  return {topFormat:top?.[0]||'—',topCount:top?.[1]||0,topDomain:topDomain?.[0]||'—',topDomainCount:topDomain?.[1]||0,secWrong,algoWrong,repeat};
}
function renderBFinalDiagnosis(a){
  const root=document.getElementById('bFinalDiagnosis');if(!root)return;const x=bFinalAutoDiagnosis(a);
  root.innerHTML=`<div class="bfinal-diagnosis-title">今回の総合実戦診断</div><div class="bfinal-diagnosis-grid">
    <div class="bfinal-diagnosis-item"><span>崩れた形式</span><b>${escapeHtml(x.topFormat)}</b><small>${x.topCount}問の誤答</small></div>
    <div class="bfinal-diagnosis-item"><span>弱点領域</span><b>${escapeHtml(x.topDomain)}</b><small>${x.topDomainCount}問の誤答</small></div>
    <div class="bfinal-diagnosis-item"><span>繰り返し誤答</span><b>${x.repeat}問</b><small>以前の総合実戦でも同じ型でつまずいた問題</small></div>
  </div>`;
}
function finishBFinalLegacyV376(timeUp=false){
  if(!bFinalItems.length)return;
  stopBFinalTimer();
  clearBFinalResume();
  const used=Math.min(B_FINAL_SECONDS,Math.max(0,Math.round((Date.now()-(bFinalStartedAt||Date.now()))/1000)));
  let correct=0,blank=0,algoCorrect=0,secCorrect=0;
  const details=bFinalItems.map((item,i)=>{
    const ans=bFinalAnswers[i],ok=ans===item.a;if(ok){correct++;if(item.kind==='algo')algoCorrect++;else secCorrect++;}if(ans===null)blank++;
    const key=item.kind==='security'?`sec:${item.sourceId}`:`algo:${item.sourceId}`;
    if(!profile.bFinalStats[key])profile.bFinalStats[key]={seen:0,correct:0,lastSeen:null};
    const st=profile.bFinalStats[key];st.seen++;if(ok)st.correct++;st.lastSeen=localDateISO(0);
    const detail={sourceId:item.sourceId,kind:item.kind,format:bFinalFormatOf(item),domain:item.kind==='security'?(item.concept||'情報セキュリティ'):(item.domain||'擬似言語'),title:item.title,q:item.q,selected:ans===null?null:item.options[ans],correct:item.correctText,ok,explain:item.explain,studyMode:item.studyMode};
    if(!ok){const mk=bFinalMistakeKey(detail);const ms=profile.bFinalMistakeStats[mk]||(profile.bFinalMistakeStats[mk]={misses:0,reasons:{},lastReason:null,last:null});ms.misses=(ms.misses||0)+1;ms.last=localDateISO(0);}
    return detail;
  });
  // Internal legacy practice points are retained only for saved-data compatibility and XP logic.
  // The UI shows raw correct count/rate and does not present this as an IRT or exam score.
  const points=correct*50,rate=Math.round(correct/20*100),earned=correct*10+(points>=600?40:0);
  profile.xp=(profile.xp||0)+earned;
  const attempt={date:localDateISO(0),total:20,correct,blank,points,rate,seconds:used,timeUp,algoCorrect,secCorrect,details};
  profile.bFinalHistory=[attempt,...(profile.bFinalHistory||[])].slice(0,20);lastBFinalAttempt=attempt;saveProfile();

  document.getElementById('bFinalExam')?.classList.remove('show');document.getElementById('bFinalResult')?.classList.add('show');
  renderBFinalResult(attempt,earned);
}
async function finishBFinal(timeUp=false){
  if(!bFinalItems.length||bFinalGradeBusyV376)return false;
  bFinalGradeBusyV376=true;stopBFinalTimer();
  const submitBtn=document.getElementById('bFinalSubmit');if(submitBtn)submitBtn.disabled=true;
  try{
    const ids=bFinalItems.map(item=>item._protectedQuestionId);
    if(ids.some(id=>!id)||new Set(ids).size!==20)throw new Error('v376_b_final_resume_ids_invalid');
    const state=bFinalBridgeV376().state();
    if(state.mode!=='final'||state.questionIds.length!==20||ids.some(id=>!state.questionIds.includes(id))){
      await bFinalBridgeV376().startSession(ids);
    }
    const serverChoices=bFinalItems.map((item,index)=>{
      const selected=bFinalAnswers[index];if(selected===null||selected===undefined)return null;
      const mapped=item._serverMap?.[selected];if(!Number.isInteger(mapped))throw new Error('v376_b_final_choice_map_invalid');return mapped;
    });
    const results=await bFinalBridgeV376().gradeSession(serverChoices);
    if(!Array.isArray(results)||results.length!==20)throw new Error('v376_b_final_grade_count_invalid');
    results.forEach((result,index)=>{
      const item=bFinalItems[index],displayAnswer=item._serverMap.indexOf(result.answerIndex);
      if(displayAnswer<0)throw new Error('v376_b_final_answer_map_invalid');
      item.a=displayAnswer;item.correctText=item.options[displayAnswer];item.explain=result.explanation||'';
    });
    finishBFinalLegacyV376(timeUp);bFinalClearProtectedV376();return true;
  }catch(error){
    bFinalBridgeV376().reportError?.(error);
    if(!timeUp&&bFinalItems.length)startBFinalTimer();
    return false;
  }finally{
    if(submitBtn)submitBtn.disabled=false;bFinalGradeBusyV376=false;
  }
}

const B_FINAL_DOMAIN_REMEDIATION={
  '制御':'nested_loop',
  '一次元配列':'array_reverse',
  '二次元配列':'matrix_find',
  '再帰・関数':'recursion',
  '木構造':'tree_dfs',
  'オブジェクト指向':'object_counter',
  'リスト':'linked_list',
  'スタック・キュー':'stack_ops',
  'ビット列':'bit_mask',
  '探索・整列':'binary_search_b'
};

function bFinalRemediationTarget(mode,source,domain){
  if(mode==='security')return {mode:'security',id:source};
  if(mode==='trace')return {mode:'trace',id:source};
  if(mode==='exam')return {mode:'trace',id:B_FINAL_DOMAIN_REMEDIATION[domain]||'binary_search_b'};
  if(mode==='compound')return {mode:'compound',id:source};
  return {mode:'mock',id:null};
}

function renderBFinalResult(a,earned){
  document.getElementById('bFinalResultPoints').textContent=`${a.rate}%`;
  document.getElementById('bFinalResultRaw').textContent=`${a.correct} / 20 正解`;
  document.getElementById('bFinalResultMessage').textContent=a.rate>=80?`かなり安定しています。時間配分を保ったまま精度を維持しましょう。+${earned} XP`:a.rate>=60?`練習上の目安には届いています。誤答分野を潰して余裕を作りましょう。+${earned} XP`:a.rate>=45?`あと少しです。誤答を「トレース」「読解」「判断」に分けて復習しましょう。+${earned} XP`:`学習モードへ戻り、途中状態を書き出す練習から積み直すのがおすすめです。+${earned} XP`;
  document.getElementById('bFinalStatCorrect').textContent=a.correct;
  document.getElementById('bFinalStatWrong').textContent=20-a.correct-a.blank;
  document.getElementById('bFinalStatBlank').textContent=a.blank;
  document.getElementById('bFinalStatTime').textContent=bMockFormatTime(a.seconds);
  document.getElementById('bFinalAlgoScore').textContent=`${a.algoCorrect} / 16`;
  document.getElementById('bFinalSecScore').textContent=`${a.secCorrect} / 4`;
  renderBFinalDiagnosis(a);

  const formats=[...new Set(a.details.map(d=>d.format))];
  document.getElementById('bFinalFormatBreakdown').innerHTML=formats.map(f=>{
    const rows=a.details.filter(d=>d.format===f),n=rows.filter(d=>d.ok).length,pct=Math.round(n/rows.length*100);
    return `<div class="bfinal-format-row"><div class="bfinal-format-label">${escapeHtml(f)}</div><div class="bfinal-format-bar"><div class="bfinal-format-fill" style="width:${pct}%"></div></div><div class="bfinal-format-score">${n}/${rows.length}</div></div>`;
  }).join('');

  document.getElementById('bFinalReviewList').innerHTML=a.details.map((d,i)=>{
    const mk=bFinalMistakeKey(d),ms=profile.bFinalMistakeStats?.[mk],reason=ms?.lastReason||'';const meta=bFinalReviewReasonMeta(reason,d);
    return `<div class="bfinal-review-item ${d.ok?'correct':'wrong'}"><div class="bfinal-review-top"><b>Q${i+1} ${escapeHtml(d.title)}</b><span>${d.kind==='security'?'🛡️ '+escapeHtml(d.domain||'セキュリティ'):'💻 '+escapeHtml(d.domain||'擬似言語')+' / '+escapeHtml(d.format)} / ${d.ok?'✓ 正解':'✕ 要復習'}</span></div><div class="bfinal-review-q">${escapeHtml(d.q)}</div><div class="bfinal-review-a">あなたの回答：<b>${d.selected===null?'未回答':escapeHtml(d.selected)}</b><br>正解：<b>${escapeHtml(d.correct)}</b></div><div class="bfinal-review-e">${escapeHtml(d.explain)}</div>${d.ok?'':`<div class="bfinal-review-reason"><div class="bfinal-review-reason-title">なぜ崩れましたか？</div><div class="bfinal-review-reason-chips">${['トレースミス','コード理解','読み違い','知識不足','時間不足'].map(r=>`<button class="bfinal-review-reason-chip ${reason===r?'picked':''}" data-bfreason="${r}" data-bfkey="${escapeHtml(mk)}">${r}</button>`).join('')}</div></div><div class="bfinal-review-action" data-bfaction="${escapeHtml(mk)}"><b>${escapeHtml(meta[0])}</b>${escapeHtml(meta[1])}</div><button class="bfinal-review-study smart" data-bfinalstudy="${escapeHtml(d.studyMode)}" data-bfinalsource="${escapeHtml(d.sourceId)}" data-bfinaldomain="${escapeHtml(d.domain||'')}">${escapeHtml(meta[0])} →</button>`}</div>`;
  }).join('');
  document.querySelectorAll('[data-bfreason]').forEach(btn=>btn.onclick=()=>{
    const key=btn.dataset.bfkey,reason=btn.dataset.bfreason,st=profile.bFinalMistakeStats[key];if(!st)return;
    if(st.lastReason&&st.reasons?.[st.lastReason])st.reasons[st.lastReason]=Math.max(0,st.reasons[st.lastReason]-1);
    st.lastReason=reason;st.reasons=st.reasons||{};st.reasons[reason]=(st.reasons[reason]||0)+1;st.last=localDateISO(0);saveProfile();renderBFinalResult(a,0);
  });
  document.querySelectorAll('[data-bfinalstudy]').forEach(btn=>btn.onclick=()=>{
    document.getElementById('bFinalResult')?.classList.remove('show');
    const target=bFinalRemediationTarget(btn.dataset.bfinalstudy,btn.dataset.bfinalsource,btn.dataset.bfinaldomain);
    if(target.mode==='security'){
      setBMode('security');startSecurityScenario(target.id);
    }else if(target.mode==='trace'){
      setBMode('trace');startBExercise(target.id);
    }else if(target.mode==='compound'){
      setBMode('mock');startCompoundChallenge();
    }else{
      setBMode('mock');showBMockMenu();
    }
  });
}

document.getElementById('bFinalStart')?.addEventListener('click',startBFinal);
document.getElementById('bFinalRetry')?.addEventListener('click',startBFinal);
document.getElementById('bFinalBackMenu')?.addEventListener('click',continueSubjectBFlow);
document.getElementById('bFinalSubmit')?.addEventListener('click',askSubmitBFinal);
document.getElementById('bFinalPrev')?.addEventListener('click',()=>{if(bFinalIndex>0){bFinalIndex--;renderBFinalQuestion()}});
document.getElementById('bFinalNext')?.addEventListener('click',()=>{if(bFinalIndex<bFinalItems.length-1){bFinalIndex++;renderBFinalQuestion()}else askSubmitBFinal()});
document.getElementById('bFinalFlag')?.addEventListener('click',()=>{bFinalFlags.has(bFinalIndex)?bFinalFlags.delete(bFinalIndex):bFinalFlags.add(bFinalIndex);renderBFinalQuestion()});
document.getElementById('bFinalExit')?.addEventListener('click',()=>{if(confirm('科目B総合実戦を終了しますか？回答は保存されません。')){clearBFinalResume();showBFinalMenu()}});


// ===== v37: Security ミニ模試 =====
const SECURITY_MOCK_COUNT=8;
const SECURITY_MOCK_SECONDS=20*60;
const SECURITY_MOCK_QUOTAS={'基礎':2,'標準':4,'応用':2};

if(!profile.securityMockHistory) profile.securityMockHistory=[];
if(!profile.securityMockStats) profile.securityMockStats={};

function ensureSecurityMockStats(){
  SECURITY_SCENARIOS.forEach(s=>{
    if(!profile.securityMockStats[s.id]) profile.securityMockStats[s.id]={seen:0,correct:0,lastSeen:null};
  });
}

let secMockItems=[],secMockAnswers=[],secMockFlags=new Set(),secMockIndex=0;
let secMockSeconds=SECURITY_MOCK_SECONDS,secMockTimerId=null,secMockStartedAt=null,lastSecurityMockAttempt=null;

function randomizeSecurityMockItem(){return undefined;}/* FEQUEST_V376_REDACTED_RESIDUAL_QUESTION_FUNCTION */

function securityAppliedStepIndex(s){
  // 実戦では「攻撃名を当てる」だけの最初の設問を避け、
  // 対応・根拠・対策を判断する2問目/3問目を使う。
  const candidates=(s.steps||[]).map((_,i)=>i).filter(i=>i>=1);
  return candidates[Math.floor(Math.random()*candidates.length)] ?? 0;
}

function securityScenarioSeen(s,stats){
  return stats?.[s.id]?.seen||0;
}
function sortSecurityScenarioPool(pool,stats){
  return [...pool].sort((a,b)=>{
    const sa=securityScenarioSeen(a,stats),sb=securityScenarioSeen(b,stats);
    if(sa!==sb)return sa-sb;
    const la=stats?.[a.id]?.lastSeen||'',lb=stats?.[b.id]?.lastSeen||'';
    if(la!==lb)return la.localeCompare(lb);
    return Math.random()-.5;
  });
}

function buildSecurityMock(){
  ensureSecurityMockStats();
  const selected=[];
  const used=new Set();

  // ログ読解を最低2問（標準1・応用1）必ず含める。
  const requiredLogLevels=['標準','応用'];
  requiredLogLevels.forEach(level=>{
    const pool=sortSecurityScenarioPool(
      SECURITY_SCENARIOS.filter(s=>s.level===level&&s.log&&!used.has(s.id)),
      profile.securityMockStats
    );
    const pick=pool[0];
    if(pick){selected.push(pick);used.add(pick.id);}
  });

  // 基礎2・標準4・応用2の配分を保ったまま残りを埋める。
  Object.entries(SECURITY_MOCK_QUOTAS).forEach(([level,n])=>{
    const already=selected.filter(s=>s.level===level).length;
    const need=Math.max(0,n-already);
    const pool=sortSecurityScenarioPool(
      SECURITY_SCENARIOS.filter(s=>s.level===level&&!used.has(s.id)),
      profile.securityMockStats
    );
    pool.slice(0,need).forEach(s=>{selected.push(s);used.add(s.id)});
  });

  return shuffled(selected).map(s=>randomizeSecurityMockItem(s,securityAppliedStepIndex(s)));
}

function securityMockEvidenceHtml(item){
  if(item.log)return `<div class="log-box">${escapeHtml(item.log)}</div>`;
  if(item.risk)return `<div class="risk-matrix">
    <div class="risk-cell"></div><div class="risk-cell">影響 低</div><div class="risk-cell">影響 中</div><div class="risk-cell">影響 高</div>
    <div class="risk-cell">可能性 高</div><div class="risk-cell medium">中</div><div class="risk-cell high">高</div><div class="risk-cell high">R1：高</div>
    <div class="risk-cell">可能性 中</div><div class="risk-cell low">低</div><div class="risk-cell medium">中</div><div class="risk-cell high">高</div>
    <div class="risk-cell">可能性 低</div><div class="risk-cell low">低</div><div class="risk-cell low">低</div><div class="risk-cell medium">中</div>
  </div>`;
  return `<div class="evidence-list">${(item.evidence||[]).map(e=>`<div class="evidence-item"><span class="ev-icon">${e.icon}</span><div>${e.text}</div></div>`).join('')}</div>`;
}

function startSecurityMock(){
  secMockItems=buildSecurityMock();
  secMockAnswers=Array(secMockItems.length).fill(null);
  secMockFlags=new Set();secMockIndex=0;secMockSeconds=SECURITY_MOCK_SECONDS;secMockStartedAt=Date.now();
  document.getElementById('secSelect')?.classList.add('hidden');
  document.getElementById('secMockResult')?.classList.remove('show');
  document.getElementById('secMockExam')?.classList.add('show');
  renderSecurityMockQuestion();startSecurityMockTimer();
}

function stopSecurityMockTimer(){if(secMockTimerId){clearInterval(secMockTimerId);secMockTimerId=null}}
function startSecurityMockTimer(){
  stopSecurityMockTimer();updateSecurityMockTimer();
  secMockTimerId=setInterval(()=>{secMockSeconds--;updateSecurityMockTimer();if(secMockSeconds<=0){stopSecurityMockTimer();finishSecurityMock(true)}},1000);
}
function updateSecurityMockTimer(){
  const t=document.getElementById('secMockTimer');if(!t)return;
  t.textContent=bMockFormatTime(secMockSeconds);
  t.classList.toggle('warn',secMockSeconds<=300&&secMockSeconds>120);
  t.classList.toggle('danger',secMockSeconds<=120);
}

function renderSecurityMockQuestion(){
  const item=secMockItems[secMockIndex];
  if(!item)return;
  document.getElementById('secMockQNum').textContent=`問題 ${secMockIndex+1} / ${secMockItems.length}`;
  document.getElementById('secMockIncidentIcon').textContent=item.incident.icon;
  document.getElementById('secMockIncidentTitle').textContent=item.incident.title;
  document.getElementById('secMockIncidentText').textContent=item.incident.text;
  document.getElementById('secMockEvidence').innerHTML=securityMockEvidenceHtml(item);
  document.getElementById('secMockQuestion').textContent=item.q;
  const ans=secMockAnswers[secMockIndex];
  document.getElementById('secMockOptions').innerHTML=item.options.map((op,i)=>`<button class="secmock-option ${ans===i?'selected':''}" data-smopt="${i}">${String.fromCharCode(65+i)}. ${escapeHtml(op)}</button>`).join('');
  document.querySelectorAll('[data-smopt]').forEach(btn=>btn.onclick=()=>{secMockAnswers[secMockIndex]=Number(btn.dataset.smopt);renderSecurityMockQuestion()});
  document.getElementById('secMockPrev').disabled=secMockIndex===0;
  document.getElementById('secMockNext').textContent=secMockIndex===secMockItems.length-1?'提出へ':'次へ →';
  document.getElementById('secMockFlag').classList.toggle('active',secMockFlags.has(secMockIndex));
  document.getElementById('secMockFlag').textContent=secMockFlags.has(secMockIndex)?'★ 後で見る':'☆ 後で見る';
  renderSecurityMockNav();
}
function renderSecurityMockNav(){
  const root=document.getElementById('secMockNavGrid');
  root.innerHTML=secMockItems.map((_,i)=>`<button class="bmock-nav-q ${secMockAnswers[i]!==null?'answered':''} ${secMockFlags.has(i)?'flagged':''} ${i===secMockIndex?'current':''}" data-smq="${i}">${i+1}</button>`).join('');
  root.querySelectorAll('[data-smq]').forEach(btn=>btn.onclick=()=>{secMockIndex=Number(btn.dataset.smq);renderSecurityMockQuestion()});
  document.getElementById('secMockAnswerCount').textContent=`${secMockAnswers.filter(x=>x!==null).length} / ${secMockItems.length} 回答`;
}
function askSubmitSecurityMock(){
  const blank=secMockAnswers.filter(x=>x===null).length;
  if(confirm(blank?`未回答が${blank}問あります。提出しますか？`:'回答を提出しますか？'))finishSecurityMock(false);
}
function finishSecurityMock(timeUp=false){
  if(!secMockItems.length)return;
  stopSecurityMockTimer();
  const used=Math.min(SECURITY_MOCK_SECONDS,Math.max(0,Math.round((Date.now()-(secMockStartedAt||Date.now()))/1000)));
  let correct=0,blank=0;
  const details=secMockItems.map((item,i)=>{
    const ans=secMockAnswers[i],ok=ans===item.a;
    if(ok)correct++;if(ans===null)blank++;
    const st=profile.securityMockStats[item.scenarioId]||(profile.securityMockStats[item.scenarioId]={seen:0,correct:0,lastSeen:null});
    st.seen=(st.seen||0)+1;if(ok)st.correct=(st.correct||0)+1;st.lastSeen=localDateISO(0);
    return {scenarioId:item.scenarioId,title:item.title,level:item.level,concept:item.concept,q:item.q,selected:ans===null?null:item.options[ans],correct:item.correctText,ok,explain:item.explain};
  });
  const rate=Math.round(correct/secMockItems.length*100),earned=correct*8+(rate>=75?20:0);
  profile.xp=(profile.xp||0)+earned;
  if(profile.skills?.['セキュリティ']!==undefined)profile.skills['セキュリティ']=clamp(profile.skills['セキュリティ']+(rate>=75?2:rate>=50?1:0),0,100);
  const attempt={
    date:localDateISO(0),total:secMockItems.length,correct,blank,rate,seconds:used,timeUp,
    levels:Object.fromEntries(['基礎','標準','応用'].map(level=>{const r=details.filter(d=>d.level===level);return[level,{correct:r.filter(d=>d.ok).length,total:r.length}]})),
    details
  };
  profile.securityMockHistory=[attempt,...(profile.securityMockHistory||[])].slice(0,20);
  lastSecurityMockAttempt=attempt;saveProfile();

  document.getElementById('secMockExam')?.classList.remove('show');
  document.getElementById('secMockResult')?.classList.add('show');
  document.getElementById('secMockResultScore').textContent=`${correct} / ${secMockItems.length}`;
  document.getElementById('secMockResultMessage').textContent=rate>=88?`状況判断がかなり安定しています。+${earned} XP`:rate>=75?`実戦で十分戦える水準に近づいています。+${earned} XP`:rate>=50?`誤答したケースを学習モードで確認しましょう。+${earned} XP`:`まずは誤答ケースの「何を最優先するか」を整理しましょう。+${earned} XP`;
  document.getElementById('secMockCorrect').textContent=correct;
  document.getElementById('secMockWrong').textContent=secMockItems.length-correct-blank;
  document.getElementById('secMockBlank').textContent=blank;
  document.getElementById('secMockTime').textContent=bMockFormatTime(used);
  document.getElementById('secMockBreakdown').innerHTML=['基礎','標準','応用'].map(level=>{const x=attempt.levels[level],pct=x.total?Math.round(x.correct/x.total*100):0;return `<div class="secmock-break-row"><div class="secmock-break-label">${level}</div><div class="secmock-break-bar"><div class="secmock-break-fill" style="width:${pct}%"></div></div><div class="secmock-break-score">${x.correct}/${x.total}</div></div>`}).join('');
  document.getElementById('secMockReviewList').innerHTML=details.map((d,i)=>`<div class="secmock-review-item ${d.ok?'correct':'wrong'}"><div class="secmock-review-top"><b>Q${i+1} ${escapeHtml(d.title)}</b><span>${d.ok?'✓ 正解':'✕ 要復習'}</span></div><div class="secmock-review-q">${escapeHtml(d.q)}</div><div class="secmock-review-a">あなたの回答：<b>${d.selected===null?'未回答':escapeHtml(d.selected)}</b><br>正解：<b>${escapeHtml(d.correct)}</b></div><div class="secmock-review-e">${escapeHtml(d.explain)}</div>${d.ok?'':`<button class="secmock-review-study" data-sstudy="${escapeHtml(d.scenarioId)}">学習モードで確認 →</button>`}</div>`).join('');
  document.querySelectorAll('[data-sstudy]').forEach(btn=>btn.onclick=()=>{document.getElementById('secMockResult')?.classList.remove('show');setBMode('security');startSecurityScenario(btn.dataset.sstudy)});
}

