function renderSecEvidence(s){
  const root=document.getElementById('secEvidence');
  if(s.log){
    root.innerHTML=`<div class="log-box">${escapeHtml(s.log)}</div>`;
    return;
  }
  if(s.risk){
    root.innerHTML=`
      <div class="risk-matrix">
        <div class="risk-cell"></div><div class="risk-cell">影響 低</div><div class="risk-cell">影響 中</div><div class="risk-cell">影響 高</div>
        <div class="risk-cell">可能性 高</div><div class="risk-cell medium">中</div><div class="risk-cell high">高</div><div class="risk-cell high">R1：最優先候補</div>
        <div class="risk-cell">可能性 中</div><div class="risk-cell low">R3</div><div class="risk-cell medium">中</div><div class="risk-cell high">高</div>
        <div class="risk-cell">可能性 低</div><div class="risk-cell low">R2</div><div class="risk-cell low">低</div><div class="risk-cell medium">中</div>
      </div>`;
    return;
  }
  root.innerHTML=`<div class="evidence-list">${
    (s.evidence||[]).map(e=>`<div class="evidence-item"><span class="ev-icon">${e.icon}</span><div>${e.text}</div></div>`).join('')
  }</div>`;
}

async function startSecurityScenario(id,resume=null){
  const meta=SECURITY_SCENARIOS.find(item=>item.id===id);if(!meta)return false;
  if(bSecurityGradeBusyV376)return false;
  if(resume)resume=bSecurityCheckpointV376(resume);
  bSecurityGradeBusyV376=true;
  document.getElementById('secOptions').innerHTML='';
  document.getElementById('secNext').classList.remove('show');
  document.getElementById('secFeedback').className='decision-feedback';
  secStepIndex=resume?.index||0;secAnswered=false;secCorrect=resume?.correct||0;secFirstTryCorrect=resume?.first||0;secAttempts=0;
  document.querySelector('.decision-panel').style.display='';
  document.getElementById('secSelect').classList.add('hidden');
  document.getElementById('bSelect').classList.add('hidden');
  document.getElementById('bLab').classList.remove('show');
  document.getElementById('secLab').classList.add('show');
  document.getElementById('secComplete').classList.remove('show');
  document.getElementById('secLabTitle').textContent=bSecurityGenericTitleV376(meta);
  document.getElementById('secLabMeta').textContent='科目B・問題を読み込み中…';
  try{
    const packet=resume?await bSecurityBridgeV376().resume(id,resume.index+1,resume.answered):await bSecurityBridgeV376().start(id);
    bSecurityApplyScenarioPacketV376(packet);
    renderSecDecision();
    if(resume){
      secAnswered=resume.answered;secAttempts=resume.attempts;bSecurityLastChoiceV376=resume.choiceIndex;
      const buttons=[...document.querySelectorAll('#secOptions .decision-option')];
      buttons.forEach((button,index)=>{button.disabled=secAnswered||(secAttempts===1&&index===bSecurityLastChoiceV376);if(!secAnswered&&button.disabled)button.classList.add('bad');});
      if(secAnswered||secAttempts){
        const feedback=document.getElementById('secFeedback');feedback.className='decision-feedback show';
        feedback.textContent=secAnswered?'この判断は回答済みです。保存した成績から続きを再開します。':'1回目の回答は保存済みです。もう一度考えてみましょう。';
      }
      if(secAnswered){const next=document.getElementById('secNext');next.classList.add('show');next.textContent=secStepIndex===2?'演習結果を見る':'次の判断へ →';}
    }
    return true;
  }catch(error){
    bSecurityBridgeV376().reportError?.(error);
    document.getElementById('secLab').classList.remove('show');
    document.getElementById('secSelect').classList.remove('hidden');
    return false;
  }finally{bSecurityGradeBusyV376=false;}
}

function renderSecDecision(){
  const packet=bSecurityBridgeV376().packet(secStepIndex+1);
  secAnswered=false;secAttempts=0;bSecurityLastChoiceV376=null;
  document.getElementById('secDecisionNum').textContent=secStepIndex+1;
  document.getElementById('secQuestion').textContent=packet.stem;
  const feedback=document.getElementById('secFeedback');feedback.className='decision-feedback';feedback.textContent='';
  const next=document.getElementById('secNext');next.classList.remove('show');next.disabled=false;
  document.getElementById('secCounter').textContent=(secStepIndex+1)+' / '+currentSec.steps.length;
  document.getElementById('secStepProgress').style.width=String((secStepIndex/currentSec.steps.length)*100)+'%';
  const root=document.getElementById('secOptions');root.innerHTML='';
  packet.options.forEach((option,index)=>{
    const button=document.createElement('button');button.className='decision-option';button.textContent=String.fromCharCode(65+index)+'. '+option;
    button.onclick=()=>{void answerSecDecision(index,button)};root.appendChild(button);
  });
}

async function answerSecDecision(index,button){
  if(secAnswered||bSecurityGradeBusyV376)return;
  const packet=bSecurityBridgeV376().packet(secStepIndex+1);
  const firstTry=secAttempts===0,nextAttempt=secAttempts+1;bSecurityGradeBusyV376=true;
  const buttons=[...document.querySelectorAll('#secOptions .decision-option')];buttons.forEach(node=>node.disabled=true);
  const feedback=document.getElementById('secFeedback');
  try{
    const result=await bSecurityBridgeV376().grade(packet.questionId,index,{finalAttempt:nextAttempt>=2});
    secAttempts=nextAttempt;bSecurityLastChoiceV376=index;
    if(!result.finalized){
      bSecurityRecordStudyPositionV376();saveProfile();
      button.classList.add('bad');
      buttons.forEach(node=>{if(node!==button)node.disabled=false});
      feedback.className='decision-feedback show bad';
      feedback.innerHTML='<b>もう一度考えてみましょう</b><div class="sec-retry-hint">💡 '+escapeHtml(packet.hint||'この状況で守るべき情報・被害拡大防止・証拠保全のどれを優先するか整理してください。')+'</div>';
      return;
    }
    secAnswered=true;
    buttons.forEach((node,i)=>{node.disabled=true;if(i===result.answerIndex)node.classList.add('good');else if(i===index&&!result.correct)node.classList.add('bad')});
    if(result.correct){
      secCorrect+=1;
      if(firstTry){secFirstTryCorrect+=1;profile.xp+=8;popToast('判断正解！ +8 XP');}
      else{profile.xp+=4;popToast('再挑戦で正解！ +4 XP');}
    }
    bSecurityRecordStudyPositionV376();saveProfile();
    if(result.postSubmit?.summary)currentSec.summary=result.postSubmit.summary;
    feedback.className='decision-feedback show'+(result.correct?'':' bad');
    feedback.innerHTML='<b>'+(result.correct?'⭕ 適切です':'❌ 正解を確認しましょう')+'</b><div style="margin-top:6px">'+escapeHtml(result.explanation||'')+'</div>';
    document.getElementById('secStepProgress').style.width=String(((secStepIndex+1)/currentSec.steps.length)*100)+'%';
    const next=document.getElementById('secNext');next.disabled=true;next.textContent=secStepIndex===currentSec.steps.length-1?'演習結果を見る':'次の判断へ →';
    if(secStepIndex<currentSec.steps.length-1)await bSecurityBridgeV376().prepareNext();
    next.disabled=false;next.classList.add('show');
  }catch(error){
    bSecurityBridgeV376().reportError?.(error);
    buttons.forEach((node,i)=>node.disabled=secAnswered||(secAttempts===1&&i===bSecurityLastChoiceV376));
    if(secAnswered){const next=document.getElementById('secNext');next.disabled=false;next.classList.add('show');next.textContent='読み込みを再試行 →';}
  }finally{bSecurityGradeBusyV376=false;if(globalThis.studyActiveV373)globalThis.studyActiveV373.last=performance.now();}
}

