function launchFinalFocus(f=finalFocusRecommendation()){
  if(!f)return;
  if(f.kind==='warmup'){showScreen('problems');startQuiz('warmup');return;}
  if(f.kind==='review'){
    const days=examDaysRemaining();
    if(days!=null&&days>=0&&days<=3){showScreen('problems');startQuiz('taperreview');return;}
    const j=actionableReviewJourneys()[0];
    if(j)startJourneyAction(j.id);
    else{showScreen('problems');startQuiz('review');}
    return;
  }
  if(f.kind==='lesson'){startLesson(f.lessonId);return;}
  if(f.kind==='chapter'){showScreen('problems');startQuiz(`corechapter:${f.chapter}`);return;}
  if(f.kind==='topic'){showScreen('problems');startQuiz(`coretopic:${f.topicId}`);return;}
  if(f.kind==='cognitive'){showScreen('problems');startQuiz(`cogcat:${f.cat}:${f.level}`);return;}
  if(f.kind==='subjectB'){
    showScreen('trace');
    const b=f.b||nextBChoice(20);
    if(b.mode==='trace'){setBMode('trace');if(b.id)startBExercise(b.id);}
    else if(b.mode==='security'){setBMode('security');if(b.id)startSecurityScenario(b.id);}
    else if(b.mode==='compound'){setBMode('mock');startCompoundChallenge();}
    else if(b.mode==='securityMock'){setBMode('security');startSecurityMock();}
    return;
  }
  if(f.kind==='aMock'){showScreen('mock');startMock('full');return;}
  if(f.kind==='bFinal'){showScreen('trace');setBMode('final');startBFinal();return;}
}

let currentFinalFocus=null;
function renderFinalMasterPanel(){
  const summary=document.getElementById('finalMasterSummary');
  const gates=document.getElementById('finalMasterGates');
  const note=document.getElementById('finalFocusNote');
  const btn=document.getElementById('finalFocusAction');
  if(!summary||!gates||!note||!btn)return;

  const st=courseMasteryStatus();
  currentFinalFocus=finalFocusRecommendation(st);
  summary.innerHTML=`<b>${st.ready?'✅ 総仕上げ基準 8/8':'🎯 総仕上げ基準 '+st.passed+'/8'}</b><br>習得 ${st.master}/130・定着以上 ${st.stable}/130・章末統合 ${st.chapterPassed}/21${st.recovering?`・習得状態を再確認中 ${st.recovering}`:''}。<br><span class="sub">習得状態は記憶保持に応じて動的に変わります。崩れたテーマは必要な証拠を優先して戻します。FE QUEST独自の学習完了基準で、合格確率や公式の合格基準ではありません。</span>`;
  gates.innerHTML=st.gates.map(g=>`<div class="readiness-part"><span>${g.passed?'✓':'•'} ${escapeHtml(g.name)}</span><b>${escapeHtml(g.value)}</b></div>`).join('');
  note.innerHTML=`<b>${currentFinalFocus.icon} 次に優先：</b> ${escapeHtml(currentFinalFocus.title)}<br>${escapeHtml(currentFinalFocus.desc)}${currentFinalFocus.long?'<br><span class="sub">通常クエストへ上乗せせず、その日のメイン学習としてまとまった時間を確保する実戦メニューです。</span>':''}`;
  btn.textContent=currentFinalFocus.button;
  btn.onclick=()=>launchFinalFocus(currentFinalFocus);
}

function examDaysRemaining(){
  const val=profile.settings?.examDate;if(!val)return null;
  const target=new Date(val+'T12:00:00'),now=new Date();now.setHours(12,0,0,0);
  return Math.ceil((target-now)/86400000);
}
function examStudyPhase(days=examDaysRemaining()){
  if(days==null)return {id:'normal',name:'通常学習',icon:'📘',ratios:{review:.17,lesson:.33,subjectB:.33,boss:.17},allowNew:true,allowLongExam:true};
  if(days<0)return {id:'expired',name:'受験日経過',icon:'📅',ratios:{review:.17,lesson:.33,subjectB:.33,boss:.17},allowNew:true,allowLongExam:true};
  if(days>90)return {id:'foundation',name:'基礎拡張期',icon:'🌱',ratios:{review:.15,lesson:.35,subjectB:.30,boss:.20},allowNew:true,allowLongExam:true};
  if(days>30)return {id:'build',name:'実力形成期',icon:'🧩',ratios:{review:.20,lesson:.25,subjectB:.35,boss:.20},allowNew:true,allowLongExam:true};
  if(days>14)return {id:'finish',name:'仕上げ期',icon:'🎯',ratios:{review:.25,lesson:.15,subjectB:.35,boss:.25},allowNew:true,allowLongExam:true};
  if(days>7)return {id:'finalPractice',name:'直前演習期',icon:'🏁',ratios:{review:.30,lesson:.10,subjectB:.30,boss:.30},allowNew:true,allowLongExam:true};
  if(days>3)return {id:'taper',name:'直前調整期',icon:'🧠',ratios:{review:.35,lesson:.25,subjectB:.20,boss:.20},allowNew:true,allowLongExam:true};
  if(days>1)return {id:'protect',name:'仕上がり保護期',icon:'🛡️',ratios:{review:.40,lesson:.40,subjectB:0,boss:.20},allowNew:false,allowLongExam:false};
  if(days===1)return {id:'eve',name:'前日確認',icon:'🌙',ratios:{review:.67,lesson:0,subjectB:0,boss:.33},allowNew:false,allowLongExam:false};
  return {id:'examDay',name:'受験当日',icon:'☀️',ratios:{review:0,lesson:0,subjectB:0,boss:1},allowNew:false,allowLongExam:false};
}
function taperStudyCap(days=examDaysRemaining()){
  if(days==null||days<0||days>7)return null;
  if(days>=4)return 45;
  if(days>=2)return 30;
  if(days===1)return 15;
  return 10;
}
function roundUp5(n){return Math.ceil((Number(n)||0)/5)*5}
