function weakestSkill(){
  return sortedSkills()[0]?.[0] || 'アルゴリズム';
}
function nextLessonChoice(){
  const weakOrder=sortedSkills().map(x=>x[0]);
  for(const skill of weakOrder){
    const ids=CORE_A_IDS.filter(id=>LESSONS[id].skill===skill);
    const incomplete=ids.find(id=>(profile.lessonProgress?.[id]||0)<100);
    if(incomplete) return {id:incomplete,skill,title:LESSONS[incomplete].title};
  }
  return {id:null,skill:weakOrder[0]||'基礎理論',title:'科目A教材 130テーマ完了',complete:true};
}
function nextBChoice(minutes=20){
  const algoTotal=B_EXERCISES.length;
  const secTotal=SECURITY_SCENARIOS.length;
  const algoDone=B_EXERCISES.filter(x=>(profile.bProgress?.[x.id]||0)>=100).length;
  const secDone=SECURITY_SCENARIOS.filter(x=>(profile.securityBProgress?.[x.id]||0)>=100).length;
  const algoRate=algoDone/Math.max(1,algoTotal);
  const secRate=secDone/Math.max(1,secTotal);

  if(algoDone<algoTotal || secDone<secTotal){
    if(algoRate<=secRate && algoDone<algoTotal){
      const ex=B_EXERCISES.find(x=>(profile.bProgress?.[x.id]||0)<100) || B_EXERCISES[0];
      return {mode:'trace',id:ex?.id,title:ex?.title||'アルゴリズムトレース'};
    }
    const sc=SECURITY_SCENARIOS.find(x=>(profile.securityBProgress?.[x.id]||0)<100) || SECURITY_SCENARIOS[0];
    return {mode:'security',id:sc?.id,title:sc?.title||'セキュリティ演習'};
  }

  // 通常の20分枠に100分の総合実戦を自動割当しない。
  // 基礎演習完了後は20分の複合演習とセキュリティ実戦を交互に回す。
  const compoundRuns=(profile.bCompoundHistory||[]).length;
  const securityRuns=(profile.securityMockHistory||[]).length;
  if(compoundRuns<=securityRuns)return {mode:'compound',id:null,title:'複合問題・3問'};
  return {mode:'securityMock',id:null,title:'セキュリティ ミニ模試'};
}

function nextReadyUnpassedChapter(){
  const rows=CORE_A_CHAPTERS.map(ch=>{
    const topics=CORE_A_CURRICULUM.filter(t=>t.chapter===ch);
    const done=topics.filter(t=>(profile.lessonProgress?.[t.id]||0)>=100).length;
    return {ch,done,total:topics.length,e:chapterIntegrationEvidence(ch)};
  }).filter(x=>x.done===x.total&&!x.e.passed);
  rows.sort((a,b)=>(b.e.bestRate||0)-(a.e.bestRate||0)||a.ch-b.ch);
  return rows[0]||null;
}

function taperFocusRecommendation(days,status=courseMasteryStatus()){
  const ev=categoryCognitiveEvidence(status.weakest[0]);

  // 残り4〜6日は、教材進捗が90%未満なら未学習を1テーマだけ許容。
  // 3日前以降は新規教材を増やさず、既習内容の穴だけを塞ぐ。
  if(days>=4&&status.lessonDone<117){
    const lesson=nextLessonChoice();
    if(lesson?.id)return {kind:'lesson',icon:'📘',title:'未完了教材を1テーマだけ',desc:`教材 ${status.lessonDone}/130。直前に広げすぎず、今日は「${lesson.title}」だけ進めます。`,button:'教材を開く',lessonId:lesson.id};
  }

  if(Number(status.weakest[1])<70){
    return {kind:'cognitive',icon:'🎯',title:`${status.weakest[0]}・${ev.weakest.level}を補強`,desc:`最低分野 ${Math.round(status.weakest[1])}% 。新規範囲ではなく弱い思考を10問で戻します。`,button:`${ev.weakest.level}を10問`,cat:status.weakest[0],level:ev.weakest.level};
  }

  // 3日前以降は独立した科目B枠を置かないため、Bが弱い場合はこの枠で短く確認。
  if(days<=3&&status.bTraining<90){
    const b=nextBChoice(10);
    return {kind:'subjectB',icon:'💻',title:'科目Bを短く確認',desc:`科目B学習 ${status.bTraining}% 。長時間実戦ではなく未完了の基礎演習を1つ確認します。`,button:'科目Bを確認',b};
  }

  const chapter=nextReadyUnpassedChapter();
  if(chapter){
    return {kind:'chapter',icon:'🧩',title:`第${chapter.ch}章を統合確認`,desc:'学習済みの章だけを12問で確認します。未学習範囲を直前に混ぜません。',button:`第${chapter.ch}章を確認`,chapter:chapter.ch};
  }

  const x=nextMasterTopicCandidate();
  if(x&&(profile.lessonProgress?.[x.topic.id]||0)>=100){
    return {kind:'topic',icon:'⭐',title:`${x.topic.title}を維持`,desc:`現在「${x.state.label}」。既習テーマの保持だけを整えます。`,button:'テーマ演習',topicId:x.topic.id};
  }

  return {kind:'cognitive',icon:'✅',title:`${status.weakest[0]}・${ev.weakest.level}を維持`,desc:'新しい範囲へ広げず、既習の最弱思考を短く確認します。',button:`${ev.weakest.level}を10問`,cat:status.weakest[0],level:ev.weakest.level};
}

function chooseTaperReviewQuestions(n=5){
  ensureQuestionProfile();
  const due=dueQuestions();
  const used=new Set();
  const out=[];
  const add=q=>{if(q&&!used.has(q.id)&&out.length<n){out.push(q);used.add(q.id);}};
  due.slice(0,n).forEach(add);
  if(out.length<n){
    trackedQuestionPool()
      .filter(q=>(profile.qStats?.[q.id]?.attempts||0)>0&&!used.has(q.id)&&!questionHasActiveJourney(q.id))
      .sort((a,b)=>reviewUrgency(b)-reviewUrgency(a))
      .slice(0,n-out.length).forEach(add);
  }
  if(out.length<n){
    shuffled(QUESTION_BANK.filter(q=>q.difficulty==='基礎'&&q.cognitiveLevel==='想起'&&!used.has(q.id)))
      .slice(0,n-out.length).forEach(add);
  }
  return out.map(buildReviewItem);
}

function chooseExamWarmupQuestions(n=3){
  ensureQuestionProfile();
  const attempted=QUESTION_BANK.filter(q=>(profile.qStats?.[q.id]?.attempts||0)>0&&!questionHasActiveJourney(q.id));
  const stable=attempted.filter(q=>{
    const r=memoryRetention(profile.qStats[q.id]);
    return r!=null&&r>=80;
  });
  const source=stable.length?stable:attempted;
  const selected=[],usedCats=new Set(),used=new Set();
  const ranked=shuffled(source).sort((a,b)=>{
    const ar=memoryRetention(profile.qStats[a.id])??0,br=memoryRetention(profile.qStats[b.id])??0;
    const cognitiveRank={'想起':0,'適用':1,'判断':2};
    const difficultyRank={'基礎':0,'標準':1,'実戦':2};
    const as=(cognitiveRank[a.cognitiveLevel]??2)*20+(difficultyRank[a.difficulty]??1)*8+Math.abs(ar-90);
    const bs=(cognitiveRank[b.cognitiveLevel]??2)*20+(difficultyRank[b.difficulty]??1)*8+Math.abs(br-90);
    // 当日は「できる問題を軽く解く」ことが目的。想起・基礎を優先し、難しい判断問題は最後にする。
    return as-bs;
  });
  for(const q of ranked){
    if(selected.length>=n)break;
    if(usedCats.has(q.cat))continue;
    selected.push(q);used.add(q.id);usedCats.add(q.cat);
  }
  for(const q of ranked){
    if(selected.length>=n)break;
    if(used.has(q.id))continue;
    selected.push(q);used.add(q.id);
  }
  // 学習履歴が全くない特殊ケースだけ、基礎の想起問題を最小限使う。
  if(selected.length<n){
    shuffled(QUESTION_BANK.filter(q=>q.difficulty==='基礎'&&q.cognitiveLevel==='想起'&&!used.has(q.id)))
      .slice(0,n-selected.length).forEach(q=>selected.push(q));
  }
  return selected.slice(0,n);
}

function buildTaperTodayTasks(days,total){
  const alloc=taperTaskAllocation(total,days);
  const routes=actionableReviewJourneys().length,due=dueQuestions().length;
  const weak=weakestSkill();

  if(days<=0){
    return [{
      type:'warmup',icon:'☀️',bg:'yellow',
      title:'受験前ウォームアップ 3問',
      desc:'既習問題を中心に3問だけ確認。新規教材・長時間模試・追い込みは行いません。',
      minutes:total
    }];
  }

  if(days===1){
    return [
      {
        type:'taperReview',icon:'🧠',bg:'green',
        title:'前日の復習 5問まで',
        desc:routes?`復習ルート ${routes}件から優先`:due?`期限/低保持 ${due}問から最大5問`:`「${weak}」を最大5問だけ確認`,
        minutes:alloc.review
      },
      {
        type:'warmup',icon:'🌙',bg:'yellow',
        title:'軽いウォームアップ 3問',
        desc:'解き慣れた既習問題だけで感覚を確認。新しい範囲は増やしません。',
        minutes:alloc.boss
      }
    ].filter(t=>t.minutes>0);
  }

  const focus=taperFocusRecommendation(days);
  const tasks=[
    {
      type:'taperReview',icon:'🧠',bg:'green',
      title:days<=3?'直前復習 5問':'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`期限/低保持 ${due}問を優先`:`期限を迎えた復習問題はありません。「${weak}」の弱点問題で定着を確認します。`,
      minutes:alloc.review
    },
    {
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:alloc.lesson,focus
    }
  ];

  if(days>=4&&alloc.subjectB>=10){
    const b=nextBChoice(alloc.subjectB);
    tasks.push({
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`科目B：${b.title}`:b.mode==='security'?`科目B：${b.title}`:b.title,
      desc:'長時間の総合実戦ではなく、短い既習演習を1つ',
      minutes:alloc.subjectB,bmode:b.mode,bid:b.id
    });
  }else if(alloc.subjectB>0){
    tasks[1].minutes+=alloc.subjectB;
  }

  tasks.push({
    type:'boss',icon:'👑',bg:'yellow',
    title:'直前総合チェック',
    desc:'判断3問＋適用2問。新規知識ではなく、使えるかだけを5問で確認。',
    minutes:alloc.boss
  });
  return tasks.filter(t=>t.minutes>0);
}

