function randomizeMockQuestion(q){
  const indexed=q.options.map((text,i)=>({text,correct:i===q.a}));
  const mixed=shuffled(indexed);
  return {
    ...q,
    options:mixed.map(x=>x.text),
    a:mixed.findIndex(x=>x.correct),
    sourceId:q.id
  };
}
function recordMockQuestionTime(){
  if(mockQuestionEnteredAt===null || !mockQuestionSeconds.length) return;
  const now=Date.now();
  const delta=Math.max(0,Math.round((now-mockQuestionEnteredAt)/1000));
  mockQuestionSeconds[mockIndex]=(mockQuestionSeconds[mockIndex]||0)+delta;
  mockQuestionEnteredAt=now;
}

const MOCK_CATEGORIES=['基礎理論','コンピュータ','データベース','ネットワーク','セキュリティ','アルゴリズム','マネジメント','ストラテジ'];
const MOCK_DIFFICULTY_LEVELS=['基礎','標準','実戦'];
const MOCK_COGNITIVE_LEVELS=['想起','適用','判断'];
const MOCK_BLUEPRINTS={
  full:{count:60,basic:15,standard:30,practical:15,time:90*60,cognitive:{'想起':15,'適用':29,'判断':16}},
  half:{count:30,basic:8,standard:14,practical:8,time:45*60,cognitive:{'想起':8,'適用':13,'判断':9}}
};
let mockCurrentBlueprint=null;

function mockCategoryQuotas(count){
  const base=Math.floor(count/MOCK_CATEGORIES.length);
  const rem=count%MOCK_CATEGORIES.length;
  const start=(profile.mockHistory?.length||0)%MOCK_CATEGORIES.length;
  const q=Object.fromEntries(MOCK_CATEGORIES.map(c=>[c,base]));
  for(let i=0;i<rem;i++) q[MOCK_CATEGORIES[(start+i)%MOCK_CATEGORIES.length]]++;
  return q;
}
function mockSeen(q){
  return profile.mockQuestionStats?.[q.id]?.seen||0;
}
function mockLastSeen(q){
  return profile.mockQuestionStats?.[q.id]?.lastSeen||'';
}
function mockCandidateSort(a,b){
  const sa=mockSeen(a),sb=mockSeen(b);
  if(sa!==sb)return sa-sb;
  const la=mockLastSeen(a),lb=mockLastSeen(b);
  if(la!==lb)return la.localeCompare(lb);
  return Math.random()-.5;
}
function mockCognitivePreference(difficulty){
  if(difficulty==='基礎')return ['想起','適用','判断'];
  if(difficulty==='標準')return ['適用','判断','想起'];
  return ['判断','適用','想起'];
}
function pickMockPool(pool,n,conceptCounts,conceptCap,cognitiveCounts,cognitiveTarget,difficulty){
  const pref=mockCognitivePreference(difficulty);
  const chosen=[];
  const used=new Set();

  const ranked=(respectCap)=>{
    const candidates=pool.filter(q=>{
      if(used.has(q.id))return false;
      const key=`${q.cat}::${q.concept}`;
      return !respectCap||(conceptCounts[key]||0)<conceptCap;
    });
    return candidates.sort((a,b)=>{
      const ar=(cognitiveCounts[a.cognitiveLevel]||0)<(cognitiveTarget[a.cognitiveLevel]||0);
      const br=(cognitiveCounts[b.cognitiveLevel]||0)<(cognitiveTarget[b.cognitiveLevel]||0);
      if(ar!==br)return ar?-1:1;
      const ap=pref.indexOf(a.cognitiveLevel),bp=pref.indexOf(b.cognitiveLevel);
      if(ap!==bp)return ap-bp;
      return mockCandidateSort(a,b);
    });
  };

  const take=q=>{
    chosen.push(q);used.add(q.id);
    const key=`${q.cat}::${q.concept}`;
    conceptCounts[key]=(conceptCounts[key]||0)+1;
    cognitiveCounts[q.cognitiveLevel]=(cognitiveCounts[q.cognitiveLevel]||0)+1;
  };

  while(chosen.length<n){
    let candidates=ranked(true);
    if(!candidates.length)candidates=ranked(false);
    if(!candidates.length)break;
    take(candidates[0]);
  }
  return chosen;
}

function allocateMockDifficultyByCategory(quotas,bp){
  const result=Object.fromEntries(MOCK_CATEGORIES.map(c=>[c,{'基礎':0,'標準':0,'実戦':0}]));

  const assign=(level,total)=>{
    for(let k=0;k<total;k++){
      const candidates=MOCK_CATEGORIES.filter(cat=>{
        const assigned=Object.values(result[cat]).reduce((a,b)=>a+b,0);
        const available=QUESTION_BANK.filter(q=>q.cat===cat&&q.difficulty===level).length;
        return assigned<quotas[cat] && result[cat][level]<available;
      }).sort((a,b)=>{
        const ra=result[a][level]/Math.max(1,quotas[a]);
        const rb=result[b][level]/Math.max(1,quotas[b]);
        return ra-rb || MOCK_CATEGORIES.indexOf(a)-MOCK_CATEGORIES.indexOf(b);
      });
      if(!candidates.length)break;
      result[candidates[0]][level]++;
    }
  };

  // Reserve practical and basic questions first; fill the remainder with standard.
  assign('実戦',bp.practical);
  assign('基礎',bp.basic);

  MOCK_CATEGORIES.forEach(cat=>{
    const assigned=result[cat]['実戦']+result[cat]['基礎'];
    result[cat]['標準']=Math.max(0,quotas[cat]-assigned);
  });

  // If a category lacks standard questions, replace the shortage with another available tier.
  MOCK_CATEGORIES.forEach(cat=>{
    const stdAvailable=QUESTION_BANK.filter(q=>q.cat===cat&&q.difficulty==='標準').length;
    if(result[cat]['標準']<=stdAvailable)return;
    let shortage=result[cat]['標準']-stdAvailable;
    result[cat]['標準']=stdAvailable;
    for(const level of ['実戦','基礎']){
      const available=QUESTION_BANK.filter(q=>q.cat===cat&&q.difficulty===level).length;
      const room=Math.max(0,available-result[cat][level]);
      const add=Math.min(room,shortage);
      result[cat][level]+=add;shortage-=add;
      if(shortage<=0)break;
    }
  });

  return result;
}

function buildMockQuestions(modeOrCount){
  const mode=typeof modeOrCount==='string'?modeOrCount:(modeOrCount===60?'full':'half');
  const bp=MOCK_BLUEPRINTS[mode]||MOCK_BLUEPRINTS.full;
  const quotas=mockCategoryQuotas(bp.count);
  const difficultyByCat=allocateMockDifficultyByCategory(quotas,bp);
  const conceptCounts={};
  const cognitiveCounts={'想起':0,'適用':0,'判断':0};
  const cognitiveTarget=bp.cognitive||{'想起':0,'適用':bp.count,'判断':0};
  const out=[];

  MOCK_CATEGORIES.forEach(cat=>{
    const cap=mode==='half'?1:2;
    MOCK_DIFFICULTY_LEVELS.forEach(level=>{
      const n=difficultyByCat[cat][level]||0;
      const pool=QUESTION_BANK.filter(q=>q.cat===cat&&q.difficulty===level);
      out.push(...pickMockPool(pool,n,conceptCounts,cap,cognitiveCounts,cognitiveTarget,level));
    });
  });

  const unique=[];
  const seenIds=new Set();
  for(const q of out){
    if(!seenIds.has(q.id)){unique.push(q);seenIds.add(q.id);}
  }
  if(unique.length<bp.count){
    unique.push(...QUESTION_BANK.filter(q=>!seenIds.has(q.id)).sort(mockCandidateSort).slice(0,bp.count-unique.length));
  }

  const picked=shuffled(unique.slice(0,bp.count));
  const counts={
    categories:Object.fromEntries(MOCK_CATEGORIES.map(c=>[c,picked.filter(q=>q.cat===c).length])),
    difficulty:Object.fromEntries(MOCK_DIFFICULTY_LEVELS.map(level=>[level,picked.filter(q=>q.difficulty===level).length])),
    cognitive:Object.fromEntries(MOCK_COGNITIVE_LEVELS.map(level=>[level,picked.filter(q=>q.cognitiveLevel===level).length])),
    unseen:picked.filter(q=>mockSeen(q)===0).length
  };
  mockCurrentBlueprint={mode,count:bp.count,quotas,difficultyByCat,counts};
  return picked.map(randomizeMockQuestion);
}

function startMock(mode){
  mockMode=mode;
  mockLastMode=mode;
  const bp=MOCK_BLUEPRINTS[mode]||MOCK_BLUEPRINTS.full;
  const count=bp.count;
  mockInitialSeconds=bp.time;
  mockSeconds=mockInitialSeconds;
  mockItems=buildMockQuestions(mode);
  if(mockItems.length<count){
    popToast(`問題数が${mockItems.length}問しかないため、この数で開始します`);
  }
  mockAnswers=Array(mockItems.length).fill(null);
  mockFlags=Array(mockItems.length).fill(false);
  mockQuestionSeconds=Array(mockItems.length).fill(0);
  mockIndex=0;
  mockStartedAt=Date.now();
  mockQuestionEnteredAt=Date.now();

  document.getElementById('mockMenu').classList.add('hidden');
  document.getElementById('mockExam').classList.add('show');
  document.getElementById('mockResult').classList.remove('show');
  document.getElementById('mockExamTitle').textContent=mode==='full'?'フル模試・科目A':'ハーフ模試・科目A';

  renderMockNavigator();
  renderMockQuestion();
  updateMockTimer();
  if(mockTimerHandle) clearInterval(mockTimerHandle);
  mockTimerHandle=setInterval(()=>{
    mockSeconds=Math.max(0,mockSeconds-1);
    updateMockTimer();
    if(mockSeconds<=0){
      clearInterval(mockTimerHandle);
      mockTimerHandle=null;
      finishMock(true);
    }
  },1000);
}

document.querySelectorAll('[data-mock-mode]').forEach(b=>{
  b.addEventListener('click',()=>startMock(b.dataset.mockMode));
});

function updateMockTimer(){
  const m=Math.floor(mockSeconds/60);
  const s=mockSeconds%60;
  const e=document.getElementById('mockTimer');
  if(!e) return;
  e.textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
  e.classList.toggle('warn',mockSeconds<=15*60 && mockSeconds>5*60);
  e.classList.toggle('danger',mockSeconds<=5*60);
}

function renderMockNavigator(){
  const root=document.getElementById('mockNavGrid');
  if(!root) return;
  root.innerHTML='';
  mockItems.forEach((q,i)=>{
    const b=document.createElement('button');
    b.className='mock-nav-q';
    b.textContent=i+1;
    b.onclick=()=>{recordMockQuestionTime();mockIndex=i;mockQuestionEnteredAt=Date.now();renderMockQuestion();};
    root.appendChild(b);
  });
  updateMockNavigator();
}
function updateMockNavigator(){
  document.querySelectorAll('.mock-nav-q').forEach((b,i)=>{
    b.classList.toggle('answered',mockAnswers[i]!==null);
    b.classList.toggle('flagged',!!mockFlags[i]);
    b.classList.toggle('current',i===mockIndex);
  });
}

function renderMockQuestion(){
  const q=mockItems[mockIndex];
  if(!q) return;
  document.getElementById('mockQNum').textContent=`問${mockIndex+1}`;
  document.getElementById('mockQCat').textContent='科目A';
  document.getElementById('mockQuestion').textContent=q.q;
  document.getElementById('mockExamProgressText').textContent=`問${mockIndex+1} / ${mockItems.length}`;
  document.getElementById('mockPrev').disabled=mockIndex===0;
  document.getElementById('mockNext').textContent=mockIndex===mockItems.length-1?'先頭へ':'次へ →';

  const flag=document.getElementById('mockFlag');
  flag.classList.toggle('active',mockFlags[mockIndex]);
  flag.textContent=mockFlags[mockIndex]?'★ 見直し対象':'☆ あとで見直す';

  const root=document.getElementById('mockOptions');
  root.innerHTML='';
  q.options.forEach((o,i)=>{
    const b=document.createElement('button');
    b.className='mock-q-option'+(mockAnswers[mockIndex]===i?' selected':'');
    b.textContent=`${String.fromCharCode(65+i)}. ${o}`;
    b.onclick=()=>{
      mockAnswers[mockIndex]=i;
      renderMockQuestion();
    };
    root.appendChild(b);
  });
  updateMockNavigator();
}

document.getElementById('mockPrev')?.addEventListener('click',()=>{
  if(mockIndex>0){
    recordMockQuestionTime();
    mockIndex--;
    mockQuestionEnteredAt=Date.now();
    renderMockQuestion();
  }
});
document.getElementById('mockNext')?.addEventListener('click',()=>{
  recordMockQuestionTime();
  mockIndex=mockIndex<mockItems.length-1?mockIndex+1:0;
  mockQuestionEnteredAt=Date.now();
  renderMockQuestion();
});
document.getElementById('mockFlag')?.addEventListener('click',()=>{
  mockFlags[mockIndex]=!mockFlags[mockIndex];
  renderMockQuestion();
});

document.getElementById('mockFinish')?.addEventListener('click',()=>{
  const blank=mockAnswers.filter(x=>x===null).length;
  const msg=blank?`未回答が${blank}問あります。終了して採点しますか？`:'終了して採点しますか？';
  if(confirm(msg)) finishMock(false);
});

function formatElapsed(sec){
  const m=Math.floor(sec/60);
  const s=sec%60;
  return `${m}分${String(s).padStart(2,'0')}秒`;
}


function mockTargetSeconds(){return mockItems.length?Math.round(mockInitialSeconds/mockItems.length):90;}
function mockAttemptDiagnostics(details,byCat){
  const target=mockTargetSeconds();
  const wrongRows=details.filter(d=>d.answerIndex===null||d.answerIndex!==d.correctIndex);
  const slowRows=details.filter(d=>(d.seconds||0)>target*1.35);
  const repeatRows=wrongRows.filter(d=>(profile.mockMistakeStats?.[d.id]?.misses||0)>=1);
  const weakest=Object.entries(byCat||{}).filter(([,v])=>v.total).sort((a,b)=>(a[1].correct/a[1].total)-(b[1].correct/b[1].total))[0];
  return {target,wrong:wrongRows.length,slow:slowRows.length,repeat:repeatRows.length,weakest:weakest?{cat:weakest[0],pct:Math.round(weakest[1].correct/weakest[1].total*100)}:null};
}
function renderMockDiagnosis(attempt,byCat){
  const root=document.getElementById('mockDiagnosis');if(!root)return;
  const x=mockAttemptDiagnostics(attempt?.details||[],byCat||{});
  root.innerHTML=`<div class="mock-diagnosis-title">今回の模試診断</div><div class="mock-diagnosis-grid">
    <div class="mock-diagnosis-item"><span>最優先分野</span><b>${x.weakest?escapeHtml(x.weakest.cat):'—'}</b><small>${x.weakest?`正答率 ${x.weakest.pct}%`:'十分なデータがありません'}</small></div>
    <div class="mock-diagnosis-item"><span>時間を使った問題</span><b>${x.slow}問</b><small>目安 ${x.target}秒/問 の1.35倍を超えた問題</small></div>
    <div class="mock-diagnosis-item"><span>繰り返し誤答</span><b>${x.repeat}問</b><small>過去にも模試レビューで誤答した論点</small></div>
  </div>`;
}
function reasonPrescription(reason,q){
  const map={
    '知識不足':{kind:'knowledge',text:'まず短い教材で定義と仕組みを整理してから、同じ分野の問題へ戻ります。'},
    '計算ミス':{kind:'calc',text:'途中式・単位・変換過程を省略しない計算ドリルで確認します。'},
    '読み違い':{kind:'read',text:'条件語を拾う練習をして、「適切／不適切」「以上／未満」の読み落としを減らします。'},
    '2択で迷った':{kind:'contrast',text:'似た選択肢を2つに絞り、違いを言葉にしてから選ぶ比較ドリルへ進みます。'},
    '時間不足':{kind:'speed',text:'1問90秒を目安に判断するスプリントで、時間配分を整えます。'}
  };
  const x=map[reason]||{kind:'repeat',text:'復習ルートに沿って、教材・類題・後日復習まで進めます。'};
  const lesson=lessonForQuestion(q);
  return {...x,lesson};
}
function renderReviewPrescription(){
  const item=reviewItems[reviewIndex];if(!item)return;
  const stat=getMockMistakeStat(item.q.id),reason=stat.lastReason;
  const p=reasonPrescription(reason,item.q),text=document.getElementById('reviewPrescriptionText'),main=document.getElementById('reviewPrescriptionMain'),journey=document.getElementById('reviewJourneyDirect');
  if(text)text.textContent=reason?`${reason}：${p.text}`:'原因を選ぶと、そのつまずき方に合った復習方法を提案します。';
  if(main){main.dataset.reason=reason||'';main.dataset.qid=item.q.id;main.textContent=reason==='知識不足'&&p.lesson?'教材で理解し直す →':reason?`${prescriptionMeta({kind:p.kind,cat:item.q.cat}).title} →`:'復習を開始 →';main.disabled=!reason;}
  const j=journeyFor(item.q.id);if(journey){journey.dataset.qid=item.q.id;journey.disabled=!j;journey.textContent=j?`${journeyStageLabel(j.stage)}から復習ルートを続ける`:'復習ルートを見る';}
}
function startReviewPrescription(qid,reason){
  const q=originalQuestionById(qid);if(!q)return;
  const p=reasonPrescription(reason,q);
  if(reason==='知識不足'&&p.lesson){activeReviewJourneyId=qid;startLesson(p.lesson);return;}
  showScreen('problems');startQuiz(`rx:${p.kind}:${q.cat}`);
}
function currentReviewDominantReason(){
  const totals=aggregateReasons();return Object.entries(totals).sort((a,b)=>b[1]-a[1])[0]?.[0]||null;
}
function finishMock(timeup=false){
  recordMockQuestionTime();
  if(mockTimerHandle){clearInterval(mockTimerHandle);mockTimerHandle=null;}
  const used=Math.min(mockInitialSeconds,Math.max(0,mockInitialSeconds-mockSeconds));
  let correct=0,blank=0;
  const byCat={};
  const wrongs=[];

  mockItems.forEach((q,i)=>{
    const ans=mockAnswers[i];
    const ok=ans===q.a;
    const sourceId=q.sourceId||q.id;
    const ms=profile.mockQuestionStats[sourceId]||(profile.mockQuestionStats[sourceId]={seen:0,correct:0,lastSeen:null});
    ms.seen=(ms.seen||0)+1;
    if(ok)ms.correct=(ms.correct||0)+1;
    ms.lastSeen=localDateISO(0);
    if(ans===null) blank++;
    if(ok) correct++;
    if(!byCat[q.cat]) byCat[q.cat]={correct:0,total:0};
    byCat[q.cat].total++;
    if(ok) byCat[q.cat].correct++;
    ensureQuestionProfile();
    const st=profile.qStats[q.sourceId||q.id];
    const sec=mockQuestionSeconds[i]||0;
    if(!ok){
      wrongs.push({q,ans});
      if(st){
        st.attempts=(st.attempts||0)+1;
        st.last=localDateISO(0);
        st.streak=0;
        if(ans===null && timeup) st.lastReason='時間不足';
        adaptiveMemoryUpdate(st,'wrong',sec,st.lastReason,false);
      }
      registerReviewJourney(q,'mock');
      applyQuestionSkillDelta(q,-1);
    }else{
      if(st){
        st.attempts=(st.attempts||0)+1;
        st.correct=(st.correct||0)+1;
        st.last=localDateISO(0);
        st.streak=(st.streak||0)+1;
        adaptiveMemoryUpdate(st,'correct',sec,null,false);
      }
      applyQuestionSkillDelta(q,0.35);
    }
  });

  const total=mockItems.length;
  const rate=total?Math.round(correct/total*100):0;
  const wrong=total-correct-blank;

  const attemptDetails=mockItems.map((q,i)=>({
    id:q.sourceId||q.id,
    shownOptions:[...q.options],
    correctIndex:q.a,
    answerIndex:mockAnswers[i],
    flagged:!!mockFlags[i],
    seconds:mockQuestionSeconds[i]||0
  }));
  lastMockAttempt={
    date:localDateISO(0),mode:mockMode,total,correct,blank,rate,seconds:used,
    blueprint:mockCurrentBlueprint?structuredClone(mockCurrentBlueprint):null,
    byCat:structuredClone(byCat),details:attemptDetails
  };
  profile.mockHistory.unshift(lastMockAttempt);
  profile.mockHistory=profile.mockHistory.slice(0,10);
  profile.xp += Math.round(correct*2);
  saveProfile();

  document.getElementById('mockExam').classList.remove('show');
  document.getElementById('mockResult').classList.add('show');

  document.getElementById('mockResultScore').textContent=`${rate}%`;
  document.getElementById('mockStatCorrect').textContent=correct;
  document.getElementById('mockStatWrong').textContent=wrong;
  document.getElementById('mockStatBlank').textContent=blank;
  document.getElementById('mockStatTime').textContent=`${Math.floor(used/60)}m`;

  let message='弱点を見つけられたことが収穫です。';
  let icon='📚';
  if(rate>=85){message='かなり安定しています。見直し問題を中心に仕上げましょう。';icon='🏆';}
  else if(rate>=70){message='良い位置です。誤答分野を復習するとさらに安定します。';icon='🎯';}
  else if(rate>=55){message='基礎はつながっています。弱点の再学習を優先しましょう。';icon='📈';}
  if(timeup) message='時間終了です。未回答を含めて、時間配分も復習材料にしましょう。';
  document.getElementById('mockResultIcon').textContent=icon;
  document.getElementById('mockResultMessage').textContent=message;
  renderMockDiagnosis(lastMockAttempt,byCat);

  const breakdown=document.getElementById('mockBreakdown');
  breakdown.innerHTML='';
  Object.entries(byCat).sort((a,b)=>(a[1].correct/a[1].total)-(b[1].correct/b[1].total)).forEach(([cat,v])=>{
    const pct=Math.round(v.correct/v.total*100);
    const d=document.createElement('div');
    d.className='mock-break-row';
    d.innerHTML=`<div class="mock-break-name">${cat}</div><div class="progress"><div style="width:${pct}%"></div></div><div class="mock-break-pct">${pct}%</div>`;
    breakdown.appendChild(d);
  });

  const review=document.getElementById('mockReviewList');
  review.innerHTML='';
  wrongs.slice(0,8).forEach(x=>{
    const d=document.createElement('div');
    d.className='mock-review-item';
    const selected=x.ans===null?'未回答':x.q.options[x.ans];
    const stat=profile.mockMistakeStats?.[x.q.sourceId||x.q.id];
    const j=journeyFor(x.q.sourceId||x.q.id);
    const reason=stat?.lastReason||'原因未記録';
    d.innerHTML=`<b>${x.q.cat}・${x.q.concept}</b><div class="sub">${escapeHtml(x.q.q)}<br>あなた：${escapeHtml(selected)} ／ 正解：${escapeHtml(x.q.options[x.q.a])}</div><div class="sub">原因：${escapeHtml(reason)}${j?` ／ 復習：${journeyStageLabel(j.stage)}`:''}</div>`;
    review.appendChild(d);
  });
  if(!wrongs.length) review.innerHTML='<div class="sub">全問正解です 🎉</div>';

  const reviewBtn=document.getElementById('mockStartReview');
  if(reviewBtn){
    const hasReview=reviewCandidates(lastMockAttempt).length>0;
    reviewBtn.style.display=hasReview?'':'none';
    reviewBtn.classList.toggle('primary-action',hasReview);
    document.getElementById('mockBackMenu')?.classList.toggle('primary-action',!hasReview);
  }
  renderMockHistory();
  renderDailyPlan();
  renderReadiness();
}

function showMockMenu(){
  if(mockTimerHandle){clearInterval(mockTimerHandle);mockTimerHandle=null;}
  document.getElementById('mockMenu').classList.remove('hidden');
  document.getElementById('mockExam').classList.remove('show');
  document.getElementById('mockResult').classList.remove('show');
  document.getElementById('mockReviewMode')?.classList.remove('show');
  renderMockHistory();
}
document.getElementById('mockBackMenu')?.addEventListener('click',()=>{showMockMenu();showScreen('problems');});
document.getElementById('mockRetry')?.addEventListener('click',()=>startMock(mockLastMode));

function renderMockHistory(){
  const root=document.getElementById('mockHistoryList');
  if(!root) return;
  const hist=(profile.mockHistory||[]).slice(0,6);
  if(!hist.length){
    root.innerHTML='<div class="sub">まだ模試履歴がありません。</div>';
    return;
  }
  root.innerHTML='';
  hist.forEach(h=>{
    const d=document.createElement('div');
    d.className='mock-history-row';
    const bp=h.blueprint?.counts?.difficulty;
    const cog=h.blueprint?.counts?.cognitive;
    const bpText=bp?`<div class="mock-history-blueprint">基礎 ${bp['基礎']||0} / 標準 ${bp['標準']||0} / 実戦 ${bp['実戦']||0}</div>`:'';
    const cogText=cog?`<div class="mock-history-blueprint">想起 ${cog['想起']||0} / 適用 ${cog['適用']||0} / 判断 ${cog['判断']||0}</div>`:'';
    d.innerHTML=`<div><div class="mock-history-title">${h.mode==='full'?'フル模試':'ハーフ模試'}・${h.correct}/${h.total}問</div><div class="mock-history-sub">${h.date}</div>${bpText}${cogText}${h.details?'<button class="mock-history-review">レビュー</button>':''}</div>
      <div class="mock-history-time">${formatElapsed(h.seconds||0)}</div><div class="mock-history-score">${h.rate}%</div>`;
    d.querySelector('.mock-history-review')?.addEventListener('click',()=>startMockReview(h));
    root.appendChild(d);
  });
}
renderMockHistory();


// ----- v14 mock review -----
if(!profile.mockMistakeStats) profile.mockMistakeStats={};

function originalQuestionById(id){
  return questionById(id);
}
function reviewCandidates(attempt){
  if(!attempt?.details) return [];
  return attempt.details.map((d,i)=>{
    const q=originalQuestionById(d.id);
    if(!q) return null;
    const wrong=d.answerIndex===null || d.answerIndex!==d.correctIndex;
    if(!wrong && !d.flagged) return null;
    return {...d,q,wrong,position:i};
  }).filter(Boolean);
}
function startMockReview(attempt=lastMockAttempt){
  if(!attempt?.details){
    popToast('この模試には詳細レビュー情報がありません');
    return;
  }
  lastMockAttempt=attempt;
  reviewItems=reviewCandidates(attempt);
  if(!reviewItems.length){
    popToast('復習対象はありません 🎉');
    return;
  }
  reviewIndex=0;
  document.getElementById('mockMenu').classList.add('hidden');
  document.getElementById('mockExam').classList.remove('show');
  document.getElementById('mockResult').classList.remove('show');
  document.getElementById('mockReviewMode').classList.add('show');
  document.getElementById('reviewCard').style.display='';
  document.getElementById('reviewSummary').classList.remove('show');
  renderMockReviewItem();
}
document.getElementById('mockStartReview')?.addEventListener('click',()=>startMockReview(lastMockAttempt));

function getMockMistakeStat(id){
  if(!profile.mockMistakeStats[id]) profile.mockMistakeStats[id]={misses:0,reasons:{},last:null};
  return profile.mockMistakeStats[id];
}
function renderMockReviewItem(){
  const item=reviewItems[reviewIndex];
  if(!item) return;
  const q=item.q;
  const stat=getMockMistakeStat(q.id);

  document.getElementById('reviewProgressText').textContent=`${reviewIndex+1} / ${reviewItems.length}`;
  document.getElementById('reviewQuestion').textContent=q.q;

  const badges=[];
  badges.push(`<span class="review-badge">${q.cat}・${q.concept}</span>`);
  if(item.wrong) badges.push('<span class="review-badge wrong">誤答</span>');
  if(item.flagged) badges.push('<span class="review-badge flag">★ 見直し</span>');
  if((stat.misses||0)>=2) badges.push(`<span class="review-badge repeat">繰り返し誤答 ${stat.misses}回</span>`);
  document.getElementById('reviewBadges').innerHTML=badges.join('');

  const user=item.answerIndex===null?'未回答':item.shownOptions[item.answerIndex];
  const correct=item.shownOptions[item.correctIndex];
  document.getElementById('reviewUserAnswerValue').textContent=user;
  document.getElementById('reviewCorrectAnswerValue').textContent=correct;
  document.getElementById('reviewUserAnswer').className='review-answer user'+(item.wrong?' wrong':'');

  document.getElementById('reviewExplanation').textContent=q.exp;
  document.getElementById('reviewHint').textContent='覚え方：'+q.hint;
  const target=Math.round((lastMockAttempt?.mode==='half'?45*60:90*60)/(lastMockAttempt?.total||60));
  document.getElementById('reviewTime').textContent=`この問題：約${item.seconds||0}秒 ／ 目安：約${target}秒`;

  document.querySelectorAll('.review-reason-chip').forEach(c=>{
    c.classList.toggle('picked',stat.lastReason===c.dataset.mreason);
  });

  document.getElementById('reviewPrev').disabled=reviewIndex===0;
  document.getElementById('reviewNext').textContent=reviewIndex===reviewItems.length-1?'レビュー完了':'次へ →';
  document.getElementById('similarBox').classList.remove('show');
  currentSimilar=null;
  renderReviewPrescription();
}

document.querySelectorAll('.review-reason-chip').forEach(chip=>{
  chip.addEventListener('click',()=>{
    const item=reviewItems[reviewIndex];
    if(!item) return;
    const stat=getMockMistakeStat(item.q.id);

    // Undo prior reason count if the reason is being changed.
    if(stat.lastReason && stat.reasons[stat.lastReason]){
      stat.reasons[stat.lastReason]=Math.max(0,stat.reasons[stat.lastReason]-1);
    }
    const reason=chip.dataset.mreason;
    stat.lastReason=reason;
    stat.reasons[reason]=(stat.reasons[reason]||0)+1;
    stat.last=localDateISO(0);
    const qst=profile.qStats?.[item.q.id];if(qst)qst.lastReason=reason;

    document.querySelectorAll('.review-reason-chip').forEach(c=>c.classList.remove('picked'));
    chip.classList.add('picked');
    saveProfile();
    renderReviewPrescription();
  });
});

function registerReviewedMiss(item){
  if(!item?.wrong) return;
  const stat=getMockMistakeStat(item.q.id);
  if(!stat._countedAttemptKey) stat._countedAttemptKey={};
  const key=`${lastMockAttempt?.date||''}-${item.position}-${lastMockAttempt?.seconds||0}`;
  if(!stat._countedAttemptKey[key]){
    stat.misses=(stat.misses||0)+1;
    stat._countedAttemptKey[key]=true;
    stat.last=localDateISO(0);
    // keep small to avoid unlimited localStorage growth
    const keys=Object.keys(stat._countedAttemptKey);
    if(keys.length>12) delete stat._countedAttemptKey[keys[0]];
    saveProfile();
  }
}
function moveReview(delta){
  const item=reviewItems[reviewIndex];
  registerReviewedMiss(item);
  const next=reviewIndex+delta;
  if(next<0 || next>=reviewItems.length) return;
  reviewIndex=next;
  renderMockReviewItem();
}
document.getElementById('reviewPrev')?.addEventListener('click',()=>moveReview(-1));
document.getElementById('reviewNext')?.addEventListener('click',()=>{
  registerReviewedMiss(reviewItems[reviewIndex]);
  if(reviewIndex<reviewItems.length-1){
    reviewIndex++;
    renderMockReviewItem();
  }else{
    finishMockReview();
  }
});

function pickSimilarQuestion(base){
  const lessonId=lessonForQuestion(base);
  const lesson=lessonId?QUESTION_BANK.filter(q=>q.id!==base.id && lessonForQuestion(q)===lessonId):[];
  const concept=QUESTION_BANK.filter(q=>q.id!==base.id && q.concept===base.concept);
  const category=QUESTION_BANK.filter(q=>q.id!==base.id && q.cat===base.cat);
  const pool=lesson.length?lesson:concept.length?concept:category;
  return pool.length?randomizeMockQuestion(shuffled(pool)[0]):null;
}
document.getElementById('reviewSimilar')?.addEventListener('click',()=>{
  const item=reviewItems[reviewIndex];
  if(!item) return;
  currentSimilar=pickSimilarQuestion(item.q);
  const box=document.getElementById('similarBox');
  if(!currentSimilar){
    box.classList.add('show');
    document.getElementById('similarQuestion').textContent='現在、この分野の別問題はありません。';
    document.getElementById('similarOptions').innerHTML='';
    document.getElementById('similarFeedback').textContent='';
    return;
  }
  box.classList.add('show');box.dataset.tried='0';
  document.getElementById('similarQuestion').textContent=currentSimilar.q;
  document.getElementById('similarFeedback').textContent='';
  const root=document.getElementById('similarOptions');
  root.innerHTML='';
  currentSimilar.options.forEach((o,i)=>{
    const b=document.createElement('button');
    b.className='similar-option';
    b.textContent=`${String.fromCharCode(65+i)}. ${o}`;
    b.onclick=()=>{
      const box=document.getElementById('similarBox');
      const tried=box.dataset.tried==='1';
      if(i===currentSimilar.a){
        root.querySelectorAll('button').forEach(x=>x.disabled=true);
        b.classList.add('good');
        document.getElementById('similarFeedback').textContent='⭕ 正解！ '+currentSimilar.exp;
        const base=reviewItems[reviewIndex]?.q,j=base?journeyFor(base.id):null;
        if(base&&j?.stage==='verify')markJourneyAnswer(base.id,!tried);
        profile.xp+=tried?2:5;saveProfile();
      }else if(!tried){
        b.disabled=true;b.classList.add('bad');box.dataset.tried='1';
        document.getElementById('similarFeedback').textContent='まだ答えは表示しません。ヒント：'+(currentSimilar.hint||'問題文の条件と選択肢の違いをもう一度比べてください。');
      }else{
        root.querySelectorAll('button').forEach(x=>x.disabled=true);b.classList.add('bad');root.children[currentSimilar.a]?.classList.add('good');
        document.getElementById('similarFeedback').textContent='正解は '+currentSimilar.options[currentSimilar.a]+'。 '+currentSimilar.exp;
        const base=reviewItems[reviewIndex]?.q;if(base)markJourneyAnswer(base.id,false);
      }
    };
    root.appendChild(b);
  });
});


document.getElementById('reviewPrescriptionMain')?.addEventListener('click',e=>{const qid=e.currentTarget.dataset.qid,reason=e.currentTarget.dataset.reason;if(qid&&reason)startReviewPrescription(qid,reason);});
document.getElementById('reviewJourneyDirect')?.addEventListener('click',e=>{const qid=e.currentTarget.dataset.qid;if(qid)startJourneyAction(qid);});

function aggregateReasons(){
  const totals={};
  reviewItems.forEach(item=>{
    const st=profile.mockMistakeStats?.[item.q.id];
    if(st?.lastReason) totals[st.lastReason]=(totals[st.lastReason]||0)+1;
  });
  return totals;
}
function finishMockReview(){
  document.getElementById('reviewCard').style.display='none';
  document.getElementById('reviewSummary').classList.add('show');

  const totals=aggregateReasons();
  const reasons=['知識不足','計算ミス','読み違い','2択で迷った','時間不足'];
  const root=document.getElementById('reasonSummary');
  root.innerHTML=reasons.map(r=>`<div class="reason-summary-card"><span class="sub">${r}</span><b>${totals[r]||0}問</b></div>`).join('');

  const catCounts={};
  reviewItems.filter(x=>x.wrong).forEach(x=>catCounts[x.q.cat]=(catCounts[x.q.cat]||0)+1);
  const priority=Object.entries(catCounts).sort((a,b)=>b[1]-a[1]).slice(0,3);
  const dominant=currentReviewDominantReason();
  document.getElementById('reviewPriority').innerHTML=priority.length
    ? `<b>次に優先する分野</b><br>${priority.map(([c,n])=>`${c}（${n}問）`).join(' → ')}<br><span class="sub">主な原因：${escapeHtml(dominant||'未記録')}。誤答は復習ルートにも登録済みです。</span>`
    : '<b>誤答はありませんでした。</b>';
  const jbtn=document.getElementById('reviewSummaryJourney'),rxbtn=document.getElementById('reviewSummaryRx');
  if(jbtn)jbtn.style.display=activeReviewJourneys().length?'':'none';
  if(rxbtn){rxbtn.style.display=dominant?'':'none';rxbtn.dataset.reason=dominant||'';rxbtn.dataset.cat=priority[0]?.[0]||weakestSkill();}

  profile.xp+=10;
  saveProfile();
}
function exitMockReview(){
  document.getElementById('mockReviewMode').classList.remove('show');
  document.getElementById('reviewCard').style.display='';
  document.getElementById('reviewSummary').classList.remove('show');
  document.getElementById('mockResult').classList.add('show');
}
document.getElementById('reviewExit')?.addEventListener('click',exitMockReview);
document.getElementById('reviewSummaryBack')?.addEventListener('click',exitMockReview);
document.getElementById('reviewSummaryJourney')?.addEventListener('click',()=>{const j=activeReviewJourneys()[0];if(j)startJourneyAction(j.id);});
document.getElementById('reviewSummaryRx')?.addEventListener('click',e=>{const reason=e.currentTarget.dataset.reason,cat=e.currentTarget.dataset.cat;const fake={id:'',cat,concept:''};const p=reasonPrescription(reason,fake);showScreen('problems');startQuiz(`rx:${p.kind}:${cat}`);});


// Planner STEP5 now reflects real mock attempts as well as ordinary problem sessions.
const _roadmapDataV13=roadmapData;
roadmapData=function(){
  const data=_roadmapDataV13();
  if(data.length){
    const mockCount=(profile.mockHistory||[]).length;
    const sessionCount=(profile.sessions||[]).length;
    const p=Math.min(100,Math.round(((mockCount*2+sessionCount)/12)*100));
    data[data.length-1].pct=Math.max(data[data.length-1].pct,p);
    data[data.length-1].desc='弱点演習・復習・科目A MOCK';
  }
  return data;
};




// ===== v44: learning history analytics =====
const ANALYTICS_CATEGORIES=['基礎理論','コンピュータ','データベース','ネットワーク','セキュリティ','アルゴリズム','マネジメント','ストラテジ'];

function analyticsDateMinus(days){return localDateISO(-days)}
function analyticsMinutes(days){
  let total=0;
  for(let i=0;i<days;i++) total+=Number(profile.activity?.[analyticsDateMinus(i)]?.minutes||0);
  return total;
}
function analyticsActiveDays(days){
  let n=0;for(let i=0;i<days;i++)if(Number(profile.activity?.[analyticsDateMinus(i)]?.minutes||0)>0)n++;return n;
}
function analyticsAttemptStream(){
  const rows=[];
  (profile.sessions||[]).forEach((s,si)=>(s.log||[]).forEach((x,li)=>rows.push({date:s.date,cat:x.cat,ok:!!x.ok,order:si*100+li,source:'session'})));
  (profile.mockHistory||[]).forEach((h,hi)=>(h.details||[]).forEach((d,di)=>{
    const q=QUESTION_BANK.find(x=>x.id===d.id);if(!q)return;
    rows.push({date:h.date,cat:q.cat,ok:d.answerIndex!==null&&d.answerIndex===d.correctIndex,order:hi*100+di+50000,source:'mock'});
  }));
  return rows.sort((a,b)=>String(b.date).localeCompare(String(a.date))||a.order-b.order);
}
function analyticsTrend(cat){
  const rows=analyticsAttemptStream().filter(x=>x.cat===cat);
  const recent=rows.slice(0,10),previous=rows.slice(10,20);
  if(recent.length<3||previous.length<3)return {delta:null,recent:null,previous:null,n:rows.length};
  const pct=a=>Math.round(a.filter(x=>x.ok).length/a.length*100);
  const r=pct(recent),p=pct(previous);return {delta:r-p,recent:r,previous:p,n:rows.length};
}
function analyticsCategorySnapshot(cat){
  let attempts=0,correct=0;
  QUESTION_BANK.filter(q=>q.cat===cat).forEach(q=>{const s=profile.qStats?.[q.id];if(s){attempts+=s.attempts||0;correct+=s.correct||0}});
  const accuracy=attempts?Math.round(correct/attempts*100):null;
  return {cat,attempts,accuracy,mastery:Math.round(profile.skills?.[cat]??50),trend:analyticsTrend(cat)};
}
function analyticsTrendClass(delta){return delta==null?'flat':delta>=8?'up':delta<=-8?'down':'flat'}
function analyticsTrendText(t){
  if(t.delta==null)return 'データ待ち';
  if(t.delta>=8)return `↑ +${t.delta}pt`;
  if(t.delta<=-8)return `↓ ${t.delta}pt`;
  return `→ ${t.delta>0?'+':''}${t.delta}pt`;
}
function renderAnalyticsHeatmap(){
  const root=document.getElementById('analyticsHeatmap');if(!root)return;
  const vals=[];for(let i=29;i>=0;i--)vals.push({date:analyticsDateMinus(i),min:Number(profile.activity?.[analyticsDateMinus(i)]?.minutes||0)});
  const max=Math.max(1,...vals.map(x=>x.min));
  root.innerHTML=vals.map(x=>{const ratio=x.min/max;const lv=x.min<=0?'':ratio<=.25?'lv1':ratio<=.5?'lv2':ratio<=.75?'lv3':'lv4';return `<div class="analytics-day ${lv} ${x.date===localDateISO(0)?'today':''}" title="${x.date}：${x.min}分"></div>`}).join('')+`<div class="analytics-heatmap-labels" style="grid-column:1/-1"><span>${vals[0].date.slice(5)}</span><span>今日</span></div>`;
}
function renderAnalyticsSignals(snaps){
  const root=document.getElementById('analyticsSignals');if(!root)return;
  const usable=snaps.filter(x=>x.trend.delta!=null);
  if(!usable.length){root.innerHTML='<div class="analytics-signal neutral"><div class="analytics-signal-top"><b>比較データを集めています</b><span class="analytics-delta">—</span></div><p>同じ分野で20回答ほど蓄積すると、直近10回答とその前10回答を比較して伸びを表示します。</p></div>';return;}
  const best=[...usable].sort((a,b)=>b.trend.delta-a.trend.delta)[0],worst=[...usable].sort((a,b)=>a.trend.delta-b.trend.delta)[0];
  let cards=[];
  if(best.trend.delta>0)cards.push(`<div class="analytics-signal good"><div class="analytics-signal-top"><b>📈 伸び：${best.cat}</b><span class="analytics-delta">+${best.trend.delta}pt</span></div><p>直近10回答 ${best.trend.recent}% ← その前 ${best.trend.previous}%</p></div>`);
  if(worst.trend.delta<0)cards.push(`<div class="analytics-signal bad"><div class="analytics-signal-top"><b>🔎 要注意：${worst.cat}</b><span class="analytics-delta">${worst.trend.delta}pt</span></div><p>直近10回答 ${worst.trend.recent}% ← その前 ${worst.trend.previous}%</p></div>`);
  if(!cards.length)cards.push('<div class="analytics-signal neutral"><div class="analytics-signal-top"><b>→ 最近は安定</b><span class="analytics-delta">横ばい</span></div><p>比較可能な分野では、大きな上昇・低下は見られません。</p></div>');
  root.innerHTML=cards.join('');
}
function renderAnalyticsCategories(snaps){
  const root=document.getElementById('analyticsCategories');if(!root)return;
  root.innerHTML=snaps.map(x=>{const acc=x.accuracy==null?'—':`${x.accuracy}%`,bar=x.accuracy==null?x.mastery:x.accuracy,tc=analyticsTrendClass(x.trend.delta);return `<div class="analytics-category-row"><div class="analytics-category-name">${x.cat}</div><div class="analytics-cat-bar"><div class="analytics-cat-fill" style="width:${bar}%"></div></div><div class="analytics-cat-metric">正答 ${acc}</div><div class="analytics-cat-metric">習熟 ${x.mastery}%</div><div class="analytics-trend-chip ${tc}">${analyticsTrendText(x.trend)}</div></div>`}).join('');
}
function analyticsJourneyCounts(){
  const js=Object.values(profile.reviewJourneys||{}),count=stage=>js.filter(j=>j.stage===stage).length;
  return {relearn:count('relearn'),verify:count('verify'),spaced:count('spaced'),stable:count('stable')};
}
function renderAnalyticsJourneys(){
  const counts=analyticsJourneyCounts();
  document.getElementById('analyticsStableTotal').textContent=counts.stable;
  const stage=document.getElementById('analyticsJourneyStages');if(stage)stage.innerHTML=`<div class="analytics-stage"><b>${counts.relearn}</b><span>教材</span></div><div class="analytics-stage"><b>${counts.verify}</b><span>類題</span></div><div class="analytics-stage"><b>${counts.spaced}</b><span>後日待ち</span></div><div class="analytics-stage"><b>${counts.stable}</b><span>定着</span></div>`;
  const stable=Object.values(profile.reviewJourneys||{}).filter(j=>j.stage==='stable').sort((a,b)=>String(b.completedAt||'').localeCompare(String(a.completedAt||''))).slice(0,6);
  const list=document.getElementById('analyticsStableList');if(list)list.innerHTML=stable.length?stable.map(j=>`<div class="analytics-stable-item"><b>${escapeHtml(j.concept)}</b><span>${escapeHtml(j.completedAt||'定着')}</span></div>`).join(''):'<div class="analytics-format-empty">まだ定着まで完了した復習ルートはありません。</div>';
}
function analyticsBFormatRows(){
  const map={};const add=(name,ok)=>{if(!name)return;if(!map[name])map[name]={name,total:0,correct:0};map[name].total++;if(ok)map[name].correct++};
  // Algorithm mini mock: all questions are intermediate-state prediction.
  (profile.bMockHistory||[]).forEach(h=>(h.details||[]).forEach(d=>add('途中状態',!!d.ok)));
  // Compound challenge stores the question kind in v36+ history.
  (profile.bCompoundHistory||[]).forEach(h=>(h.details||[]).forEach(d=>add(d.kind||'処理結果',!!d.ok)));
  // Full Subject-B practice already stores normalized format names.
  (profile.bFinalHistory||[]).forEach(h=>(h.details||[]).forEach(d=>add(d.format||(d.kind==='security'?'ケース判断':'処理結果'),!!d.ok)));
  // Security mini mock: infer log-reading vs scenario judgment from its source scenario.
  (profile.securityMockHistory||[]).forEach(h=>(h.details||[]).forEach(d=>{const s=SECURITY_SCENARIOS.find(x=>x.id===d.scenarioId);add(s?.log?'ログ読解':'ケース判断',!!d.ok)}));
  return Object.values(map).sort((a,b)=>b.total-a.total);
}
function renderAnalyticsBFormats(){
  const root=document.getElementById('analyticsBFormats');if(!root)return;const rows=analyticsBFormatRows();
  if(!rows.length){root.innerHTML='<div class="analytics-format-empty">科目Bの実戦モードを解くと、途中状態・空欄補充・ケース判断などの形式別正答率を表示します。</div>';return;}
  root.innerHTML=rows.map(x=>{const pct=Math.round(x.correct/x.total*100);return `<div class="analytics-format-row"><div class="analytics-format-name">${escapeHtml(x.name)}</div><div class="analytics-format-bar"><div class="analytics-format-fill" style="width:${pct}%"></div></div><div class="analytics-format-score">${pct}% (${x.correct}/${x.total})</div></div>`}).join('');
}
function renderAnalyticsNext(snaps){
  const root=document.getElementById('analyticsNext');if(!root)return;
  const active=activeReviewJourneys();
  if(active.length){const j=active[0];root.innerHTML=`<div class="analytics-next-icon">🔁</div><div><b>${escapeHtml(j.concept)}の復習ルートを続ける</b><span>${escapeHtml(journeyGuidance(j))}</span><button data-analytics-next-action>復習を続ける →</button></div>`;root.querySelector('[data-analytics-next-action]').onclick=()=>startJourneyAction(j.id);return;}
  const attempted=snaps.filter(x=>x.attempts>=3&&x.accuracy!=null);
  if(attempted.length){const weak=[...attempted].sort((a,b)=>a.accuracy-b.accuracy||a.mastery-b.mastery)[0];root.innerHTML=`<div class="analytics-next-icon">🎯</div><div><b>${weak.cat}を10問で確認</b><span>累積正答率 ${weak.accuracy}%・習熟度 ${weak.mastery}%です。現在もっとも確認効果が高い分野です。</span><button data-analytics-next-action>苦手画面で確認 →</button></div>`;root.querySelector('[data-analytics-next-action]').onclick=()=>showScreen('weak');return;}
  root.innerHTML='<div class="analytics-next-icon">🌱</div><div><b>まず演習データを集める</b><span>まだ分析に必要な回答数が少ないため、今日の学習やランダム問題を進めると分析精度が上がります。</span></div>';
}
const V344_LEARNING_OUTCOMES_SPEC=Object.freeze({
  version:'v344',
  profileSchemaChange:false,
  trendWindowMax:10,
  trendWindowMin:3,
  meaningfulDelta:8,
  wording:'recorded-answer-windows'
});

function analyticsOutcomeTrendV344(cat){
  const rows=analyticsAttemptStream().filter(x=>x.cat===cat);
  const recent=rows.slice(0,V344_LEARNING_OUTCOMES_SPEC.trendWindowMax);
  const previous=rows.slice(V344_LEARNING_OUTCOMES_SPEC.trendWindowMax,V344_LEARNING_OUTCOMES_SPEC.trendWindowMax*2);
  const result={cat,delta:null,recent:null,previous:null,recentN:recent.length,previousN:previous.length,totalRecorded:rows.length};
  if(recent.length<V344_LEARNING_OUTCOMES_SPEC.trendWindowMin||previous.length<V344_LEARNING_OUTCOMES_SPEC.trendWindowMin)return result;
  const pct=a=>Math.round(a.filter(x=>x.ok).length/a.length*100);
  result.recent=pct(recent);result.previous=pct(previous);result.delta=result.recent-result.previous;
  return result;
}

function learningOutcomeReportDecisionV344({sevenMinutes=0,sevenActiveDays=0,trends=[],snapshots=[],activeReview=null}={}){
  const usable=(trends||[]).filter(x=>Number.isFinite(x?.delta));
  const growth=usable.filter(x=>x.delta>=V344_LEARNING_OUTCOMES_SPEC.meaningfulDelta).sort((a,b)=>b.delta-a.delta)[0]||null;
  let growthState='pending';
  if(growth)growthState='growth';
  else if(usable.length)growthState='stable';

  let next={kind:'collect',title:'まず演習データを集める',detail:'回答が増えると、次に伸ばす分野をより具体的に案内できます。'};
  if(activeReview?.concept){
    next={kind:'review',title:`${activeReview.concept}の復習を続ける`,detail:activeReview.guidance||'進行中の復習ルートを完了すると、定着までつながります。'};
  }else{
    const attempted=(snapshots||[]).filter(x=>Number(x?.attempts)>=3&&Number.isFinite(x?.accuracy));
    if(attempted.length){
      const weak=[...attempted].sort((a,b)=>a.accuracy-b.accuracy||a.mastery-b.mastery)[0];
      next={kind:'category',cat:weak.cat,title:`${weak.cat}を次に確認`,detail:`累積正答率 ${weak.accuracy}%・習熟度 ${weak.mastery}%をもとに選んでいます。`};
    }
  }

  return {
    activity:{minutes:Math.max(0,Number(sevenMinutes)||0),activeDays:Math.max(0,Number(sevenActiveDays)||0)},
    growthState,
    growth,
    next,
    passProbability:false
  };
}

function learningOutcomeReportV344(){
  const snapshots=ANALYTICS_CATEGORIES.map(analyticsCategorySnapshot);
  const trends=ANALYTICS_CATEGORIES.map(analyticsOutcomeTrendV344);
  const active=activeReviewJourneys()[0]||null;
  return learningOutcomeReportDecisionV344({
    sevenMinutes:analyticsMinutes(7),
    sevenActiveDays:analyticsActiveDays(7),
    trends,
    snapshots,
    activeReview:active?{concept:active.concept,guidance:journeyGuidance(active)}:null
  });
}

