  document.getElementById('weakTopTitle').textContent=`最優先：${top.cat}`;
  document.getElementById('weakTopScore').textContent=top.priority;
  document.getElementById('weakTopSub').textContent=
    `習熟度 ${top.mastery}%・正答率 ${top.accuracy}%・弱い思考：${top.weakestCognitive}${top.weakestCognitiveScore==null?'':` ${top.weakestCognitiveScore}%`}・${top.dominant==='データ不足'?'誤答理由はまだ未記録':`主なつまずき：${top.dominant}`}`;
  const weakTopAction=document.getElementById('weakTopAction');
