// ===== v17: technique-specific problem solving =====
if(!profile.techniqueStats) profile.techniqueStats={};

function rxKind(){
  return String(quizMode).startsWith('rx:') ? String(quizMode).split(':')[1] : null;
}
function stopQuestionPacer(){
  if(rxPaceHandle){clearInterval(rxPaceHandle);rxPaceHandle=null;}
}
function safeTechniqueSnapshot(){
  const kind=rxKind();
  if(!kind) return null;
  const out={kind};
  if(kind==='calc') out.work=(rxTechniqueData.work||'').slice(0,120);
  if(kind==='read') out.marked=[...(rxTechniqueData.marked||[])];
  if(kind==='contrast') out.finalists=[...(rxTechniqueData.finalists||[])];
  if(kind==='speed') out.seconds=rxPaceElapsed||0;
  if(kind==='repeat') out.confirmed=!!rxTechniqueData.confirmed;
  return out;
}
function techniqueStat(kind){
  if(!profile.techniqueStats[kind]) profile.techniqueStats[kind]={sessions:0,questions:0,recovered:0,firstWrong:0};
  return profile.techniqueStats[kind];
}
function recordTechniqueSessionStats(){
  const kind=rxKind();
  if(!kind) return;
  const st=techniqueStat(kind);
  st.sessions++;
  const rows=sessionLog.filter(x=>x.technique===kind);
  st.questions+=rows.length;
  st.recovered+=rows.filter(x=>x.recovered).length;
  st.firstWrong+=rows.filter(x=>!x.ok).length;
  st.last=localDateISO(0);
  saveProfile();
}

function renderRxTechnique(q){
  const box=document.getElementById('rxTechnique');
  const body=document.getElementById('rxTechniqueBody');
  if(!box||!body) return;
  const kind=rxKind();
  stopQuestionPacer();
  rxPaceElapsed=0;
  const optionsEl=document.getElementById('quizOptions');


  if(!kind || kind==='knowledge'){
    box.style.display='none';
    rxTechniqueReady=true;
    return;
  }

  box.style.display='block';
  const icon=document.getElementById('rxTechniqueIcon');
  const title=document.getElementById('rxTechniqueTitle');
  const desc=document.getElementById('rxTechniqueDesc');

  if(kind==='calc'){
    icon.textContent='🧮';
    title.textContent='途中式を残してから答える';
    desc.textContent='頭の中だけで計算せず、式・途中結果・単位のどれかを書きます。';
    rxTechniqueReady=false;
    rxTechniqueData={work:''};
    body.innerHTML=`
      <textarea class="calc-work" id="rxCalcWork" placeholder="例：0.9 × 0.9 = 0.81&#10;または 200 × 100 × 8 = 160000 bit"></textarea>
      <div class="technique-checks">
        <span class="tech-check" id="calcCheckFormula">式を書く</span>
        <span class="tech-check">桁を確認</span>
        <span class="tech-check">単位を確認</span>
      </div>`;
    document.getElementById('rxCalcWork').addEventListener('input',e=>{
      rxTechniqueData.work=e.target.value;
      rxTechniqueReady=e.target.value.trim().length>=2;
      document.getElementById('calcCheckFormula').classList.toggle('done',rxTechniqueReady);
    });
    return;
  }

  if(kind==='read'){
    icon.textContent='🔍';
    title.textContent='条件語を先に拾う';
    desc.textContent='答えを見る前に、問題文で判断を左右する語を確認します。';
    const keywords=['最も適切','不適切','適切','以上','以下','未満','超える','最優先','まず','次に','主な','一般に','必ず'];
    let found=keywords.filter(k=>q.q.includes(k));
    if(!found.length) found=['何を問われているか確認'];
    rxTechniqueReady=false;
    rxTechniqueData={marked:new Set()};
    body.innerHTML=`<div class="condition-chips">${found.map((k,i)=>`<button class="condition-chip" data-cond="${i}">${k}</button>`).join('')}</div>
      <div class="finalist-status">少なくとも1つ確認すると回答できます。</div>`;
    body.querySelectorAll('.condition-chip').forEach((btn,i)=>btn.onclick=()=>{
      btn.classList.toggle('marked');
      if(btn.classList.contains('marked')) rxTechniqueData.marked.add(found[i]);
      else rxTechniqueData.marked.delete(found[i]);
      rxTechniqueReady=rxTechniqueData.marked.size>0;
    });
    return;
  }

  if(kind==='contrast'){
    icon.textContent='⚖️';
    title.textContent='まず2択まで絞る';
    desc.textContent='最終回答の前に、比較する2候補を明示します。';
    rxTechniqueReady=false;
    rxTechniqueData={finalists:new Set()};
    body.innerHTML=`<div class="finalist-grid">${q.options.map((o,i)=>`<button class="finalist-option" data-finalist="${i}">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}</div>
      <div class="finalist-status" id="finalistStatus">0 / 2 選択</div>`;
    body.querySelectorAll('.finalist-option').forEach((btn,i)=>btn.onclick=()=>{
      if(rxTechniqueData.finalists.has(i)){
        rxTechniqueData.finalists.delete(i);btn.classList.remove('picked');
      }else if(rxTechniqueData.finalists.size<2){
        rxTechniqueData.finalists.add(i);btn.classList.add('picked');
      }else popToast('比較する候補は2つまでです');
      rxTechniqueReady=rxTechniqueData.finalists.size===2;
      document.getElementById('finalistStatus').textContent=`${rxTechniqueData.finalists.size} / 2 選択`;
    });
    return;
  }

  if(kind==='speed'){
    icon.textContent='⏱️';
    title.textContent='1問90秒ペース';
    desc.textContent='90秒を超えたら、いったん判断して見直しへ回す感覚を身につけます。';
    rxTechniqueReady=true;
    rxTechniqueData={};
    rxPaceRemaining=90;
    rxPaceElapsed=0;
    body.innerHTML=`<div class="pace-wrap">
      <div class="pace-clock" id="paceClock">90s</div>
      <div><div class="pace-track"><div class="pace-fill" id="paceFill"></div></div>
      <div class="pace-label" id="paceLabel">目安：90秒以内。30秒時点で選択肢を絞り始めます。</div></div>
    </div>`;
    rxPaceHandle=setInterval(()=>{
      rxPaceElapsed++;
      rxPaceRemaining--;
      const clock=document.getElementById('paceClock');
      const fill=document.getElementById('paceFill');
      const label=document.getElementById('paceLabel');
      if(!clock||!fill||!label){stopQuestionPacer();return;}
      if(rxPaceRemaining>=0){
        clock.textContent=`${rxPaceRemaining}s`;
        fill.style.width=Math.max(0,rxPaceRemaining/90*100)+'%';
        fill.classList.toggle('warn',rxPaceRemaining<=30);
        if(rxPaceRemaining<=30) label.textContent='残り30秒以下：候補を絞り、いったん回答を決めましょう。';
      }else{
        clock.textContent=`+${Math.abs(rxPaceRemaining)}s`;
        clock.classList.add('over');
        fill.style.width='100%';fill.classList.add('over');
        label.textContent='90秒を超過。実戦なら見直しフラグへ回す判断も有効です。';
      }
    },1000);
    return;
  }

  if(kind==='repeat'){
    icon.textContent='🔁';
    title.textContent='前回のつまずきを思い出す';
    desc.textContent='同じ間違いを無意識に繰り返さないため、前回の原因を先に確認します。';
    const ms=profile.mockMistakeStats?.[q.id];
    const qs=profile.qStats?.[q.id];
    const ordinary=Math.max(0,(qs?.attempts||0)-(qs?.correct||0));
    const misses=Math.max(ms?.misses||0,ordinary);
    const reason=ms?.lastReason||qs?.lastReason||'原因未記録';
    rxTechniqueReady=false;
    rxTechniqueData={confirmed:false};
    body.innerHTML=`<div class="repeat-memory"><b>この論点の誤答記録：約${misses}回</b><br>直近の原因：${reason}<br>今回は同じ原因を避けて解きます。</div>
      <button class="repeat-confirm" id="repeatConfirm">前回のつまずきを確認した</button>`;
    document.getElementById('repeatConfirm').onclick=e=>{
      rxTechniqueData.confirmed=true;rxTechniqueReady=true;
      e.currentTarget.classList.add('done');e.currentTarget.textContent='✓ 確認済み';
    };
    return;
  }

  box.style.display='none';
  rxTechniqueReady=true;
}

function validateRxTechniqueBeforeAnswer(){
  const kind=rxKind();
  if(quizMode==='review'){
    if(!rxTechniqueReady){
      popToast('まず記憶から答えを思い出してから選択肢へ進みましょう');
      return false;
    }
    return true;
  }
  if(!kind || kind==='knowledge' || kind==='speed') return true;
  if(!rxTechniqueReady){
    const msgs={
      calc:'途中式を1行だけでも書いてから回答しましょう。',
      read:'問題文の条件語を1つ確認してから回答しましょう。',
      contrast:'比較する2つの候補を先に選んでください。',
      repeat:'前回のつまずきを確認してから回答しましょう。'
    };
    popToast(msgs[kind]||'解く前のステップを完了してください');
    return false;
  }
  if(kind==='contrast' && !rxTechniqueData.finalists.has(quizSelected)){
    popToast('先ほど選んだ2択の中から最終回答を選んでください');
    return false;
  }
  return true;
}

// ===== v16: adaptive prescription engine =====
let rxTimerHandle=null;
let rxSeconds=0;

const RX_CALC_KEYWORDS=['基数','16進','データ量','稼働','信頼性','損益','財務','スループット','サブネット','画像'];
const RX_CONTRAST_KEYWORDS=['TCP','UDP','スタック','キュー','公開鍵','共通鍵','バックアップ','RAM','ROM','アジャイル','ウォーターフォール','SLA','監査','外部キー'];

function normalizeReason(reason){
  if(['用語を知らなかった','ほぼ分からなかった'].includes(reason)) return '知識不足';
  if(reason==='計算方法を忘れた') return '計算ミス';
  if(reason==='問題文を読み違えた') return '読み違い';
  return reason||'データ不足';
}
// FE QUEST v343 — Subject A adaptive evidence confidence.
// This is injected into app-v343.js in place of the previous recommendedPrescription().
// It deliberately reuses existing profile fields; no profile schema migration is required.
const V343_ADAPTIVE_PRECISION_SPEC=Object.freeze({
  version:'v343',
  reasonWindowDays:30,
  minDistinctReasonQuestions:2,
  minTimedAnswers:5,
  slowSeconds:110,
  weakAccuracyThreshold:80,
  policy:'accuracy-and-repeat-primary-reason-time-gated-no-schema-change'
});
const V343_SUBJECT_A_REASONS=Object.freeze(['知識不足','計算ミス','読み違い','2択で迷った','時間不足']);

function subjectAEvidenceAgeDaysV343(value){
  const raw=String(value||'').trim();
  if(!/^\d{4}-\d{2}-\d{2}$/.test(raw))return null;
  const at=Date.parse(raw+'T00:00:00Z');
  const now=Date.parse(localDateISO(0)+'T00:00:00Z');
  if(!Number.isFinite(at)||!Number.isFinite(now))return null;
  return Math.max(0,Math.floor((now-at)/86400000));
}
function subjectAAdaptiveEvidenceV343(cat){
  ensureQuestionProfile();
  const ids=[...new Set(weakQuestionIdsForCat(cat))];
  const reasonCounts={};
  const recentReasonCounts={};
  let timedAnswers=0,weightedSeconds=0;
  ids.forEach(id=>{
    const qst=profile.qStats?.[id]||{};
    const mst=profile.mockMistakeStats?.[id]||{};
    const timed=Math.max(0,Number(qst.timedAnswers)||0);
    const avg=Math.max(0,Number(qst.avgSeconds)||0);
    if(timed>0&&avg>0){timedAnswers+=timed;weightedSeconds+=timed*avg;}
    const reason=normalizeReason(reasonForQuestion(id));
    if(!V343_SUBJECT_A_REASONS.includes(reason))return;
    reasonCounts[reason]=(reasonCounts[reason]||0)+1;
    const dates=[qst.last,mst.last].filter(Boolean).sort();
    const age=subjectAEvidenceAgeDaysV343(dates.at(-1));
    if(age!=null&&age<=V343_ADAPTIVE_PRECISION_SPEC.reasonWindowDays){
      recentReasonCounts[reason]=(recentReasonCounts[reason]||0)+1;
    }
  });
  const ranked=Object.entries(reasonCounts).sort((a,b)=>b[1]-a[1]||V343_SUBJECT_A_REASONS.indexOf(a[0])-V343_SUBJECT_A_REASONS.indexOf(b[0]));
  const reason=ranked[0]?.[0]||null;
  const reasonSupport=ranked[0]?.[1]||0;
  const secondSupport=ranked[1]?.[1]||0;
  const recentReasonSupport=reason?(recentReasonCounts[reason]||0):0;
  const reasonConfident=!!reason&&reasonSupport>=V343_ADAPTIVE_PRECISION_SPEC.minDistinctReasonQuestions&&recentReasonSupport>=1&&reasonSupport>secondSupport;
  return {
    cat,
    reason,
    reasonSupport,
    recentReasonSupport,
    reasonConfident,
    timedAnswers,
    avgSeconds:timedAnswers?Math.round(weightedSeconds/timedAnswers):0,
    timingConfident:timedAnswers>=V343_ADAPTIVE_PRECISION_SPEC.minTimedAnswers
  };
}
function subjectAPrescriptionDecisionV343(top,evidence){
  const e=evidence||{};
  const accuracy=Number(top?.accuracy);
  const weakAccuracy=Number.isFinite(accuracy)&&accuracy<V343_ADAPTIVE_PRECISION_SPEC.weakAccuracyThreshold;
  const repeats=Math.max(0,Number(top?.repeats)||0);
  const reason=e.reason||null;
  const base={cat:top?.cat||'基礎理論',priority:Number(top?.priority)||0,v343Evidence:{...e,weakAccuracy,repeats}};

  if(e.reasonConfident){
    if(reason==='計算ミス')return {...base,kind:'calc',reason,evidenceConfidence:'reason-repeated'};
    if(reason==='読み違い')return {...base,kind:'read',reason,evidenceConfidence:'reason-repeated'};
    if(reason==='2択で迷った')return {...base,kind:'contrast',reason,evidenceConfidence:'reason-repeated'};
    if(reason==='時間不足'&&e.timingConfident&&e.avgSeconds>=V343_ADAPTIVE_PRECISION_SPEC.slowSeconds&&weakAccuracy){
      return {...base,kind:'speed',reason,evidenceConfidence:'reason-and-time'};
    }
    if(reason==='知識不足')return {...base,kind:'knowledge',reason,evidenceConfidence:'reason-repeated'};
  }

  // A single recent time-shortage report may become actionable only when measured timing
  // and weak accuracy corroborate it. Slow-but-correct data alone must never force speed work.
  if(reason==='時間不足'&&e.reasonSupport>=1&&e.recentReasonSupport>=1&&e.timingConfident&&e.avgSeconds>=V343_ADAPTIVE_PRECISION_SPEC.slowSeconds&&weakAccuracy){
    return {...base,kind:'speed',reason,evidenceConfidence:'reason-time-corroborated'};
  }
  if(repeats>=2)return {...base,kind:'repeat',reason:'繰り返し誤答',evidenceConfidence:'repeat-errors'};
  return {...base,kind:'knowledge',reason:'データ不足',evidenceConfidence:'insufficient'};
}
function recommendedPrescription(){
  const top=sortedCategoryAnalytics()[0]||{cat:'基礎理論',dominant:'データ不足',avgSec:0,repeats:0,priority:0,accuracy:0};
  const evidence=subjectAAdaptiveEvidenceV343(top.cat);
  return subjectAPrescriptionDecisionV343(top,evidence);
}
globalThis.V343_ADAPTIVE_PRECISION_SPEC=V343_ADAPTIVE_PRECISION_SPEC;
globalThis.subjectAAdaptiveEvidenceV343=subjectAAdaptiveEvidenceV343;
globalThis.subjectAPrescriptionDecisionV343=subjectAPrescriptionDecisionV343;
function prescriptionMeta(modeOrRx){
  let rx=modeOrRx;
  if(typeof rx==='string'){
    const parts=rx.split(':');
    rx={kind:parts[1]||'knowledge',cat:parts.slice(2).join(':')||weakestSkill()};
  }
  const map={
    knowledge:{icon:'📘',title:`${rx.cat}：知識補強`,desc:'関連教材で理解を作ってから演習へ進みます。'},
    calc:{icon:'🧮',title:`${rx.cat}：計算ドリル`,desc:'数値・式・単位を丁寧に追う問題を優先します。'},
    read:{icon:'🔍',title:`${rx.cat}：条件語ドリル`,desc:'「最も適切」「以上・未満」など条件を意識して解きます。'},
    contrast:{icon:'⚖️',title:`${rx.cat}：比較ドリル`,desc:'似た用語・方式の違いを根拠付きで選ぶ練習です。'},
    speed:{icon:'⏱️',title:`${rx.cat}：15分スプリント`,desc:'10問を15分。1問90秒を目安に時間配分を練習します。'},
    repeat:{icon:'🔁',title:`${rx.cat}：繰り返し誤答つぶし`,desc:'何度も間違えている問題・論点を最優先で解き直します。'}
  };
  return map[rx.kind]||map.knowledge;
}
function rxMode(rx=recommendedPrescription()){return `rx:${rx.kind}:${rx.cat}`;}
function questionMatchesKeywords(q,words){const t=`${q.concept} ${q.q}`;return words.some(w=>t.includes(w));}
function padQuizPool(pool,cat,count){
  const used=new Set(pool.map(q=>q.id));
  const same=shuffled(QUESTION_BANK.filter(q=>q.cat===cat&&!used.has(q.id)));
  const rest=shuffled(QUESTION_BANK.filter(q=>!used.has(q.id)));
  return [...pool,...same,...rest].slice(0,count);
}
function buildPrescriptionQuiz(mode){
  const p=String(mode).split(':');
  const kind=p[1]||'knowledge',cat=p.slice(2).join(':')||weakestSkill();
  const same=QUESTION_BANK.filter(q=>q.cat===cat);
  let pool=[];
  if(kind==='calc'){
    pool=shuffled(same.filter(q=>questionMatchesKeywords(q,RX_CALC_KEYWORDS)));
    if(pool.length<6) pool=[...pool,...shuffled(QUESTION_BANK.filter(q=>questionMatchesKeywords(q,RX_CALC_KEYWORDS)&&!pool.some(x=>x.id===q.id)))];
    return padQuizPool(pool,cat,8);
  }
  if(kind==='read'){
    const words=['最も適切','適切','未満','以上','次に','主な','一般に','どれ'];
    return padQuizPool(shuffled(same.filter(q=>words.some(w=>q.q.includes(w)))),cat,8);
  }
  if(kind==='contrast'){
    pool=shuffled(same.filter(q=>questionMatchesKeywords(q,RX_CONTRAST_KEYWORDS)));
    if(pool.length<6) pool=[...pool,...shuffled(QUESTION_BANK.filter(q=>questionMatchesKeywords(q,RX_CONTRAST_KEYWORDS)&&!pool.some(x=>x.id===q.id)))];
    return padQuizPool(pool,cat,8);
  }
  if(kind==='repeat'){
    const ids=new Set(repeatedWrongQuestions().map(x=>x.q.id));
    return padQuizPool(shuffled(QUESTION_BANK.filter(q=>ids.has(q.id))),cat,8);
  }
  if(kind==='speed') return padQuizPool(shuffled(same),cat,10);
  return padQuizPool(shuffled(same),cat,8);
}
function stopRxTimer(){
  if(rxTimerHandle){clearInterval(rxTimerHandle);rxTimerHandle=null;}
  rxSeconds=0;
  const e=document.getElementById('rxTimer');
  if(e){e.style.display='none';e.classList.remove('warn');}
}
function updateRxTimer(){
  const e=document.getElementById('rxTimer');if(!e)return;
  e.textContent=`${String(Math.floor(rxSeconds/60)).padStart(2,'0')}:${String(rxSeconds%60).padStart(2,'0')}`;
  e.classList.toggle('warn',rxSeconds<=180);
}
function startRxSpeedTimer(){
  stopRxTimer();rxSeconds=900;
  const e=document.getElementById('rxTimer');if(e)e.style.display='block';
  updateRxTimer();
  rxTimerHandle=setInterval(()=>{
    rxSeconds=Math.max(0,rxSeconds-1);updateRxTimer();
    if(rxSeconds===0){stopRxTimer();popToast('15分経過です。残りは正確さを優先して解きましょう。');}
  },1000);
}
function configurePrescriptionUI(mode){
  const b=document.getElementById('rxBanner');if(!b)return;
  if(!String(mode).startsWith('rx:')){b.style.display='none';stopRxTimer();return;}
  const m=prescriptionMeta(mode);
  b.style.display='flex';
  document.getElementById('rxBannerIcon').textContent=m.icon;
  document.getElementById('rxBannerTitle').textContent=m.title;
  document.getElementById('rxBannerDesc').textContent=m.desc;
  if(String(mode).startsWith('rx:speed:'))startRxSpeedTimer();else stopRxTimer();
}
function refreshPrescriptionCard(){
  const rx=recommendedPrescription(),m=prescriptionMeta(rx);
  const a=document.getElementById('rxMiniLabel'),b=document.getElementById('rxMiniDesc');
  if(a)a.textContent=rx.reason==='データ不足'?'診断用':rx.reason;
  if(b)b.textContent=`${m.icon} ${m.title} — ${m.desc}`;
}
function startRecommendedPrescription(){
  const rx=recommendedPrescription();
  if(rx.kind==='knowledge'){startLesson(pickLessonForSkill(rx.cat));return;}
  showScreen('problems');startQuiz(rxMode(rx));
}
