function topReviewCandidates(n=3){
  ensureQuestionProfile();
  const attempted=QUESTION_BANK.filter(q=>profile.qStats[q.id]?.attempts>0);
  return attempted.sort((a,b)=>reviewUrgency(b)-reviewUrgency(a)).slice(0,n);
}
function reviewTimingLabel(stat){
  const due=stat?.due;
  if(!due) return {text:'復習タイミング：自動調整',due:false};
  const today=localDateISO(0);
  if(due<=today) return {text:'復習タイミング：今',due:true};
  const days=Math.max(1,daysBetweenISO(today,due));
  return {text:days===1?'次回の復習：明日':`次回の復習：${days}日後`,due:false};
}
function renderHomeReviewCandidates(){
  const root=document.getElementById('homeReviewCandidates');
  if(!root) return;
  const items=topReviewCandidates(3);
  if(!items.length){
    root.innerHTML='<div class="mini-card"><div class="big">🧠</div><b>学習データ待ち</b><div class="sub">問題を解くと、忘れそうな論点をここに表示します。</div></div>';
    return;
  }
  const icons={'基礎理論':'🔢','コンピュータ':'⚙️','データベース':'🗃️','ネットワーク':'🌐','セキュリティ':'🛡️','アルゴリズム':'🧩','マネジメント':'📋','ストラテジ':'📈'};
  root.innerHTML=items.map(q=>{
    const st=profile.qStats[q.id];
    const r=memoryRetention(st)??100;
    const timing=reviewTimingLabel(st);
    return `<div class="mini-card"><div class="big">${icons[q.cat]||'🧠'}</div><b>${escapeHtml(q.concept)}</b>
      <div class="sub">${escapeHtml(q.cat)}・${escapeHtml(q.cognitiveLevel||'')}・推定保持 ${r}%</div>
      <div class="progress" style="margin-top:10px"><div style="width:${r}%"></div></div>
      <div class="memory-risk" style="${timing.due?'':'color:var(--muted)'}">${escapeHtml(timing.text)}</div></div>`;
  }).join('');
}
function renderMemoryHealth(){
  const h=memoryHealth();
  const measured=h.attempted>0;
  const ring=document.getElementById('memoryHealthRing');
  if(ring){
    ring.style.setProperty('--memory-p',measured?h.avg:0);
    ring.classList.toggle('is-unmeasured',!measured);
    ring.setAttribute('aria-label',measured?`推定記憶保持率 ${h.avg}%`:'記憶保持率は未計測です');
  }
  const value=document.getElementById('memoryHealthValue');
  if(value) value.textContent=measured?h.avg+'%':'未計測';
  const caption=document.getElementById('memoryHealthCaption');
  if(caption) caption.textContent=measured?'推定保持':'問題演習後に表示';
  if(document.getElementById('memoryFreshCount')) document.getElementById('memoryFreshCount').textContent=h.fresh;
  if(document.getElementById('memorySoonCount')) document.getElementById('memorySoonCount').textContent=h.soon;
  if(document.getElementById('memoryDueCount')) document.getElementById('memoryDueCount').textContent=h.due;
  const note=document.getElementById('memoryHealthAdvice');
  if(note){
    if(!measured) note.textContent='問題演習をすると、問題ごとの記憶間隔を学習して復習日を調整します。';
    else if(h.due>0) note.innerHTML=`<b>${h.due}問が復習タイミングです。</b> 今日の復習では忘却リスクが高い順に出題します。`;
    else if(h.soon>0) note.innerHTML=`現在は安定しています。<b>${h.soon}問が近いうちに復習へ戻る見込み</b>です。`;
    else note.textContent='現在学習済みの問題はよく保持できています。新しい範囲を進めて構いません。';
  }
}
function renderReviewForecast(){
  const root=document.getElementById('reviewForecast');
  if(!root) return;
  const rows=reviewForecast(7);
  const max=Math.max(1,...rows.map(x=>x.count));
  const names=['日','月','火','水','木','金','土'];
  root.innerHTML=rows.map((x,i)=>{
    const d=parseLocalISO(x.date);
    const height=x.count?Math.max(10,Math.round(x.count/max*100)):4;
    return `<div class="forecast-day ${i===0?'today':''}">
      <div class="forecast-count">${x.count?x.count+'問':''}</div>
      <div class="forecast-bar-wrap"><div class="forecast-bar" style="height:${height}%"></div></div>
      <div class="forecast-label">${i===0?'今日':names[d.getDay()]}</div>
    </div>`;
  }).join('');
}
