function validateSubjectBSemantics(){

  const errors=[];
  const predPos=[0,0,0,0],compoundPos=[0,0,0,0],securityPos=[0,0,0,0],examPos=[0,0,0,0];

  if(B_EXERCISES.length!==20)errors.push('trace exercises must be 20');
  B_EXERCISES.forEach(ex=>{
    const preds=ex.steps.filter(s=>s.predict).map(s=>s.predict);
    if(preds.length!==2)errors.push(`${ex.id}: prediction count`);
    preds.forEach((p,i)=>{
      if(!Array.isArray(p.opts)||p.opts.length!==4||new Set(p.opts.map(String)).size!==4||
         !Number.isInteger(p.a)||p.a<0||p.a>=p.opts.length||!p.explain||!p.hint){
        errors.push(`${ex.id}:${i+1}: invalid prediction`);
      }else{
        predPos[p.a]++;
        if(B_PREDICTION_CONTRACTS[`${ex.id}:${i+1}`]!==String(p.opts[p.a])){
          errors.push(`${ex.id}:${i+1}: prediction semantic drift`);
        }
      }
    });
  });
  if(predPos.some(x=>x!==10))errors.push(`prediction answer-position bias: ${predPos.join('/')}`);

  if(B_COMPOUND_SETS.length!==15)errors.push('compound sets must be 15');
  B_COMPOUND_SETS.forEach(s=>{
    if(s.qs?.length!==3)errors.push(`${s.id}: compound q count`);
    s.qs?.forEach((q,i)=>{
      if(q.opts?.length!==4||new Set(q.opts).size!==4||q.a<0||q.a>3||!q.exp){
        errors.push(`${s.id}:${i+1}: invalid compound question`);
      }else{
        compoundPos[q.a]++;
        if(B_COMPOUND_CONTRACTS[`${s.id}:${i+1}`]!==q.opts[q.a]){
          errors.push(`${s.id}:${i+1}: compound semantic drift`);
        }
      }
    });
  });
  if(Math.max(...compoundPos)-Math.min(...compoundPos)>1){
    errors.push(`compound answer-position bias: ${compoundPos.join('/')}`);
  }

  if(SECURITY_SCENARIOS.length!==15)errors.push('security scenarios must be 15');
  if(SECURITY_SCENARIOS.filter(s=>s.log).length<4)errors.push('security log scenarios must be at least 4');
  const weakDistractor=/好きな|壁紙|プリンタ用紙|モニタ|CPUクロック|キーボード配列|背景色|ディスプレイ解像度|モニタ解像度/;
  SECURITY_SCENARIOS.forEach(s=>{
    if(s.steps?.length!==3)errors.push(`${s.id}: security step count`);
    const firstExpected=B_SECURITY_FIRST_STEP_CONTRACTS[s.id];
    if(!firstExpected||s.steps?.[0]?.options?.[s.steps[0].a]!==firstExpected){
      errors.push(`${s.id}: first security semantic drift`);
    }
    s.steps?.forEach((q,i)=>{
      if(q.options?.length!==4||new Set(q.options).size!==4||q.a<0||q.a>3||!q.explain){
        errors.push(`${s.id}:${i+1}: invalid security question`);
      }else{
        securityPos[q.a]++;
        if(B_SECURITY_STEP_CONTRACTS[`${s.id}:${i+1}`]!==q.options[q.a]){
          errors.push(`${s.id}:${i+1}: security semantic drift`);
        }
        if(q.options.some(x=>weakDistractor.test(String(x)))){
          errors.push(`${s.id}:${i+1}: trivial security distractor`);
        }
      }
    });
  });
  if(Math.max(...securityPos)-Math.min(...securityPos)>1){
    errors.push(`security answer-position bias: ${securityPos.join('/')}`);
  }

  if(B_EXAM_ALGO_ITEMS.length!==40)errors.push('exam algorithm pool must be 40');
  const domainCounts={},levelCounts={};
  B_EXAM_ALGO_ITEMS.forEach(q=>{
    domainCounts[q.domain]=(domainCounts[q.domain]||0)+1;
    levelCounts[q.level]=(levelCounts[q.level]||0)+1;
    if(q.options?.length!==4||new Set(q.options).size!==4||q.a<0||q.a>3||!q.explain||!q.code?.length){
      errors.push(`${q.id}: invalid exam item`);
    }else{
      examPos[q.a]++;
      if(B_EXAM_ALGO_CONTRACTS[q.id]!==String(q.options[q.a])){
        errors.push(`${q.id}: exam semantic drift`);
      }
    }
  });
  if(examPos.some(x=>x!==10))errors.push(`exam answer-position bias: ${examPos.join('/')}`);
  B_FINAL_ALGO_DOMAINS.forEach(d=>{
    if((domainCounts[d]||0)<3)errors.push(`${d}: insufficient exam pool`);
  });
  if((levelCounts['標準']||0)<18||(levelCounts['応用']||0)<20){
    errors.push(`exam level balance: 標準${levelCounts['標準']||0}/応用${levelCounts['応用']||0}`);
  }

  return {
    ok:errors.length===0,errors,domainCounts,levelCounts,
    answerPositions:{prediction:predPos,compound:compoundPos,security:securityPos,exam:examPos}
  };
}

function runLessonUXAudit(){
  const lessonIds=Object.keys(LESSONS||{});
  const pageCounts=Object.fromEntries(lessonIds.map(id=>[id,LESSONS[id].pages.length]));
  const interactiveTypes=lessonIds.flatMap(id=>LESSONS[id].pages.filter(p=>p.interactive).map(p=>p.interactive));
  const issues=[];
  if(lessonIds.length!==34)issues.push(`lesson count ${lessonIds.length}`);
  
  if(new Set(interactiveTypes).size!==interactiveTypes.length)issues.push('duplicate interactive type');
  const required=['transaction','mutex','filesystem','automata','cache','stackqueue'];
  required.forEach(x=>{if(!interactiveTypes.includes(x))issues.push(`missing ${x}`)});
  return {ok:issues.length===0,lessonCount:lessonIds.length,totalPages:Object.values(pageCounts).reduce((a,b)=>a+b,0),interactiveCount:interactiveTypes.length,issues};
}
window.FEQUEST_LESSON_UX_AUDIT=runLessonUXAudit();

