function revalidateProfileFreshness(reason='画面復帰'){
  if(profileWriteBlocked||profileConflictBlocked)return false;
  try{
    const atomic=currentAtomicProfile();
    if(!atomic)return true;
    const rev=nonNegativeInt(atomic.revision,0);
    const checksum=atomic.checksum||profileIntegrityChecksum(atomic.profile);
    const externalWriter=atomic.writerId!==TAB_INSTANCE_ID;
    const newer=rev>profileBaseRevision;
    const rewound=rev<profileBaseRevision;
    const sameRevisionChanged=rev===profileBaseRevision&&checksum!==profileCommittedChecksum;
    if((externalWriter&&newer)||rewound||sameRevisionChanged){
      restoreCommittedProfileInMemory(true);
      markProfileConflict(`${reason}時に、別の保存世代を検出しました`);
      return false;
    }
    return true;
  }catch(e){
    if(e?.code==='FUTURE_PROFILE_SCHEMA'){
      restoreCommittedProfileInMemory(true);profileWriteBlocked=true;profileRecoverySource='future';profileRecoveryReason=e?.message||String(e);
      showAppNotice?.('error','FE QUESTの更新が必要です','画面復帰時に、このアプリより新しい形式の学習データを検出しました。上書きを防ぐため保存を停止しています。','更新を確認',()=>checkForAppUpdate(true));
      return false;
    }
    restoreCommittedProfileInMemory(true);markProfileConflict(`${reason}時に保存データの整合性を確認できませんでした`);return false;
  }
}

function uiStateIsToday(state){
  const ts=Number(state?.updatedAt)||0;if(!ts)return false;
  const a=new Date(ts),b=new Date();
  return a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate();
}
function restoreResilientUiState(){
  restoringUiState=true;
  try{
    if(restoreBFinalResume()){
      appHistoryReplace('trace',0);
      setTimeout(()=>showAppNotice?.('info','総合実戦を再開しました','再読み込み前の回答と残り時間から続けています。'),30);
      return 'bfinal';
    }
    const state=readUiState();
    if(!uiStateIsToday(state)){
      showScreen('home',{noHistory:true,instant:true});
      appHistoryReplace('home',0);
      return 'home';
    }
    if(state.screen==='lesson'&&state.lessonId&&LESSONS[state.lessonId]){
      activeLesson=state.lessonId;
      lessonStep=Math.max(0,Math.min(LESSONS[activeLesson].pages.length-1,Number(state.lessonStep)||0));
      lessonCompleteMode=false;
      resetLessonState();
      showScreen('lesson',{noHistory:true,instant:true});
      renderLesson();
      appHistoryReplace('lesson',0);
      return 'lesson';
    }
    const target=SAFE_RESUME_SCREENS.has(state.screen)?state.screen:'home';
    showScreen(target,{noHistory:true,instant:true});
    if(target==='problems')openProblemsHub();
    appHistoryReplace(target,0);
    return target;
  }finally{
    restoringUiState=false;
  }
}
