function showAppNotice(kind,title,body,actionLabel='',action=null){
  if(!appNotice)return;
  appNotice.className=`app-notice show ${kind||''}`;
  appNoticeIcon.textContent=kind==='update'?'⬆️':kind==='error'?'⚠️':kind==='offline'?'📴':'ℹ️';
  appNoticeTitle.textContent=title;
  appNoticeBody.textContent=body;
  if(actionLabel&&action){
    appNoticeAction.style.display='';appNoticeAction.textContent=actionLabel;
    appNoticeAction.onclick=()=>{
      hideAppNotice();
      try{action()}catch(e){console.warn('Notice action failed',e);setTimeout(()=>reportGlobalError?.(),0)}
    };
  }else{
    appNoticeAction.style.display='none';appNoticeAction.onclick=null;
  }
}
