function openPwaGuide(){
  if(!pwaModal)return;
  pwaReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;
  pwaModal.classList.add('open');pwaModal.setAttribute('aria-hidden','false');
  requestAnimationFrame(()=>closePwaModal?.focus({preventScroll:true}));
}
function closePwaGuide(){
  if(!pwaModal)return;
  pwaModal.classList.remove('open');pwaModal.setAttribute('aria-hidden','true');
  const target=pwaReturnFocus;pwaReturnFocus=null;requestAnimationFrame(()=>target?.focus?.({preventScroll:true}));
}
installPwaBtn?.addEventListener('click',async()=>{
  if(deferredInstallPrompt){
    deferredInstallPrompt.prompt();
    await deferredInstallPrompt.userChoice;
    deferredInstallPrompt=null;refreshInstallCard();return;
  }
  openPwaGuide();
});
closePwaModal?.addEventListener('click',closePwaGuide);
pwaModal?.addEventListener('click',e=>{if(e.target===pwaModal)closePwaGuide()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&pwaModal?.classList.contains('open')){e.preventDefault();closePwaGuide();}});

function updateOnlineState(showTransition=true){
  const online=navigator.onLine;
  offlinePill?.classList.toggle('show',!online);
  if(showTransition&&previousOnlineState!==online){
    if(online){popToast('オンラインに戻りました');checkForAppUpdate(false)}
    else showAppNotice('offline','オフラインで利用中','教材と学習データはこの端末から利用できます。接続が戻ると更新確認を行います。');
  }
  previousOnlineState=online;
  refreshPwaHealth();
}
window.addEventListener('online',()=>updateOnlineState(true));
window.addEventListener('offline',()=>updateOnlineState(true));
updateOnlineState(false);

function activatePendingUpdateOrReload(){
  // v116: updating is always a one-tap operation.  A blocked/conflicting screen has
  // already rolled in-memory data back to the last committed snapshot, so it must
  // not ask the learner to manually export/reload before installing a safer runtime.
  persistResilientUiState();
  const worker=pendingUpdateRegistration?.waiting;
  if(worker)worker.postMessage({type:'SKIP_WAITING'});
  else location.reload();
  return true;
}
async function applyPendingUpdateSafely(){
  // If this tab is stale, conflicted, or write-blocked, do not write from it.
  // Simply activate the waiting app and let the new runtime load the authoritative
  // committed profile. This avoids the previous manual reload/export loop.
  if(profileConflictBlocked||profileWriteBlocked){
    return activatePendingUpdateOrReload();
  }
  const saved=persistProfileSilently();
  if(!saved){
    // persistProfileSilently rolls the profile back to the committed snapshot on
    // failure/conflict.  Proceeding with the app update is therefore safer than
    // trapping the learner in a recovery workflow.
    return activatePendingUpdateOrReload();
  }
  try{await Promise.race([writeRecoveryCheckpoint(profile,'pre-update',true),new Promise(resolve=>setTimeout(()=>resolve(false),1800))]);}catch(_e){}
  return activatePendingUpdateOrReload();
}
function showUpdateAvailable(reg){
  pendingUpdateRegistration=reg;
  showAppNotice('update','FE QUESTを更新できます','学習データを保護して、自動で最新版へ切り替えます。','今すぐ更新',()=>applyPendingUpdateSafely());
  refreshPwaHealth();
}

async function checkForAppUpdate(showResult=true){
  if(!swRegistration){if(showResult)popToast('更新確認の準備中です');return false;}
  try{
    lastUpdateCheck=Date.now();
    await swRegistration.update();
    if(swRegistration.waiting){showUpdateAvailable(swRegistration);return true;}
    if(showResult)popToast('最新版です');
    refreshPwaHealth();return false;
  }catch(e){
    console.warn('Update check failed',e);
    if(showResult)showAppNotice('error','更新を確認できませんでした','通信状態を確認して、もう一度お試しください。');
    return false;
  }
}

if('serviceWorker' in navigator){
  navigator.serviceWorker.addEventListener('message',e=>{
    if(e.data?.type!=='APP_VERSION')return;
    serviceWorkerVersion=e.data.version||null;
    if(serviceWorkerVersion && serviceWorkerVersion!==APP_VERSION){
      showAppNotice('update','アプリ更新が必要です',`画面は${APP_VERSION}、オフライン用データは${serviceWorkerVersion}です。更新してそろえてください。`,'更新を確認',()=>checkForAppUpdate(true));
    }
    refreshPwaHealth();
  });
}
function requestServiceWorkerVersion(){
  navigator.serviceWorker?.controller?.postMessage?.({type:'GET_VERSION'});
}

if('serviceWorker' in navigator&&location.protocol!=='file:'){
  window.addEventListener('load',async()=>{
    try{
      const reg=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});
      swRegistration=reg;
      if(reg.waiting)showUpdateAvailable(reg);
      reg.addEventListener('updatefound',()=>{
        const worker=reg.installing;if(!worker)return;
        worker.addEventListener('statechange',()=>{
          if(worker.state==='installed'&&navigator.serviceWorker.controller)showUpdateAvailable(reg);
          refreshPwaHealth();
        });
      });
      refreshPwaHealth();
      requestServiceWorkerVersion();
      setTimeout(()=>checkForAppUpdate(false),1200);
    }catch(err){
      console.warn('Service Worker registration failed:',err);
      showAppNotice('error','オフライン準備に失敗しました','オンラインでは利用できますが、オフライン起動の準備ができませんでした。再読み込みすると改善する場合があります。','再読み込み',()=>location.reload());
      refreshPwaHealth();
    }
  });
  navigator.serviceWorker.addEventListener('controllerchange',()=>{
    if(controllerReloading)return;controllerReloading=true;persistResilientUiState();location.reload();
  });
}

function maybeCheckUpdate(){
  if(document.visibilityState==='visible'&&navigator.onLine&&Date.now()-lastUpdateCheck>5*60*1000)checkForAppUpdate(false);
}
window.addEventListener('focus',()=>{revalidateProfileFreshness('フォーカス復帰');maybeCheckUpdate()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')revalidateProfileFreshness('画面復帰');maybeCheckUpdate()});
window.addEventListener('pageshow',e=>{revalidateProfileFreshness(e.persisted?'休止状態からの復帰':'画面表示');updateOnlineState(false);refreshPwaHealth()});

function bytesText(n){
  if(!Number.isFinite(n))return '不明';
  if(n<1024)return `${n} B`;
  if(n<1024*1024)return `${(n/1024).toFixed(1)} KB`;
  return `${(n/1024/1024).toFixed(1)} MB`;
}
function quickProfileIntegrityState(){
  try{
    const a=currentAtomicProfile();
    if(!a)return {ok:false,label:'初回保存前'};
    const mirror=localStorage.getItem(STORAGE_KEY);
    const expected=localStorage.getItem(PROFILE_CHECKSUM_KEY);
    if(!mirror)return {ok:false,label:'ミラー未作成'};
    const checked=validRawWithChecksum(mirror,expected||null);
    if(profileIntegrityChecksum(checked.profile)!==profileIntegrityChecksum(a.profile))return {ok:false,label:'ミラー差異'};
    return {ok:true,label:'正常'};
  }catch(e){return {ok:false,label:'要確認',error:e};}
}
async function verifyProfileDurability(showResult=true){
  if(profileRecoverySource==='future'){
    if(showResult)showAppNotice('error','最新版への更新が必要です','保存データはこの画面より新しい形式です。古い画面では検査や修復を行わず、最新版へ更新してから確認してください。','更新を確認',()=>checkForAppUpdate(true));
    return false;
  }
  const quick=quickProfileIntegrityState();
  let points=0;try{points=await recoveryCheckpointCount()}catch(_e){}
  if(quick.ok){
    if(showResult)showAppNotice('info','学習データは正常です',`原子的な現在データと互換ミラーの整合性を確認しました。長期復旧点は${points}件あります。${localStorage.getItem(LAST_GOOD_PROFILE_KEY)?'一世代前の正常データも保持しています。':'一世代前のデータは次回保存以降に作成されます。'}`);
    return true;
  }
  if(showResult)showAppNotice('error','学習データを確認してください',`整合性確認結果：${quick.label}。現在の確定データは自動復旧機構で保護されていますが、念のため外部バックアップを書き出してください。`,'データを書き出す',exportLearningData);
  return false;
}
async function createRecoveryPointNow(){
  if(profileWriteBlocked||profileConflictBlocked){showAppNotice('error','復旧点を作成できません','保存が停止している画面では新しい復旧点を作りません。最新状態を読み込むか、保存状態を確認してください。');return false;}
  if(!persistProfileSilently()){showAppNotice('error','復旧点を作成できません','現在の学習データを正常保存できなかったため、復旧点作成を中止しました。');return false;}
  try{const ok=await writeRecoveryCheckpoint(profile,'manual',true);if(ok){popToast('長期復旧点を作成しました');refreshPwaHealth();return true;}throw new Error('checkpoint unavailable');}
  catch(e){showAppNotice('error','復旧点を作成できませんでした','ブラウザの保存領域やIndexedDBの利用状態を確認してください。');return false;}
}
async function ensureVersionRecoveryCheckpoint(){
  try{
    if(localStorage.getItem(PROFILE_VERSION_CHECKPOINT_KEY)===APP_VERSION)return false;
    if(profileWriteBlocked||profileConflictBlocked)return false;
    const ok=await writeRecoveryCheckpoint(profile,`version-${APP_VERSION}`,true);
    if(ok){localStorage.setItem(PROFILE_VERSION_CHECKPOINT_KEY,APP_VERSION);refreshPwaHealth();return true;}
  }catch(e){console.warn('Version recovery checkpoint failed',e)}
  return false;
}

async function refreshPwaHealth(){
  const v=document.getElementById('pwaVersionStatus'),net=document.getElementById('pwaNetworkStatus'),disp=document.getElementById('pwaDisplayStatus'),worker=document.getElementById('pwaWorkerStatus'),storage=document.getElementById('pwaStorageStatus'),bar=document.getElementById('pwaStorageBar'),persist=document.getElementById('pwaPersistenceStatus'),persistBtn=document.getElementById('requestPersistentStorage');
  const schema=document.getElementById('profileSchemaStatus'),snapshot=document.getElementById('profileSnapshotStatus'),rollback=document.getElementById('restorePreImport'),manualRollback=document.getElementById('restorePreManual'),corruptExport=document.getElementById('exportCorruptProfile'),saveState=document.getElementById('profileSaveStatus'),integrity=document.getElementById('profileIntegrityStatus'),exportState=document.getElementById('profileExportStatus');
  if(v){const mismatch=serviceWorkerVersion&&serviceWorkerVersion!==APP_VERSION;v.textContent=mismatch?`${APP_VERSION}・更新必要`:pendingUpdateRegistration?.waiting?`${APP_VERSION}・更新あり`:APP_VERSION;v.className=(mismatch||pendingUpdateRegistration?.waiting)?'warn':'good'}
  if(net){net.textContent=navigator.onLine?'オンライン':'オフライン';net.className=navigator.onLine?'good':'warn'}
  if(disp){disp.textContent=isStandalone()?'ホーム画面アプリ':'ブラウザ';disp.className=isStandalone()?'good':''}
  if(worker){
    const controlled=!!navigator.serviceWorker?.controller;
    worker.textContent=controlled?'準備完了':('serviceWorker'in navigator?'準備中':'非対応');worker.className=controlled?'good':'warn';
  }
  if(schema){
    if(profileRecoverySource==='future'){schema.textContent='更新が必要';schema.className='warn';}
    else{schema.textContent=`v${profile.profileSchemaVersion||PROFILE_SCHEMA_VERSION}`;schema.className=(profile.profileSchemaVersion===PROFILE_SCHEMA_VERSION)?'good':'warn';}
  }
  if(saveState){
    if(profileConflictBlocked){saveState.textContent='別画面を検出・停止';saveState.className='warn';}
    else if(profileWriteBlocked){saveState.textContent='保存停止';saveState.className='warn';}
    else{
      try{const a=currentAtomicProfile();const t=a?JSON.parse(localStorage.getItem(PROFILE_ATOMIC_KEY)).savedAt:null;saveState.textContent=a?`r${a.revision}・${t?new Date(t).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'}):'保存済み'}`:'初回保存前';saveState.className=a?'good':'warn';}catch(_e){saveState.textContent='要確認';saveState.className='warn';}
    }
  }
  if(integrity){
    const quick=quickProfileIntegrityState();integrity.textContent=quick.ok?'正常':quick.label;integrity.className=quick.ok?'good':'warn';
  }
  if(exportState){
    const raw=localStorage.getItem(PROFILE_LAST_EXPORT_KEY),at=Date.parse(raw||'');
    if(!Number.isFinite(at)){exportState.textContent='未作成';exportState.className='warn';}
    else{const days=Math.floor((Date.now()-at)/86400000);exportState.textContent=days<=0?'今日':`${days}日前`;exportState.className=days<=14?'good':'warn';}
  }
  if(snapshot){
    const localOk=!!localStorage.getItem(LAST_GOOD_PROFILE_KEY);
    const n=await recoveryCheckpointCount();
    snapshot.textContent=localOk?(n?`2段保護＋復旧点${n}`:'2段保護'):(n?`復旧点${n}`:'未作成');
    snapshot.className=(localOk||n>0)?'good':'warn';
  }
  if(rollback){
    rollback.classList.toggle('hidden',!localStorage.getItem(PRE_IMPORT_PROFILE_KEY));
  }
  if(manualRollback)manualRollback.classList.toggle('hidden',!localStorage.getItem(PRE_MANUAL_RESTORE_PROFILE_KEY));
  if(corruptExport)corruptExport.classList.toggle('hidden',!localStorage.getItem(CORRUPT_PROFILE_KEY));
  if(persist){
    if(navigator.storage?.persisted){
      try{const granted=await navigator.storage.persisted();persist.textContent=granted?'永続化済み':'標準保護';persist.className=granted?'good':'warn';if(persistBtn)persistBtn.classList.toggle('hidden',granted||!navigator.storage?.persist)}catch(_e){persist.textContent='確認できませんでした'}
    }else{persist.textContent='この環境では取得不可';if(persistBtn)persistBtn.classList.add('hidden')}
  }
  if(storage&&navigator.storage?.estimate){
    try{
      const x=await navigator.storage.estimate(),usage=x.usage||0,quota=x.quota||0,pct=quota?Math.min(100,usage/quota*100):0;
      storage.textContent=`${bytesText(usage)} 使用 / ${bytesText(quota)}`;
      storage.className=pct>=80?'warn':'good';if(bar)bar.style.width=`${pct}%`;
      if(pct>=90&&!storagePressureNoticeShown){storagePressureNoticeShown=true;setTimeout(()=>showAppNotice?.('error','保存領域が少なくなっています','学習データ本体を優先するため、通常の長期復旧点の追加を抑えます。念のため学習データを書き出してください。','データを書き出す',exportLearningData),0)}
    }catch(e){storage.textContent='取得できませんでした'}
  }else if(storage){storage.textContent='この環境では取得不可'}
}

function stableJson(value){
  if(value===undefined||typeof value==='function'||typeof value==='symbol')return undefined;
  if(value===null||typeof value!=='object')return JSON.stringify(value);
  if(Array.isArray(value))return '['+value.map(v=>stableJson(v)??'null').join(',')+']';
  const parts=[];
  Object.keys(value).sort().forEach(k=>{
    const encoded=stableJson(value[k]);
    if(encoded!==undefined)parts.push(JSON.stringify(k)+':'+encoded);
  });
  return '{'+parts.join(',')+'}';
}
function fnv1a32(text){
  let h=0x811c9dc5;
  for(let i=0;i<text.length;i++){
    h^=text.charCodeAt(i);
    h=Math.imul(h,0x01000193);
  }
  return (h>>>0).toString(16).padStart(8,'0');
}
function profileIntegrityChecksum(p){
  return `fnv1a32:${fnv1a32(stableJson(normalizeProfileData(p)))}`;
}

function openRecoveryDb(){
  if(typeof indexedDB==='undefined')return Promise.reject(new Error('IndexedDB unsupported'));
  return new Promise((resolve,reject)=>{
    const req=indexedDB.open(RECOVERY_DB_NAME,RECOVERY_DB_VERSION);
    req.onupgradeneeded=()=>{
      const db=req.result;
      if(!db.objectStoreNames.contains(RECOVERY_DB_STORE))db.createObjectStore(RECOVERY_DB_STORE,{keyPath:'id'});
    };
    req.onsuccess=()=>resolve(req.result);
    req.onerror=()=>reject(req.error||new Error('IndexedDB open failed'));
  });
}
function idbRequest(req){
  return new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('IndexedDB request failed'));});
}
async function recoverySnapshots(){
  const db=await openRecoveryDb();
  try{
    const tx=db.transaction(RECOVERY_DB_STORE,'readonly');
    const rows=await idbRequest(tx.objectStore(RECOVERY_DB_STORE).getAll());
    return (rows||[]).sort((a,b)=>(b.id||0)-(a.id||0));
  }finally{db.close();}
}
async function recoveryCheckpointCount(){
  if(typeof indexedDB==='undefined')return 0;
  try{return (await recoverySnapshots()).length}catch(e){return 0}
}
async function storagePressureRatio(){
  if(!navigator.storage?.estimate)return 0;
  try{const x=await navigator.storage.estimate(),u=x.usage||0,q=x.quota||0;return q?u/q:0}catch(_e){return 0}
}
async function writeRecoveryCheckpoint(p=profile,reason='autosave',force=false){
  if(typeof indexedDB==='undefined'||profileWriteBlocked||profileConflictBlocked)return false;
  const now=Date.now();
  if(!force&&now-recoveryCheckpointLastAt<RECOVERY_CHECKPOINT_INTERVAL)return false;
  if(!force&&(await storagePressureRatio())>=0.90)return false;
  recoveryCheckpointLastAt=now;
  const payload=makeBackupPayload(p);
  const db=await openRecoveryDb();
  try{
    await new Promise((resolve,reject)=>{
      const tx=db.transaction(RECOVERY_DB_STORE,'readwrite');
      const store=tx.objectStore(RECOVERY_DB_STORE);
      store.put({id:now,createdAt:new Date(now).toISOString(),reason,appVersion:APP_VERSION,profileSchemaVersion:PROFILE_SCHEMA_VERSION,payload});
      tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('IndexedDB write failed'));tx.onabort=()=>reject(tx.error||new Error('IndexedDB write aborted'));
    });
    const rows=await recoverySnapshots();
    if(rows.length>RECOVERY_MAX_SNAPSHOTS){
      const db2=await openRecoveryDb();
      try{
        await new Promise((resolve,reject)=>{
          const tx=db2.transaction(RECOVERY_DB_STORE,'readwrite'),store=tx.objectStore(RECOVERY_DB_STORE);
          rows.slice(RECOVERY_MAX_SNAPSHOTS).forEach(x=>store.delete(x.id));
          tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('IndexedDB trim failed'));
        });
      }finally{db2.close();}
    }
    return true;
  }finally{db.close();}
}
function queueRecoveryCheckpoint(reason='autosave',force=false){
  if(profileWriteBlocked||profileConflictBlocked||typeof indexedDB==='undefined')return;
  const now=Date.now();
  if(!force&&now-recoveryCheckpointLastAt<RECOVERY_CHECKPOINT_INTERVAL)return;
  setTimeout(()=>writeRecoveryCheckpoint(profile,reason,force).then(ok=>{if(ok)refreshPwaHealth?.();}).catch(e=>console.warn('Recovery checkpoint failed',e)),0);
}
async function recoverLatestIndexedDbCheckpoint(){
  if(typeof indexedDB==='undefined')return false;
  let rows=[];
  try{rows=await recoverySnapshots()}catch(e){return false}
  for(const row of rows){
    try{
      const decoded=decodeBackupPayload(row.payload);
      profileWriteBlocked=false;
      profileRecoveryNeedsIndexedDb=false;
      profile=stampProfileForSave(decoded.profile);
      const result=writeCurrentProfile(profile,{preservePrevious:false,skipConflictCheck:true});
      profile=result.profile;rememberCommittedProfile(profile);
      localStorage.setItem(LAST_GOOD_PROFILE_KEY,result.raw);
      localStorage.setItem(LAST_GOOD_CHECKSUM_KEY,result.checksum);
      profileRecoverySource='indexeddb';
      return true;
    }catch(e){console.warn('Skipped invalid recovery checkpoint',e)}
  }
  return false;
}
function makeBackupPayload(p=profile){
  const normalized=normalizeProfileData(p);
  return {
    format:'fequest-backup-v2',
    appVersion:APP_VERSION,
    profileSchemaVersion:PROFILE_SCHEMA_VERSION,
    exportedAt:new Date().toISOString(),
    checksum:profileIntegrityChecksum(normalized),
    profile:normalized
  };
}
function validateImportedProfile(candidate){
  return isPlainObject(candidate)&&(isPlainObject(candidate.skills)||Number.isFinite(Number(candidate.xp))||isPlainObject(candidate.lessonProgress));
}
function decodeBackupPayload(parsed){
  if(!isPlainObject(parsed))throw new Error('バックアップの形式が一致しません');
  const candidate=isPlainObject(parsed.profile)?parsed.profile:parsed;
  if(!validateImportedProfile(candidate))throw new Error('学習データとして認識できません');

  const schema=nonNegativeInt(parsed.profileSchemaVersion??candidate.profileSchemaVersion??1,1);
  if(schema>PROFILE_SCHEMA_VERSION)throw new Error('このバックアップは、より新しいFE QUESTで作成されています');

  if(parsed.format==='fequest-backup-v2'){
    if(typeof parsed.checksum!=='string')throw new Error('整合性情報がありません');
    const actual=schema===3?profileIntegrityChecksumV3(candidate):schema===4?profileIntegrityChecksumV4(candidate):profileIntegrityChecksum(candidate);
    if(actual!==parsed.checksum)throw new Error('整合性チェックに失敗しました。ファイルが破損または変更されています');
  }else if(parsed.format && parsed.format!=='fequest-backup-v1'){
    throw new Error('未対応のバックアップ形式です');
  }

  return {
    profile:normalizeProfileData(candidate),
    sourceFormat:parsed.format||'legacy-profile',
    appVersion:typeof parsed.appVersion==='string'?parsed.appVersion:'旧形式',
    exportedAt:typeof parsed.exportedAt==='string'?parsed.exportedAt:null,
    sourceSchema:schema
  };
}
function backupSummary(decoded){
  const p=decoded.profile;
  const lessonDone=Object.values(p.lessonProgress||{}).filter(x=>Number(x)>=100).length;
  const bDone=Object.values(p.bProgress||{}).filter(x=>Number(x)>=100).length;
  const secDone=Object.values(p.securityBProgress||{}).filter(x=>Number(x)>=100).length;
  const when=decoded.exportedAt?new Date(decoded.exportedAt).toLocaleString('ja-JP'):'日時情報なし';
  return `作成元：${decoded.appVersion}\n作成日時：${when}\nXP：${p.xp.toLocaleString('ja-JP')}\n科目A完了：${lessonDone}テーマ\n科目B：トレース${bDone}・セキュリティ${secDone}`;
}

function recoveryProfileMetrics(p){
  const qStats=safeObject(p?.qStats);
  const attempted=Object.values(qStats).filter(x=>nonNegativeInt(x?.attempts,0)>0).length;
  const answered=Object.values(qStats).reduce((n,x)=>n+nonNegativeInt(x?.attempts,0),0);
  const lessonDone=Object.values(safeObject(p?.lessonProgress)).filter(x=>Number(x)>=100).length;
  const bDone=Object.values(safeObject(p?.bProgress)).filter(x=>Number(x)>=100).length;
  const secDone=Object.values(safeObject(p?.securityBProgress)).filter(x=>Number(x)>=100).length;
  return {xp:nonNegativeInt(p?.xp,0),lessonDone,bDone,secDone,attempted,answered};
}
function recoveryMetricsText(p){
  const m=recoveryProfileMetrics(p);
  return `XP ${m.xp.toLocaleString('ja-JP')}・科目A完了 ${m.lessonDone}・演習済み ${m.attempted}問・科目B ${m.bDone}/${m.secDone}`;
}
function recoveryReasonText(reason=''){
  if(reason==='manual')return '手動作成';
  if(reason==='autosave')return '自動保護';
  if(reason==='pre-update')return 'アプリ更新前';
  if(reason==='pre-import')return 'バックアップ読込前';
  if(reason==='import')return 'バックアップ読込後';
  if(reason==='pre-import-restore')return '読込前データへの復帰後';
  if(reason==='pre-manual-restore')return '手動復元前';
  if(reason==='manual-restore')return '手動復元後';
  if(reason==='manual-restore-undo')return '手動復元の取消後';
  if(String(reason).startsWith('version-'))return `${String(reason).slice(8)}初回`;
  return reason||'自動保護';
}
function recoveryCandidateDateText(value){
  const t=Date.parse(value||'');
  return Number.isFinite(t)?new Date(t).toLocaleString('ja-JP'):'日時不明';
}
function downloadTextFile(name,text,type='application/json'){
  const blob=new Blob([text],{type});
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}
async function recoveryCandidates(){
  const items=[];
  const lastRaw=localStorage.getItem(LAST_GOOD_PROFILE_KEY);
  if(lastRaw){
    try{
      const checked=validRawWithChecksum(lastRaw,localStorage.getItem(LAST_GOOD_CHECKSUM_KEY)||null);
      items.push({kind:'last-good',id:'last-good',label:'一世代前の正常データ',createdAt:checked.profile.profileMeta?.updatedAt||null,reason:'一世代前',profile:checked.profile,valid:true});
    }catch(e){items.push({kind:'last-good',id:'last-good',label:'一世代前のデータ',createdAt:null,reason:'一世代前',valid:false,error:e?.message||String(e)})}
  }
  if(typeof indexedDB!=='undefined'){
    let rows=[];try{rows=await recoverySnapshots()}catch(e){rows=[]}
    for(const row of rows){
      try{
        const decoded=decodeBackupPayload(row.payload);
        items.push({kind:'idb',id:row.id,label:recoveryReasonText(row.reason),createdAt:row.createdAt||decoded.exportedAt,reason:row.reason,profile:decoded.profile,valid:true});
      }catch(e){items.push({kind:'idb',id:row.id,label:recoveryReasonText(row.reason),createdAt:row.createdAt,reason:row.reason,valid:false,error:e?.message||String(e)})}
    }
  }
  return items;
}
async function getRecoveryCandidate(kind,id){
  if(kind==='last-good'){
    const raw=localStorage.getItem(LAST_GOOD_PROFILE_KEY);if(!raw)throw new Error('一世代前のデータがありません');
    return validRawWithChecksum(raw,localStorage.getItem(LAST_GOOD_CHECKSUM_KEY)||null).profile;
  }
  const rows=await recoverySnapshots();
  const row=rows.find(x=>String(x.id)===String(id));if(!row)throw new Error('復旧点が見つかりません');
  return decodeBackupPayload(row.payload).profile;
}
async function renderRecoveryCenter(){
  const list=document.getElementById('recoveryPointList'),status=document.getElementById('recoveryCenterStatus'),undo=document.getElementById('restorePreManual'),corrupt=document.getElementById('exportCorruptProfile');
  if(!list||!status)return;
  if(undo)undo.classList.toggle('hidden',!localStorage.getItem(PRE_MANUAL_RESTORE_PROFILE_KEY));
  if(corrupt)corrupt.classList.toggle('hidden',!localStorage.getItem(CORRUPT_PROFILE_KEY));
  list.replaceChildren();
  if(profileRecoverySource==='future'){
    status.textContent='保存データがこの画面より新しい形式です。復旧操作はせず、先にFE QUESTを更新してください。';status.className='recovery-center-status warn';return;
  }
  const items=await recoveryCandidates();
  const valid=items.filter(x=>x.valid);
  const currentChecksum=profileIntegrityChecksum(profile);
  const restorable=valid.filter(x=>profileIntegrityChecksum(x.profile)!==currentChecksum);
  status.textContent=restorable.length?`現在：${recoveryMetricsText(profile)}。戻せる過去データが${restorable.length}件あります。通常時は復元する必要はありません。`:'現在と異なる復旧候補はありません。現在データが正常なら、そのまま利用できます。';
  status.className=`recovery-center-status ${valid.length?'good':''}`;
  items.forEach(item=>{
    const same=item.valid&&profileIntegrityChecksum(item.profile)===currentChecksum;
    const row=document.createElement('div');row.className=`recovery-row${item.valid?'':' invalid'}`;
    const copy=document.createElement('div');copy.className='recovery-row-copy';
    const title=document.createElement('b');title.textContent=`${item.label}・${recoveryCandidateDateText(item.createdAt)}`;
    const sub=document.createElement('span');sub.textContent=item.valid?(same?`現在と同じ・${recoveryMetricsText(item.profile)}`:recoveryMetricsText(item.profile)):`使用できません：${item.error||'整合性エラー'}`;
    copy.append(title,sub);row.append(copy);
    if(item.valid&&!same){const btn=document.createElement('button');btn.textContent='この状態を確認・復元';btn.addEventListener('click',()=>restoreRecoveryCandidate(item.kind,item.id,item.label));row.append(btn)}
    list.append(row);
  });
}
async function restoreRecoveryCandidate(kind,id,label='復旧点'){
  if(profileRecoverySource==='future'){showAppNotice('error','先にFE QUESTを更新してください','新しい形式の保存データを古い画面から変更しないよう、復旧操作を停止しています。','更新を確認',()=>checkForAppUpdate(true));return false}
  if(profileWriteBlocked||profileConflictBlocked){showAppNotice('error','この画面からは復元できません','保存が停止しているか、別の画面で新しい学習データがあります。最新状態を読み込んでから復旧センターを開いてください。','最新状態を読み込む',()=>location.reload());return false}
  let candidate;try{candidate=await getRecoveryCandidate(kind,id)}catch(e){showAppNotice('error','復旧点を読み取れませんでした',e?.message||'復旧点の整合性を確認できませんでした。');renderRecoveryCenter();return false}
  const currentText=recoveryMetricsText(profile),candidateText=recoveryMetricsText(candidate);
  if(!confirm(`${label}へ戻しますか？

現在：${currentText}
復元先：${candidateText}

現在の状態は「直前の手動復元前」として1回分退避します。`))return false;
  if(!persistProfileSilently()){showAppNotice('error','復元を開始できません','現在の学習データを正常保存できなかったため、復元を中止しました。');return false}
  if(!acquireProfileWriteLease()){markProfileConflict('別のFE QUEST画面がいま学習データを書き込んでいます');return false}
  try{
    assertNoExternalProfileConflict();
    localStorage.setItem(PRE_MANUAL_RESTORE_PROFILE_KEY,JSON.stringify(makeBackupPayload(profile)));
    try{await Promise.race([writeRecoveryCheckpoint(profile,'pre-manual-restore',true),new Promise(resolve=>setTimeout(()=>resolve(false),1800))])}catch(_e){}
    profile=stampProfileForSave(candidate);
    const result=writeCurrentProfile(profile,{preservePrevious:true});profile=result.profile;rememberCommittedProfile(profile);
    localStorage.removeItem('fequest_bfinal_resume_v1');localStorage.removeItem('fequest_ui_state_v2');
    popToast('選んだ復旧点へ戻しました');setTimeout(()=>location.reload(),500);return true;
  }catch(e){
    restoreCommittedProfileInMemory(true);noteProfileSaveFailure(e);
    if(e?.code==='PROFILE_REVISION_CONFLICT')markProfileConflict();else showAppNotice('error','復元できませんでした','現在のデータは変更していません。保存状態を確認してもう一度お試しください。');
    return false;
  }finally{releaseProfileWriteLease()}
}
async function restorePreManualProfile(){
  const raw=localStorage.getItem(PRE_MANUAL_RESTORE_PROFILE_KEY);if(!raw){popToast('戻せる手動復元前データはありません');return false}
  if(profileWriteBlocked||profileConflictBlocked){showAppNotice('error','この画面からは戻せません','最新状態を読み込んでから操作してください。','最新状態を読み込む',()=>location.reload());return false}
  try{
    const decoded=decodeBackupPayload(JSON.parse(raw));
    if(!confirm(`直前の手動復元を取り消しますか？

戻り先：${recoveryMetricsText(decoded.profile)}`))return false;
    if(!acquireProfileWriteLease()){markProfileConflict();return false}
    try{
      assertNoExternalProfileConflict();
      profile=stampProfileForSave(decoded.profile);const result=writeCurrentProfile(profile,{preservePrevious:true});profile=result.profile;rememberCommittedProfile(profile);
      localStorage.removeItem(PRE_MANUAL_RESTORE_PROFILE_KEY);
      localStorage.removeItem('fequest_bfinal_resume_v1');localStorage.removeItem('fequest_ui_state_v2');
      popToast('手動復元前の状態へ戻しました');setTimeout(()=>location.reload(),500);return true;
    }finally{releaseProfileWriteLease()}
  }catch(e){showAppNotice('error','復元前の状態へ戻せませんでした',e?.message||'退避データの整合性を確認できませんでした。');return false}
}
async function runStorageSelfTest(){
  const status=document.getElementById('recoveryCenterStatus');if(status){status.textContent='安全性チェックを実行しています…';status.className='recovery-center-status'}
  const tests=[];
  const push=(name,ok,detail='')=>tests.push({name,ok,detail});
  const quick=quickProfileIntegrityState(),currentOk=quick.ok||quick.label==='初回保存前';push('現在データの整合性',currentOk,quick.label);
  try{
    const key=`fequest_probe_${Date.now()}`,value=`ok-${Math.random()}`;localStorage.setItem(key,value);const ok=localStorage.getItem(key)===value;localStorage.removeItem(key);push('ブラウザ内の基本保存',ok,ok?'書込・読込・削除OK':'読込値が一致しません');
  }catch(e){push('ブラウザ内の基本保存',false,e?.name||e?.message||'保存不可')}
  if(typeof indexedDB==='undefined')push('長期復旧領域',false,'IndexedDB非対応');
  else{
    const dbName=`fequest-selftest-${Date.now()}`;
    try{
      const db=await new Promise((resolve,reject)=>{const r=indexedDB.open(dbName,1);r.onupgradeneeded=()=>r.result.createObjectStore('probe');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
      const wrote=await new Promise((resolve,reject)=>{const tx=db.transaction('probe','readwrite'),st=tx.objectStore('probe');st.put('ok','k');tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error)});
      const read=await new Promise((resolve,reject)=>{const tx=db.transaction('probe','readonly'),r=tx.objectStore('probe').get('k');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
      db.close();indexedDB.deleteDatabase(dbName);push('長期復旧領域',wrote&&read==='ok','書込・読込OK');
    }catch(e){try{indexedDB.deleteDatabase(dbName)}catch(_e){}push('長期復旧領域',false,e?.name||e?.message||'利用不可')}
  }
  const swSupported='serviceWorker'in navigator;push('オフライン用データ',!swSupported||!!navigator.serviceWorker.controller,swSupported?(navigator.serviceWorker.controller?'制御中':'まだ準備中'):'この環境では非対応');
  const critical=tests.slice(0,3),passed=critical.filter(x=>x.ok).length;
  const lines=tests.map(x=>`${x.ok?'✓':'×'} ${x.name}${x.detail?`：${x.detail}`:''}`);
  if(status){status.textContent=`安全性チェック ${passed}/${critical.length}：${lines.join(' ／ ')}`;status.className=`recovery-center-status ${passed===critical.length?'good':'warn'}`}
  if(passed===critical.length)popToast('学習データの保存機構は正常です');else showAppNotice('error','保存機構に確認が必要です','復旧センターに安全性チェック結果を表示しました。学習を続ける前に外部バックアップを書き出してください。','データを書き出す',exportLearningData);
  refreshPwaHealth();return tests;
}
async function exportRecoveryDiagnostics(){
  const quick=quickProfileIntegrityState();let points=[];try{points=await recoveryCandidates()}catch(_e){}
  let storage=null;try{if(navigator.storage?.estimate){const x=await navigator.storage.estimate();storage={usage:x.usage||0,quota:x.quota||0}}}catch(_e){}
  let persisted=null;try{if(navigator.storage?.persisted)persisted=await navigator.storage.persisted()}catch(_e){}
  const a=(()=>{try{return currentAtomicProfile()}catch(_e){return null}})();
  const report={
    format:'fequest-diagnostics-v1',createdAt:new Date().toISOString(),appVersion:APP_VERSION,profileSchemaVersion:profile.profileSchemaVersion,
    profile:{revision:a?.revision??profileBaseRevision,integrity:quick.label,writeBlocked:profileWriteBlocked,conflictBlocked:profileConflictBlocked,recoverySource:profileRecoverySource||null,lastSaveFailure:lastProfileSaveFailure||null,lastSaveFailureAt:lastProfileSaveFailureAt?new Date(lastProfileSaveFailureAt).toISOString():null,summary:recoveryProfileMetrics(profile)},
    recovery:{usable:points.filter(x=>x.valid).length,invalid:points.filter(x=>!x.valid).length,preImportRollback:!!localStorage.getItem(PRE_IMPORT_PROFILE_KEY),preManualRollback:!!localStorage.getItem(PRE_MANUAL_RESTORE_PROFILE_KEY),corruptRawPreserved:!!localStorage.getItem(CORRUPT_PROFILE_KEY)},
    environment:{standalone:isStandalone(),online:navigator.onLine,serviceWorkerControlled:!!navigator.serviceWorker?.controller,persistentStorage:persisted,storage}
  };
  downloadTextFile(`fe-quest-diagnostics-${localDateISO(0)}.json`,JSON.stringify(report,null,2));popToast('診断レポートを書き出しました');
}
