let lastGlobalErrorAt=0;
function reportGlobalError(){
  const now=Date.now();if(now-lastGlobalErrorAt<3000)return;lastGlobalErrorAt=now;
  showAppNotice('error','画面の処理で問題が発生しました','学習データは端末に保存されています。表示がおかしい場合は再読み込みしてください。','再読み込み',()=>location.reload());
}
