    const skip=firstRunGuidedNodeV364('button','v364-secondary','ログインせずに始める');skip.type='button';skip.id='firstRunAccountSkipV364';skip.addEventListener('click',()=>advancePastFirstRunAccountV364('skipped'));root.append(skip);
