  if(finished){
    rec.done[active.task.slot]=true;
    const progress=rec.blockProgressV373?.[active.task.slot];
    if(progress?.lessonId&&!complete)profile.settings.resumeReadingV373={id:progress.lessonId,scroll:progress.scroll};
    const e=profile.settings.evidenceV373||{days:{},samples:[]};e.samples=e.samples||[];
    e.samples.push({kind:active.screen==='lesson'?'lesson':active.task.lane,lessonId:active.lessonId||null,complete,minutes:active.seconds/60,date:active.date});e.samples=e.samples.slice(-60);profile.settings.evidenceV373=e;
  }
  if(!persistProfileSilently()){popToast('保存できませんでした。画面を閉じずに再度保存してください。');return false;}
  globalThis.studyActiveV373=null;document.getElementById('studyBlockBarV373')?.remove();document.body.classList.remove('study-block-active-v373');
  if(home)showScreen('home');renderDailyPlan();return true;
