async function launchStudyBlockV373(task){
  if(globalThis.studyActiveV373?.launching)return false;
  if(globalThis.studyActiveV373&&!pauseStudyBlockV373(false))return;
  const rec=getDailyRecord(),progress=rec.blockProgressV373?.[task.slot];
  const active={task,date:dateKey(),seconds:progress?.seconds||0,recordedSeconds:progress?.seconds||0,last:performance.now(),screen:'problems',launching:true};globalThis.studyActiveV373=active;
  try{
  const pending=studySettingsV373().pendingPracticeV373||[];
  const practice=pending.find(id=>studyPracticeMinutesV373(id)<=task.minutes);
  if(practice&&!Array.isArray(progress?.remainingIds)&&!progress?.bid&&!progress?.sid){active.screen='problems';active.practiceMode='coretopic:'+practice;showScreen('problems');if(!(await startQuiz(active.practiceMode))){globalThis.studyActiveV373=null;return false;}}
  else if(task.lane==='lesson'||(task.lane==='subjectB'&&task.minutes<15)){
    const stored=studySettingsV373().resumeReadingV373;
    active.lessonId=progress?.lessonId||(task.lane==='subjectB'?'core_03_01':stored?.id||nextLessonChoice().id)||'core_03_01';active.screen='lesson';
    if(!(await resumeCourseLesson(active.lessonId)))throw new Error('protected_lesson_resume_failed');
    const y=progress?.scroll||(stored?.id===active.lessonId?stored.scroll:0)||0;requestAnimationFrame(()=>window.scrollTo(0,y));
  }else if(task.lane==='subjectB'){
    const b=progress?.bid?{mode:'trace',id:progress.bid}:progress?.sid?{mode:'security',id:progress.sid}:nextBChoice(task.minutes);
    // Timed mock exams are explicitly scheduled separately, never squeezed into
    // a short daily slot. Foundational trace/security work can stop at a boundary.
    if(['trace','security'].includes(b.mode)){
      active.screen='trace';active.bmode=b.mode;
      if(b.mode==='trace'){
        const traceResume=migrateTraceCheckpointV376(progress);
        if(traceResume?.complete)throw new Error('b_trace_checkpoint_complete');
        showScreen('trace');setBMode('trace');
        if(!(await startBExercise(b.id,traceResume))){globalThis.studyActiveV373=null;return false;}
      }else{
        const securityResume=progress?.sid?(progress.securityV376||progress.sec):null;
        if(progress?.sid&&!securityResume)throw new Error('b_security_checkpoint_missing');
        showScreen('trace');setBMode('security');
        if(!(await startSecurityScenario(b.id,securityResume))){globalThis.studyActiveV373=null;return false;}
      }
    }else{active.screen='lesson';active.lessonId='core_03_01';if(!(await resumeCourseLesson(active.lessonId)))throw new Error('protected_lesson_resume_failed');}
  }else{
    if(Array.isArray(progress?.remainingIds)&&!progress.remainingIds.length){
      active.launching=false;return pauseStudyBlockV373(true,true);
    }
    showScreen('problems');
    if(!(await startQuiz('budget:'+task.slot))){globalThis.studyActiveV373=null;return false;}

  }
  active.last=performance.now();active.launching=false;const bar=document.createElement('aside');bar.id='studyBlockBarV373';bar.setAttribute('aria-label','学習時間と途中保存');
  bar.innerHTML='<span data-status aria-live="polite"></span><button type="button" data-pause>途中保存して終える</button>';
  bar.querySelector('button').onclick=()=>pauseStudyBlockV373();document.body.append(bar);document.body.classList.add('study-block-active-v373');studyTickV373();
  return true;
  }catch(error){
    if(globalThis.studyActiveV373===active)globalThis.studyActiveV373=null;
    document.getElementById('studyBlockBarV373')?.remove();
    document.body.classList.remove('study-block-active-v373');
    popToast('学習を開始できませんでした。途中保存は残っています。');
    return false;
  }
}
function renderDailyPlan(){
  const root=document.getElementById('dailyTaskList');if(!root)return;
  const rec=getDailyRecord(),tasks=ensureTodayPlanSnapshot(),done=tasks.filter(t=>dailyTaskDone(rec,t)),next=tasks.find(t=>!dailyTaskDone(rec,t));
  const doneMinutes=done.reduce((s,t)=>s+(Number(t.minutes)||0),0),target=rec.targetMinutes||0;
  const set=(id,text)=>{const e=document.getElementById(id);if(e)e.textContent=text;};
  set('dailyProgressLabel',`${doneMinutes} / ${target}分（課題の目安）`);set('dailyDoneLabel',`${done.length} / ${tasks.length} 完了`);
  const bar=document.getElementById('dailyProgressBar');if(bar)bar.style.width=(target?Math.min(100,doneMinutes/target*100):100)+'%';
  set('todayPlanMeta',`今日の設定 ${effectiveStudyMinutes()}分・実際の所要時間は区切りごとに調整できます`);
  set('homeReadiness',calcReadiness()+'%');
  root.innerHTML='';
  const pending=tasks.filter(t=>!dailyTaskDone(rec,t)),visible=[...done,...pending.slice(0,3)];
  const draw=(parent,t)=>{const row=document.createElement('div');row.className='daily-task'+(dailyTaskDone(rec,t)?' done':'');row.innerHTML=`<div class="daily-task-icon ${t.bg||'blue'}">${t.icon||'📘'}</div><div><div class="daily-task-title">${escapeHtml(t.title)}</div><div class="daily-task-desc">${escapeHtml(t.desc||'')}</div></div><div class="daily-task-side"><div>${t.minutes}分</div><button class="daily-task-btn">${dailyTaskDone(rec,t)?'確認済み':'開始'}</button></div>`;row.querySelector('button').disabled=dailyTaskDone(rec,t);row.querySelector('button').onclick=()=>launchDailyTask(t);parent.append(row);};
  visible.forEach(t=>draw(root,t));
  if(pending.length>3){const fold=document.createElement('details');fold.innerHTML=`<summary>このあとの${pending.length-3}区切りを見る</summary>`;pending.slice(3).forEach(t=>draw(fold,t));root.append(fold);}
  if((rec.carriedMinutesV373||0)>0){const p=document.createElement('p');p.textContent=`途中までの学習 約${Math.ceil(rec.carriedMinutesV373)}分も今日の時間から差し引いています。`;root.append(p);}
  if(doneMinutes>effectiveStudyMinutes()){const p=document.createElement('p');p.textContent='設定変更前の完了分は残しています。今日は新しい課題を追加しません。';root.append(p);}
  if(!next){const p=document.createElement('p');p.textContent=effectiveStudyMinutes()===0?'今日はお休みの設定です。必要なら演習から自由に学べます。':'今日の予定はここまでです。追加で学ぶ場合は「学習」「演習」から選べます。';root.append(p);}
  const pendingPractice=studySettingsV373().pendingPracticeV373||[];if(pendingPractice.length){const p=document.createElement('p');p.className='study-help-v373';p.textContent=`読了後のテーマ演習 ${pendingPractice.length}件。次の演習は約${studyPracticeMinutesV373(pendingPractice[0])}分を確保できる区切りで行います。短い日は時間を変更して予定することもできます。`;root.append(p);}
  const exam=studySettingsV373().longExamV373;if(exam){const p=document.createElement('p');p.className='study-help-v373';p.textContent=`模試予定：${exam.date}・${exam.kind==='a'?'科目A 90分':'科目B 100分'}。${exam.date===dateKey()&&!tasks.some(t=>t.type==='scheduledExamV373')?'今日の残り時間では確保できません。「時間・受験予定を変更」から見直してください。':'「計画」で実施日を変更できます。'}`;root.append(p);}
  const stop=document.createElement('button');stop.type='button';stop.className='secondary';stop.textContent='今日はここまでにする';stop.onclick=()=>{if(globalThis.studyActiveV373&&!pauseStudyBlockV373(false))return;rec.tasks=rec.tasks.filter(t=>dailyTaskDone(rec,t));rec.targetMinutes=rec.tasks.reduce((s,t)=>s+t.minutes,0);rec.endedV373=true;if(persistProfileSilently())renderPlannerScreen();};if(next)root.append(stop);
  set('rightDailyProgress',`${done.length}/${tasks.length}完了`);set('rightDailyNext',next?`次は「${next.title}」・${next.minutes}分`:'今日の予定はここまでです');
  for(const id of ['todayResumeBtn','rightDailyAction']){const b=document.getElementById(id);if(b){b.disabled=!next;b.textContent=next?'次の区切りを始める →':'今日の予定はここまで ✓';b.onclick=next?()=>launchDailyTask(next):null;}}
}
function installStudyPlanningV373(){
  if(globalThis.studyInstalledV373)return;globalThis.studyInstalledV373=true;
  const launch=launchDailyTask;launchDailyTask=function(t){if(t.type==='studyBlockV373')return launchStudyBlockV373(t);if(t.type==='scheduledExamV373'){if(globalThis.studyActiveV373&&!pauseStudyBlockV373(false))return;globalThis.studyExamV373={slot:t.slot,kind:t.examKind,date:dateKey()};if(t.examKind==='a'){showScreen('mock');startMock('full');}else{showScreen('trace');setBMode('final');startBFinal();}return;}return launch(t);};
  const start=startQuiz;startQuiz=function(mode){
    if(globalThis.studyDeferredPracticeV373&&String(mode).startsWith('coretopic:')){
      const id=String(mode).slice(10);globalThis.studyDeferredPracticeV373=false;profile.settings.pendingPracticeV373=[...new Set([...(studySettingsV373().pendingPracticeV373||[]),id])];persistProfileSilently();showScreen('home');popToast('読了を記録しました。テーマ演習は時間のある区切りで続けます。');return;
    }globalThis.studyDeferredPracticeV373=false;return start(mode);
  };
  const finish=finishQuizSession;finishQuizSession=function(){const mode=quizMode,isBlock=String(mode).startsWith('budget:')||globalThis.studyActiveV373?.practiceMode===mode;finish();if(String(mode).startsWith('coretopic:'))profile.settings.pendingPracticeV373=(studySettingsV373().pendingPracticeV373||[]).filter(id=>id!==String(mode).slice(10));if(isBlock&&globalThis.studyActiveV373)pauseStudyBlockV373(false,true);persistProfileSilently();const next=nextUnfinishedDailyTask(),button=document.getElementById('sessionContinueDaily');if(button){button.style.display=next?'':'none';button.onclick=next?()=>launchDailyTask(next):null;}};
  const bFinish=finishBExercise;finishBExercise=function(){bFinish();if(globalThis.studyActiveV373?.bmode==='trace')pauseStudyBlockV373(false,true);};
  const secFinish=finishSecurityScenario;finishSecurityScenario=function(){secFinish();if(globalThis.studyActiveV373?.bmode==='security')pauseStudyBlockV373(false,true);};
  const mockFinish=finishMock;finishMock=function(timeup=false){mockFinish(timeup);finishScheduledExamV373('a',Math.max(0,(mockInitialSeconds-mockSeconds)/60));};
  const finalFinish=finishBFinal;finishBFinal=async function(timeup=false){const result=await finalFinish(timeup);if(result!==false)finishScheduledExamV373('b',Math.max(0,(B_FINAL_SECONDS-bFinalSeconds)/60));return result;};
  // Ending a reading block does not set lessonProgress. Normal completion keeps
  // its full original practice contract; no truncated core-topic quizzes.
  document.getElementById('lessonNext')?.addEventListener('click',()=>{const a=globalThis.studyActiveV373;if(a?.screen==='lesson'&&(LESSONS[activeLesson]?.core||lessonStep===LESSONS[activeLesson]?.pages.length-1)){if(studySettingsV373().resumeReadingV373?.id===activeLesson)delete profile.settings.resumeReadingV373;globalThis.studyDeferredPracticeV373=!!LESSONS[activeLesson]?.core;pauseStudyBlockV373(false,true);}},{capture:true});
  document.getElementById('quizSubmit')?.addEventListener('click',e=>{const a=globalThis.studyActiveV373;if(a?.screen==='problems'&&quizAnswered&&a.seconds>=a.task.minutes*60&&quizIndex<quizItems.length-1){e.stopImmediatePropagation();pauseStudyBlockV373(true,true);}},{capture:true});
  setInterval(()=>{studyTickV373();const a=globalThis.studyActiveV373;if(a&&a.date!==dateKey())pauseStudyBlockV373();},1000);
  setInterval(checkpointStudyBlockV373,15000);document.addEventListener('visibilitychange',()=>{if(document.hidden)checkpointStudyBlockV373();});window.addEventListener('pagehide',checkpointStudyBlockV373);
  const show=showScreen;showScreen=function(id,opts={}){const a=globalThis.studyActiveV373;if(a&&!a.launching&&id!==a.screen&&!pauseStudyBlockV373(false))return;return show(id,opts);};
  document.getElementById('diagFinish').textContent='診断をもとに計画を確認 →';
  if(studySettingsV373().planReviewPendingV373){firstRunGuidedSessionV364=true;document.body.classList.add('fequest-first-run-v364');originalShowScreenV364('diagnostic',{instant:true});globalThis.studyPlanReviewV373=false;finishGuidedDiagnosticV364();}
  const settingsLink=document.createElement('button');settingsLink.type='button';settingsLink.className='secondary';settingsLink.id='openStudySettingsV373';settingsLink.textContent='時間・受験予定を変更';settingsLink.onclick=()=>{setPlanDetailsOpen(true);document.getElementById('learningSettingsCard')?.scrollIntoView({block:'start',behavior:'smooth'});};document.getElementById('planFocusAction')?.parentElement.append(settingsLink);
  renderPlannerScreen();
}
function studyPracticeMinutesV373(id){return Math.ceil(QUESTION_BANK.filter(q=>q.coreTopicId===id&&isCoreTopicImmediatePracticeQuestion(q)).length*studyEstimateV373().questionMinutes+2);}
function studyScheduledExamV373(budget,rec){
  const exam=studySettingsV373().longExamV373;if(!exam||exam.date!==dateKey())return null;
  const slot='v373-exam-'+exam.kind;if(rec.done?.[slot])return null;
  const days=examDaysRemaining();if(days!=null&&days>=0&&days<=3)return null;
  const minutes=exam.kind==='a'?90:100;if(budget<minutes)return null;
  return {type:'scheduledExamV373',slot,examKind:exam.kind,minutes,title:exam.kind==='a'?'科目A フル模試':'科目B 総合実戦',desc:'予定した模試です。全時間を確保してから開始します。',icon:'📝',bg:'purple'};
}
function finishScheduledExamV373(kind,minutes){
  const exam=globalThis.studyExamV373;if(!exam||exam.kind!==kind||exam.date!==dateKey())return;
  const rec=getDailyRecord();if(!rec.done[exam.slot]){rec.done[exam.slot]=true;addActivity(minutes,'exam');}
  globalThis.studyExamV373=null;renderPlannerScreen();
}

